/**
 * 静态站点托管：把 apps/web 静态导出产物（out/）经本服务同域提供。
 * - /_next/static/* 由 out/_next/static 读取，immutable 缓存
 * - 页面路径映射 <path>.html（/ → index.html），防目录穿越
 * - 目录由环境变量 STATIC_DIR 指定（standalone 部署时为 server.js 同级的 out/）
 * - 中间件仍先行：未登录页面照常 307 → /login
 */
import { NextResponse } from "next/server";
import { createReadStream, existsSync, statSync } from "node:fs";
import { join, normalize, extname } from "node:path";
import { Readable } from "node:stream";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
  ".gif": "image/gif",
  ".avif": "image/avif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".webmanifest": "application/manifest+json",
  ".map": "application/json",
};

function staticDir(): string {
  return process.env.STATIC_DIR || join(process.cwd(), "out");
}

function fileStream(path: string): ReadableStream | null {
  if (!existsSync(path) || !statSync(path).isFile()) return null;
  // Readable.toWeb 的类型与 Next 期待的 ReadableStream 兼容（运行时为 WHATWG 流）
  return Readable.toWeb(createReadStream(path)) as unknown as ReadableStream;
}

function respond(path: string, req: Request): NextResponse {
  const immutable = path.includes(`${join("_next", "static")}`) || path.includes("_next/static");
  const stream = fileStream(path);
  if (!stream) return new NextResponse(null, { status: 404 });
  return new NextResponse(stream, {
    headers: {
      "Content-Type": MIME[extname(path).toLowerCase()] ?? "application/octet-stream",
      "Cache-Control": immutable ? "public, max-age=31536000, immutable" : "no-cache",
      ETag: `"${statSync(path).size}-${statSync(path).mtimeMs}"`,
    },
  });
}

async function GET(req: Request) {
  const { pathname } = new URL(req.url);
  const dir = staticDir();
  const clean = normalize(decodeURIComponent(pathname)).replace(/\\/g, "/");
  if (clean.includes("..")) return new NextResponse(null, { status: 400 });

  const candidates: string[] = [];
  if (clean === "/" || clean === "") {
    candidates.push(join(dir, "index.html"));
  } else if (clean.endsWith("/")) {
    candidates.push(join(dir, clean, "index.html"), join(dir, clean.slice(0, -1) + ".html"));
  } else {
    candidates.push(join(dir, clean), join(dir, clean + ".html"), join(dir, clean, "index.html"));
  }
  for (const c of candidates) {
    if (existsSync(c) && statSync(c).isFile()) return respond(c, req);
  }
  // 动态段壳页回退：contacts/[id]、spaces/[id] 静态导出只产出 __shell__.html，任意 id 复用它（真实 id 由客户端 useParams 从 URL 读取）
  const shell = clean.match(/^\/?(contacts|spaces)\/[^/]+\/?$/);
  if (shell) {
    const p = join(dir, shell[1], "__shell__.html");
    if (existsSync(p)) return respond(p, req);
  }
  const notFound = join(dir, "404.html");
  if (existsSync(notFound)) {
    return new NextResponse(Readable.toWeb(createReadStream(notFound)) as unknown as ReadableStream, {
      status: 404,
      headers: { "Content-Type": "text/html; charset=utf-8" },
    });
  }
  return new NextResponse(null, { status: 404 });
}

export { GET };

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

/** PATCH /api/accounts/:id —— 改名/图标/期初余额/排序/归档 */
export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const body = (await req.json().catch(() => ({}))) as {
    name?: string;
    icon?: string;
    openingBalanceCents?: number;
    archived?: boolean;
  };

  const sets: string[] = [];
  const vals: unknown[] = [];
  if (body.name?.trim()) {
    vals.push(body.name.trim());
    sets.push(`name = $${vals.length}`);
  }
  if (body.icon?.trim()) {
    vals.push(body.icon.trim());
    sets.push(`icon = $${vals.length}`);
  }
  if (body.openingBalanceCents != null) {
    if (!Number.isInteger(body.openingBalanceCents)) {
      return NextResponse.json({ error: "期初余额需为整数（分）" }, { status: 400 });
    }
    vals.push(body.openingBalanceCents);
    sets.push(`opening_balance_cents = $${vals.length}`);
  }
  if (body.archived != null) {
    vals.push(body.archived);
    sets.push(`archived = $${vals.length}`);
  }
  if (sets.length === 0) return NextResponse.json({ error: "没有可更新的字段" }, { status: 400 });
  vals.push(id, user.id);

  try {
    const updated = (
      await pool.query(
        `update accounts set ${sets.join(", ")}
         where id = $${vals.length - 1} and user_id = $${vals.length} returning *`,
        vals,
      )
    ).rows[0];
    if (!updated) return NextResponse.json({ error: "账户不存在" }, { status: 404 });
    return NextResponse.json({ account: updated });
  } catch (e) {
    if (String(e).includes("accounts_user_id_name_key")) {
      return NextResponse.json({ error: "已存在同名账户" }, { status: 400 });
    }
    return NextResponse.json({ error: String(e) }, { status: 500 });
  }
}

/** DELETE /api/accounts/:id —— 归档账户（不物理删除，历史流水完整保留） */
export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const updated = (
    await pool.query(
      `update accounts set archived = true where id = $1 and user_id = $2 returning id`,
      [id, user.id],
    )
  ).rows[0];
  if (!updated) return NextResponse.json({ error: "账户不存在" }, { status: 404 });
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/accounts —— 全部账户（含动态余额） */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { rows } = await pool.query(
    `select a.id, a.name, a.icon, a.sort_order, a.opening_balance_cents,
            (a.opening_balance_cents + coalesce((
               select sum(case when t.direction = 'out' then -t.amount_cents else t.amount_cents end)
               from transactions t
               where t.account_id = a.id and t.is_draft = false
             ), 0))::int as balance_cents
     from accounts a
     where a.user_id = $1 and a.archived = false
     order by a.sort_order, a.created_at`,
    [user.id],
  );
  return NextResponse.json({ accounts: rows });
}

/** POST /api/accounts —— 新建账户 {name, icon?, openingBalanceCents?} */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const body = (await req.json().catch(() => ({}))) as {
    name?: string;
    icon?: string;
    openingBalanceCents?: number;
  };
  const name = body.name?.trim();
  if (!name) return NextResponse.json({ error: "账户名称必填" }, { status: 400 });
  if (name.length > 20) return NextResponse.json({ error: "账户名称过长" }, { status: 400 });
  const opening = body.openingBalanceCents ?? 0;
  if (!Number.isInteger(opening)) return NextResponse.json({ error: "期初余额需为整数（分）" }, { status: 400 });

  try {
    const created = (
      await pool.query(
        `insert into accounts (user_id, name, icon, opening_balance_cents, sort_order)
         values ($1, $2, $3, $4, (select coalesce(max(sort_order), 0) + 1 from accounts where user_id = $1))
         returning *`,
        [user.id, name, body.icon?.trim() || "💳", opening],
      )
    ).rows[0];
    return NextResponse.json({ account: created });
  } catch (e) {
    if (String(e).includes("accounts_user_id_name_key")) {
      return NextResponse.json({ error: "已存在同名账户" }, { status: 400 });
    }
    return NextResponse.json({ error: String(e) }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

/** PATCH /api/activities/:id —— 修改分类（名称/图标/颜色/默认时长） */
export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const body = (await req.json().catch(() => ({}))) as {
    name?: string;
    icon?: string;
    color?: string;
    defaultMin?: number;
  };

  const sets: string[] = [];
  const vals: unknown[] = [];
  if (body.name != null) { vals.push(body.name.trim()); sets.push(`name = $${vals.length}`); }
  if (body.icon != null) { vals.push(body.icon.trim() || "🏷"); sets.push(`icon = $${vals.length}`); }
  if (body.color != null && /^#[0-9a-fA-F]{6}$/.test(body.color)) {
    vals.push(body.color); sets.push(`color = $${vals.length}`);
  }
  if (body.defaultMin != null) {
    vals.push(Math.min(Math.max(body.defaultMin, 5), 720));
    sets.push(`default_min = $${vals.length}`);
  }
  if (sets.length === 0) return NextResponse.json({ error: "没有可更新的字段" }, { status: 400 });
  vals.push(id, user.id);

  try {
    const updated = (
      await pool.query(
        `update activities set ${sets.join(", ")}
         where id = $${vals.length - 1} and user_id = $${vals.length} returning *`,
        vals,
      )
    ).rows[0];
    if (!updated) return NextResponse.json({ error: "分类不存在" }, { status: 404 });
    return NextResponse.json({ activity: updated });
  } catch (e) {
    if (String(e).includes("activities_user_id_name_key")) {
      return NextResponse.json({ error: "已存在同名分类" }, { status: 400 });
    }
    return NextResponse.json({ error: String(e) }, { status: 500 });
  }
}

/** DELETE /api/activities/:id —— 删除自定义分类（其时间块/待办归入"其他"）；预设分类不可删 */
export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const client = await pool.connect();
  try {
    await client.query("begin");
    const act = (
      await client.query(
        `select * from activities where id = $1 and user_id = $2`,
        [id, user.id],
      )
    ).rows[0];
    if (!act) {
      await client.query("rollback");
      return NextResponse.json({ error: "分类不存在" }, { status: 404 });
    }
    if (act.is_preset) {
      await client.query("rollback");
      return NextResponse.json({ error: "预设分类不可删除（可修改名称/图标/颜色）" }, { status: 400 });
    }
    await client.query(`update time_blocks set activity_id = 'other' where activity_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`update todos set activity_id = 'other' where activity_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from activities where id = $1 and user_id = $2`, [id, user.id]);
    await client.query("commit");
    return NextResponse.json({ ok: true, reassigned: true });
  } catch (e) {
    await client.query("rollback");
    return NextResponse.json({ error: String(e) }, { status: 500 });
  } finally {
    client.release();
  }
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { seedPresetActivities } from "@/lib/seed";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/activities —— 全部分类（空则自愈播种，兜底早期注册的存量账号） */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  let { rows } = await pool.query(
    `select * from activities where user_id = $1 order by sort_order, created_at`,
    [user.id],
  );
  if (rows.length === 0) {
    await seedPresetActivities(user.id);
    ({ rows } = await pool.query(
      `select * from activities where user_id = $1 order by sort_order, created_at`,
      [user.id],
    ));
  }
  return NextResponse.json({ activities: rows });
}

/** POST /api/activities —— 新增自定义分类 */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const body = (await req.json().catch(() => ({}))) as {
    name?: string;
    icon?: string;
    color?: string;
    defaultMin?: number;
  };
  const name = body.name?.trim();
  if (!name) return NextResponse.json({ error: "名称必填" }, { status: 400 });

  try {
    const created = (
      await pool.query(
        `insert into activities (id, user_id, name, icon, color, default_min, sort_order, is_preset)
         values (gen_random_uuid()::text, $1, $2, $3, $4, $5,
                 (select coalesce(max(sort_order), 0) + 1 from activities where user_id = $1), false)
         returning *`,
        [
          user.id,
          name,
          body.icon?.trim() || "🏷",
          /^#[0-9a-fA-F]{6}$/.test(body.color ?? "") ? body.color : "#64748b",
          Math.min(Math.max(body.defaultMin ?? 30, 5), 720),
        ],
      )
    ).rows[0];
    return NextResponse.json({ activity: created });
  } catch (e) {
    if (String(e).includes("activities_user_id_name_key")) {
      return NextResponse.json({ error: "已存在同名分类" }, { status: 400 });
    }
    return NextResponse.json({ error: String(e) }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { envJevMode, getJevMode, setJevMode, type JevModeValue } from "@/lib/ai-mode";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const VALID: JevModeValue[] = ["off", "shadow", "on"];

/** GET /api/admin/ai-mode —— 当前生效的调用模式 + env 默认值（UI 标注用） */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });
  const mode = await getJevMode();
  return NextResponse.json({ mode, envDefault: envJevMode(), takeoverAvailable: true });
}

/** PUT /api/admin/ai-mode {mode} —— 切换调用模式，保存即生效（清缓存）。
 * off=全 GLM；shadow=GLM 行为不变 + Jev 影子对照（仅审计）；
 * on=实时接管（3-D：空间分类切 Jev + 五域混合引擎，Jev 失败自动回落全量 GLM）。 */
export async function PUT(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });
  const { mode } = (await req.json().catch(() => ({}))) as { mode?: string };
  if (!VALID.includes(mode as JevModeValue)) {
    return NextResponse.json({ error: "mode 需为 off/shadow/on" }, { status: 400 });
  }
  await setJevMode(mode as JevModeValue, user.id);
  return NextResponse.json({ ok: true, mode });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getAdminUser, getCurrentUser } from "@/lib/auth";
import { MODULES, listUserModules, type ModuleKey } from "@/lib/modules";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const VALID = new Set<string>(MODULES);

/** GET /api/admin/grants —— 全部用户的模块授权矩阵（叠加 billing/users 的用户列表用） */
export async function GET() {
  const admin = await getAdminUser();
  if (!admin) {
    const user = await getCurrentUser();
    return NextResponse.json({ error: user ? "仅管理员" : "未登录" }, { status: user ? 403 : 401 });
  }
  const { rows } = await pool.query(
    `select user_id, module, granted_by, granted_at from user_module_grants order by granted_at desc`,
  );
  return NextResponse.json({ grants: rows });
}

/** POST /api/admin/grants {userId, module} —— 授权（幂等） */
export async function POST(req: Request) {
  const admin = await getAdminUser();
  if (!admin) {
    const user = await getCurrentUser();
    return NextResponse.json({ error: user ? "仅管理员" : "未登录" }, { status: user ? 403 : 401 });
  }
  const { userId, module } = (await req.json().catch(() => ({}))) as {
    userId?: string;
    module?: string;
  };
  if (!userId || !module || !VALID.has(module)) {
    return NextResponse.json({ error: "userId 与 module（debt/trade_review）必填" }, { status: 400 });
  }
  const exists = await pool.query(`select 1 from profiles where id = $1`, [userId]);
  if (!exists.rows[0]) return NextResponse.json({ error: "用户不存在" }, { status: 404 });
  await pool.query(
    `insert into user_module_grants (user_id, module, granted_by)
     values ($1,$2,$3) on conflict (user_id, module) do nothing`,
    [userId, module, admin.id],
  );
  return NextResponse.json({ ok: true, modules: await listUserModules(userId, "user") });
}

/** DELETE /api/admin/grants?userId=&module= —— 撤销授权（幂等） */
export async function DELETE(req: Request) {
  const admin = await getAdminUser();
  if (!admin) {
    const user = await getCurrentUser();
    return NextResponse.json({ error: user ? "仅管理员" : "未登录" }, { status: user ? 403 : 401 });
  }
  const { searchParams } = new URL(req.url);
  const userId = searchParams.get("userId");
  const module = searchParams.get("module");
  if (!userId || !module || !VALID.has(module)) {
    return NextResponse.json({ error: "userId 与 module（debt/trade_review）必填" }, { status: 400 });
  }
  await pool.query(`delete from user_module_grants where user_id = $1 and module = $2`, [
    userId,
    module,
  ]);
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { generateInviteCode } from "@/lib/auth-crypto";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/admin/invites —— 管理员查看邀请码（最近 50 个；自 auth/invites 迁移，旧地址保留别名） */
export async function GET() {
  const admin = await getAdminUser();
  if (!admin) return NextResponse.json({ error: "仅管理员可管理邀请码" }, { status: 403 });
  const { rows } = await pool.query(
    `select i.code, i.used_by, i.expires_at, i.created_at, p.nickname as used_by_name
     from invite_codes i left join profiles p on p.id = i.used_by
     order by i.created_at desc limit 50`,
  );
  return NextResponse.json({ invites: rows });
}

/** POST /api/admin/invites {days?: 7} —— 管理员生成邀请码 */
export async function POST(req: Request) {
  const admin = await getAdminUser();
  if (!admin) return NextResponse.json({ error: "仅管理员可管理邀请码" }, { status: 403 });
  const { days = 7 } = (await req.json().catch(() => ({}))) as { days?: number };
  const code = generateInviteCode();
  const expires = days > 0 ? new Date(Date.now() + days * 86_400_000) : null;
  const { rows } = await pool.query(
    `insert into invite_codes (code, created_by, expires_at) values ($1,$2,$3) returning code, expires_at`,
    [code, admin.id, expires],
  );
  return NextResponse.json({ ok: true, invite: rows[0] });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { chat } from "@shiguangri/ai";
import { PROMPT_KEYS, PROMPT_META, defaultPrompt, getPrompt, getPromptBundle, assembleUserPrompt, type PromptKey } from "@/lib/prompts";
import { writeAuditRecord } from "@/lib/audit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/admin/prompts/[key]/optimize {hint?} —— AI 协助优化（v1.1）
 * 用 prompt_optimizer 元 prompt 组装：用途 + 契约约束 + 当前内容 + 意图 → chat()
 * 纯建议：不落库、不写版本、不动缓存；记 audit_logs stage='prompt_optimize'
 */
export async function POST(req: Request, ctx: { params: Promise<{ key: string }> }) {
  const startedAt = Date.now();
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  const { hint } = (await req.json().catch(() => ({}))) as { hint?: string };
  const target = (await getPrompt(key as PromptKey)).slice(0, 30_000);
  // 优化器自身也走三件套装配（3-A：prompt_optimizer 的 user 模板/注入可在后台调）
  const optBundle = await getPromptBundle("prompt_optimizer");
  const contract = CONTRACT_HINTS[key as PromptKey]
    ? `【必须保留的契约约束】\n${CONTRACT_HINTS[key as PromptKey]}`
    : "【必须保留的契约约束】\n保持原文中的输出 JSON 结构、字段名、枚举值与占位符完全不变。";

  const userPrompt = assembleUserPrompt("prompt_optimizer", optBundle, {
    purpose: `${PROMPT_META[key as PromptKey].title}（key=${key}）——「拾光」系统的 AI 提示词`,
    contract,
    current: target,
    intent: hint?.trim() ? hint.trim().slice(0, 500) : "（无，按专家判断全面优化）",
  });

  const t0 = Date.now();
  try {
    const suggestion = await chat({
      system: optBundle.system,
      user: userPrompt,
      temperature: 0.3,
      maxTokens: 8000,
      timeoutMs: 60_000,
      onUsage: (u) => {
        void writeAuditRecord({
          userId: user.id, entryId: null, stage: "prompt_optimize",
          model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "prompt-optimize",
          latencyMs: Date.now() - t0, ok: true,
          promptTokens: u.prompt_tokens, completionTokens: u.completion_tokens,
        });
      },
    });
    const cleaned = suggestion
      .trim()
      .replace(/^```(?:\w*)\n?/, "")
      .replace(/\n?```$/, "")
      .trim();
    if (!cleaned) throw new Error("优化结果为空");
    // 弱模型偶发复述输入块（【用途】…【当前 prompt】…）——启发式剥离，只留正文
    const echoIdx = cleaned.lastIndexOf("【当前 prompt】");
    const body = echoIdx >= 0 ? cleaned.slice(echoIdx + "【当前 prompt】".length).trim() : cleaned;
    if (!body) throw new Error("优化结果为空");
    return NextResponse.json({ ok: true, suggestion: body, latencyMs: Date.now() - startedAt });
  } catch (e) {
    void writeAuditRecord({
      userId: user.id, entryId: null, stage: "prompt_optimize",
      model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "prompt-optimize",
      latencyMs: Date.now() - t0, ok: false, error: String(e).slice(0, 300),
    });
    return NextResponse.json({ error: `AI 优化失败：${e instanceof Error ? e.message : String(e).slice(0, 200)}` }, { status: 502 });
  }
}

/** 各 key 的契约要点：拼进优化器输入，硬约束 LLM 不许改输出结构 */
const CONTRACT_HINTS: Partial<Record<PromptKey, string>> = {
  extract_full: `输出 JSON 结构（reasoning + schedule/todo/finance/mood/diet/people/ambiguity）与全部字段名、枚举（activity 9 值、meal 6 值、direction out/in、category 7 值）不变；用户消息中的占位（当前时间/分类对照/联系人名单/「用户的话」）由 buildExtractUserPrompt 拼装，prompt 中对它们的引用描述不能失效。`,
  extract_domain_schedule: `只输出 {"reasoning","schedule":{...}}，字段与枚举（activity 9 值）不变。`,
  extract_domain_todo: `只输出 {"reasoning","todo":{"applicable","due","confidence"}} 结构不变。`,
  extract_domain_finance: `只输出 {"reasoning","finance":{...}}，direction/category 枚举不变。`,
  extract_domain_mood: `只输出 {"reasoning","mood":{"label","score","confidence"}} 结构不变。`,
  extract_domain_diet: `只输出 {"reasoning","diet":{...}}，meal 枚举（早餐/午餐/晚餐/加餐/夜宵/未知）与 items 结构不变。`,
  extract_domain_people: `只输出 {"reasoning","people":[{"name","event"}]} 结构不变。`,
  review_day: `输出 JSON 固定三键 summary/highlights/suggestions 及字数上限不变。`,
  review_week: `输出 JSON 固定三键 summary/highlights/suggestions 及字数上限不变。`,
  review_month: `输出 JSON 四键 summary/sections/highlights/suggestions（sections 为 {title,text} 数组）不变。`,
  review_year: `输出 JSON 四键 summary/sections/highlights/suggestions（sections 为 {title,text} 数组）不变。`,
  profile_merge: `输出 JSON 固定四键 habits/preferences/patterns/facts（字符串数组）不变。`,
  space_classify: `只输出 {"spaceId":string|null,"confidence":number}；spaceId 必须来自候选列表或 null。`,
  todo_decompose: `只输出 {"reasoning","actions":[{"title"}]}；title ≤30 字；条数上限 10。`,
  action_decompose: `只输出 {"reasoning","actions":[{"title"}]}；title ≤30 字；条数上限 3。`,
  prompt_optimizer: `本 key 是优化器元 prompt 自身：优化时必须保留"硬性规则"与"仅输出全文"的输出契约。`,
};

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { ACTIVITY_NAMES, toCstWallClock } from "@shiguangri/ai";
import { PROMPT_KEYS, getPromptBundle, assembleUserPrompt, getPrompt, type PromptKey } from "@/lib/prompts";
import { writeAuditRecord } from "@/lib/audit";
import { listContactNames } from "@/lib/analyze";
import { loadProfileBlock } from "@/lib/review-input";
import { buildReviewCtx, type ReviewKind } from "@/lib/review-ctx";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/admin/prompts/[key]/preview {sample?, period?} —— 装配预览（REQ-003 FR-1.5）
 * 按「当前生效三件套」走与线上同一条装配逻辑，返回最终 user 输入全文。
 * 不调 LLM、零 token；结果不落库；audit 仅记 stage='prompt_preview' 计数，不记内容。
 * sample 缺省时取管理员最近真实数据；period 供复盘类指定期间（日/周 YYYY-MM-DD、月 YYYY-MM、年 YYYY）。
 */
export async function POST(req: Request, ctx: { params: Promise<{ key: string }> }) {
  const startedAt = Date.now();
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  const { sample, period } = (await req.json().catch(() => ({}))) as { sample?: string; period?: string };
  const bundle = await getPromptBundle(key as PromptKey);
  const cfg = bundle.config;
  const sampleText = sample?.trim() || null;

  const latestEntry = async (): Promise<string | null> => {
    const { rows } = await pool.query(
      `select raw_text from entries where user_id = $1 order by created_at desc limit 1`,
      [user.id],
    );
    return rows[0]?.raw_text ?? null;
  };

  let userPrompt = "";
  let ctxOut: Record<string, string> = {};

  if (key === "extract_full" || key.startsWith("extract_domain_")) {
    const contactsOn = cfg.inject.contactList ?? false;
    const contactNames = contactsOn ? await listContactNames(user.id, cfg.caps.contactCount ?? 100) : [];
    const catList =
      key === "extract_full" && cfg.inject.catList
        ? (Object.keys(ACTIVITY_NAMES) as (keyof typeof ACTIVITY_NAMES)[])
            .slice(0, cfg.caps.catCount ?? 50)
            .map((k) => `${k}=${ACTIVITY_NAMES[k]}`)
            .join("、")
        : "";
    const contactList =
      contactsOn && contactNames.length
        ? `\n已有联系人（人物识别时称呼对齐到名单原文）：${contactNames.join("、")}`
        : "";
    const text = sampleText ?? (await latestEntry()) ?? "（管理员名下暂无动态，可粘贴样例话术）";
    ctxOut = { nowCst: toCstWallClock(new Date()), catList, contactList, text };
    userPrompt = assembleUserPrompt(key as PromptKey, bundle, ctxOut);
  } else if (key.startsWith("review_")) {
    const kind = key.slice("review_".length) as ReviewKind;
    const built = await buildReviewCtx(
      user.id,
      kind,
      {
        date: kind === "day" || kind === "week" ? period || undefined : undefined,
        month: kind === "month" ? period || undefined : undefined,
        year: kind === "year" ? period || undefined : undefined,
      },
      bundle,
    );
    ctxOut = built.ctx;
    userPrompt = built.userPrompt;
  } else if (key === "todo_decompose" || key === "action_decompose") {
    const isAction = key === "action_decompose";
    const todo = (
      await pool.query(
        isAction
          ? `select id, title, note, space_id, parent_todo_id from todos where user_id = $1 and kind = 'action' and status = 'pending' order by created_at desc limit 1`
          : `select id, title, note, space_id from todos where user_id = $1 and parent_todo_id is null and status = 'pending' order by created_at desc limit 1`,
        [user.id],
      )
    ).rows[0];
    const title = todo?.title ?? sampleText ?? "（示例）整理书桌并归位物品";
    const note = todo?.note ?? null;
    const space = todo?.space_id
      ? (await pool.query(`select name, description from goal_spaces where id = $1`, [todo.space_id])).rows[0]
      : null;
    const parent =
      isAction && todo?.parent_todo_id
        ? (await pool.query(`select title, note from todos where id = $1`, [todo.parent_todo_id])).rows[0]
        : null;
    // 去重清单口径与拆解路由一致（按同父兄弟 / 独立行动全体 / 顶层 todo 的子行动）
    const existingTitles = todo
      ? isAction
        ? todo.parent_todo_id
          ? (
              await pool.query(
                `select title from todos where user_id = $1 and parent_todo_id = $2 and kind = 'action' and id <> $3 and status = 'pending' order by sort`,
                [user.id, todo.parent_todo_id, todo.id],
              )
            ).rows.map((r) => r.title)
          : (
              await pool.query(
                `select title from todos where user_id = $1 and parent_todo_id is null and kind = 'action' and id <> $2 and status = 'pending' order by sort`,
                [user.id, todo.id],
              )
            ).rows.map((r) => r.title)
        : (
            await pool.query(
              `select title from todos where user_id = $1 and parent_todo_id = $2 and kind = 'action' and status = 'pending' order by sort`,
              [user.id, todo.id],
            )
          ).rows.map((r) => r.title)
      : [];
    const listed = cfg.inject.existingBlock ? existingTitles.slice(0, cfg.caps.existingCount ?? 30) : [];
    const profile = cfg.inject.profileBlock ? await loadProfileBlock(user.id) : null;
    ctxOut = {
      todoBlock: `${isAction ? `所属 todo：${parent?.title ?? ""}` : `todo：${title}`}${note || (isAction ? parent?.note : null) ? `\n相关描述：${note || parent?.note}` : ""}`,
      spaceBlock: cfg.inject.spaceBlock && space ? `所属空间：${space.name}${space.description ? `（${space.description}）` : ""}` : "",
      existingBlock: listed.length
        ? `已有行动（禁止生成语义重复项）：\n${listed.map((t) => `- ${t}`).join("\n")}`
        : cfg.inject.existingBlock
          ? "已有行动：无"
          : "",
      profileBlock: profile ? `用户画像（供参考）：\n${profile}` : "",
      target: isAction ? `「${title}」` : "上述 todo",
      modeSuffix: "",
    };
    userPrompt = assembleUserPrompt(key as PromptKey, bundle, ctxOut);
  } else if (key === "space_classify") {
    const { rows: spaces } = await pool.query(
      `select id, name, description from goal_spaces where user_id = $1 and status = 'active' order by sort limit ${cfg.caps.spaceCount ?? 20}`,
      [user.id],
    );
    const candidates = spaces
      .map((s) => `- ${s.id}：${s.name}${s.description ? `（${s.description}）` : ""}`)
      .join("\n");
    const text = (sampleText ?? (await latestEntry()) ?? "（示例）今天背了两百个单词").slice(0, 500);
    ctxOut = { candidates, text };
    userPrompt = assembleUserPrompt("space_classify", bundle, ctxOut);
  } else {
    // prompt_optimizer：current 为管理员粘贴的目标 prompt（缺省取当前生效的 system）
    const contract =
      "【必须保留的契约约束】\n保持原文中的输出 JSON 结构、字段名、枚举值与占位符完全不变。";
    ctxOut = {
      purpose: `示例（key=${key}）——「拾光」系统的 AI 提示词`,
      contract,
      current: sampleText ?? (await getPrompt(key as PromptKey)),
      intent: "（无，按专家判断全面优化）",
    };
    userPrompt = assembleUserPrompt("prompt_optimizer", bundle, ctxOut);
  }

  void writeAuditRecord({
    userId: user.id, entryId: null, stage: "prompt_preview",
    model: null, engine: "prompt-preview",
    latencyMs: Date.now() - startedAt, ok: true,
  });
  return NextResponse.json({ ok: true, userPrompt, ctx: ctxOut, config: bundle.config });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { PROMPT_KEYS, invalidatePrompts, type PromptKey } from "@/lib/prompts";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

interface VersionPayload {
  system?: string;
  userTemplate?: string | null;
  contextConfig?: { inject?: Record<string, boolean>; caps?: Record<string, number> } | null;
}

/**
 * POST /api/admin/prompts/[key]/restore {versionId} —— 回滚到历史版本（记 restored_from，保存即生效）。
 * 3-A：优先取版本 payload（三件套整体回滚：system + user 模板 + 注入配置）；
 * 老版本（无 payload）仅回滚 system content，user 模板/配置保持当前覆盖不变。
 */
export async function POST(req: Request, ctx: { params: Promise<{ key: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  const { versionId } = (await req.json().catch(() => ({}))) as { versionId?: number };
  if (!versionId) return NextResponse.json({ error: "缺少 versionId" }, { status: 400 });

  const ver = (
    await pool.query(`select id, content, payload from ai_prompt_versions where id = $1 and key = $2`, [versionId, key])
  ).rows[0];
  if (!ver) return NextResponse.json({ error: "版本不存在" }, { status: 404 });

  const payload = (ver.payload ?? null) as VersionPayload | null;
  const content = payload?.system ?? ver.content;
  const tpl = payload ? (payload.userTemplate ?? null) : null;
  const cfg = payload ? (payload.contextConfig ?? null) : null;

  // 无 payload 的老版本：仅回滚 system，user 模板/配置保留当前覆盖
  let finalTpl: string | null = tpl;
  let finalCfg: Record<string, unknown> | null = cfg;
  if (!payload) {
    const cur = (await pool.query(`select user_template, context_config from ai_prompts where key = $1`, [key])).rows[0];
    finalTpl = (cur?.user_template as string | null) ?? null;
    finalCfg = (cur?.context_config as Record<string, unknown> | null) ?? null;
  }

  const { rows } = await pool.query(
    `insert into ai_prompts (key, content, enabled, user_template, context_config, updated_by, updated_at)
     values ($1,$2,true,$3,$4::jsonb,$5,now())
     on conflict (key) do update set content = $2, enabled = true, user_template = $3, context_config = $4::jsonb, updated_by = $5, updated_at = now()
     returning key, content, enabled, user_template, context_config, updated_at`,
    [key, content, finalTpl, finalCfg ? JSON.stringify(finalCfg) : null, user.id],
  );
  await pool.query(
    `insert into ai_prompt_versions (key, content, payload, restored_from, created_by) values ($1,$2,$3::jsonb,$4,$5)`,
    [key, content, JSON.stringify({ system: content, userTemplate: finalTpl, contextConfig: finalCfg }), ver.id, user.id],
  );
  invalidatePrompts(key as PromptKey);
  return NextResponse.json({ ok: true, prompt: rows[0] });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { PROMPT_KEYS, invalidatePrompts, type PromptKey } from "@/lib/prompts";
import { AI_INPUT_REGISTRY, validateUserTemplate } from "@/lib/ai-inputs";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type CtxConfig = { inject?: Record<string, boolean>; caps?: Record<string, number> };

/**
 * PUT /api/admin/prompts/[key] —— 保存三件套覆盖（REQ-003 3-A）：system + user 模板 + 注入配置。
 * 校验：模板占位符完整性（缺失/未知 → 400 列明）、caps 整数且在注册表范围、required 注入不可为 false。
 * 保存即生效（upsert + 清缓存）；版本快照写 payload 三件套（content 列保留兼容）。
 */
export async function PUT(req: Request, ctx: { params: Promise<{ key: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  const spec = AI_INPUT_REGISTRY[key as PromptKey];
  const { content, enabled = true, remark, userTemplate, contextConfig } = (await req.json().catch(() => ({}))) as {
    content?: string; enabled?: boolean; remark?: string | null;
    userTemplate?: string | null; contextConfig?: CtxConfig | null;
  };
  if (typeof content !== "string" || !content.trim()) {
    return NextResponse.json({ error: "内容不能为空" }, { status: 400 });
  }
  if (content.length > 50_000) {
    return NextResponse.json({ error: `内容过长（${content.length}/50000 字）` }, { status: 400 });
  }

  // ---- user 模板校验（未传 = 保持原覆盖；传空串/null = 回归代码默认） ----
  let tplToSave: string | null = null;
  if (userTemplate !== undefined) {
    if (userTemplate === null || !userTemplate.trim()) {
      tplToSave = null;
    } else {
      if (userTemplate.length > 50_000) {
        return NextResponse.json({ error: `user 模板过长（${userTemplate.length}/50000 字）` }, { status: 400 });
      }
      const { missing, unknown } = validateUserTemplate(key as PromptKey, userTemplate);
      if (missing.length || unknown.length) {
        return NextResponse.json(
          {
            error: `user 模板占位符校验未通过${missing.length ? `：缺失 ${missing.map((x) => `{${x}}`).join("、")}` : ""}${unknown.length ? `：未知 ${unknown.map((x) => `{${x}}`).join("、")}` : ""}`,
            missing,
            unknown,
          },
          { status: 400 },
        );
      }
      tplToSave = userTemplate;
    }
  }

  // ---- 注入配置校验（开关仅限注册表项且 required 不可关；caps 整数且在范围内） ----
  let cfgToSave: { inject: Record<string, boolean>; caps: Record<string, number> } | null = null;
  if (contextConfig !== undefined) {
    if (contextConfig === null) {
      cfgToSave = null;
    } else {
      const inject: Record<string, boolean> = {};
      if (contextConfig.inject) {
        for (const [k, v] of Object.entries(contextConfig.inject)) {
          const def = spec.injects.find((i) => i.key === k);
          if (!def) return NextResponse.json({ error: `未知的注入项：${k}` }, { status: 400 });
          if (def.required && v === false) {
            return NextResponse.json({ error: `必需注入项「${def.label}」不可关闭` }, { status: 400 });
          }
          if (typeof v === "boolean") inject[k] = v;
        }
      }
      const caps: Record<string, number> = {};
      if (contextConfig.caps) {
        for (const [k, v] of Object.entries(contextConfig.caps)) {
          const def = spec.caps.find((c) => c.key === k);
          if (!def) return NextResponse.json({ error: `未知的参数：${k}` }, { status: 400 });
          if (typeof v !== "number" || !Number.isFinite(v) || v < def.min || v > def.max) {
            return NextResponse.json({ error: `参数「${def.label}」需为 ${def.min}~${def.max} 的数值` }, { status: 400 });
          }
          caps[k] = Math.round(v);
        }
      }
      cfgToSave = { inject, caps };
    }
  }

  // 读原覆盖（未传的字段保持原值）
  const prev = (await pool.query(`select user_template, context_config from ai_prompts where key = $1`, [key])).rows[0];
  const finalTpl = userTemplate !== undefined ? tplToSave : ((prev?.user_template as string | null) ?? null);
  const finalCfg =
    contextConfig !== undefined
      ? cfgToSave
      : ((prev?.context_config as { inject: Record<string, boolean>; caps: Record<string, number> } | null) ?? null);

  const { rows } = await pool.query(
    `insert into ai_prompts (key, content, enabled, remark, user_template, context_config, updated_by, updated_at)
     values ($1,$2,$3,$4,$5,$6::jsonb,$7,now())
     on conflict (key) do update set
       content = $2, enabled = $3, remark = $4, user_template = $5, context_config = $6::jsonb, updated_by = $7, updated_at = now()
     returning key, content, enabled, remark, user_template, context_config, updated_at`,
    [key, content, enabled === true, remark ?? null, finalTpl, finalCfg ? JSON.stringify(finalCfg) : null, user.id],
  );
  // 版本快照（三件套 payload；content 列保留兼容旧版本读取）
  await pool.query(
    `insert into ai_prompt_versions (key, content, payload, created_by) values ($1,$2,$3::jsonb,$4)`,
    [key, content, JSON.stringify({ system: content, userTemplate: finalTpl, contextConfig: finalCfg }), user.id],
  );
  invalidatePrompts(key as PromptKey);
  return NextResponse.json({ ok: true, prompt: rows[0] });
}

/** GET /api/admin/prompts/[key] —— 版本历史（最近 30 条，含三件套 payload 供整体回滚） */
export async function GET(_req: Request, ctx: { params: Promise<{ key: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  const { rows } = await pool.query(
    `select v.id, v.content, v.payload, v.restored_from, v.created_at, p.nickname as created_by_name,
            length(v.content) as size
     from ai_prompt_versions v left join profiles p on p.id = v.created_by
     where v.key = $1 order by v.created_at desc limit 30`,
    [key],
  );
  return NextResponse.json({ versions: rows });
}

/** DELETE /api/admin/prompts/[key] —— 恢复代码默认：删覆盖行 + 清缓存 */
export async function DELETE(_req: Request, ctx: { params: Promise<{ key: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { key } = await ctx.params;
  if (!PROMPT_KEYS.includes(key as PromptKey)) {
    return NextResponse.json({ error: "未知的 prompt key" }, { status: 404 });
  }
  await pool.query(`delete from ai_prompts where key = $1`, [key]);
  invalidatePrompts(key as PromptKey);
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { PROMPT_KEYS, PROMPT_META, defaultPrompt, type PromptKey } from "@/lib/prompts";
import { AI_INPUT_REGISTRY, mergeContextConfig } from "@/lib/ai-inputs";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/admin/prompts —— prompt 清单：key 元信息 + 生效来源 + DB 覆盖内容 + 默认值全文（前端做对比）。
 * 3-A 扩展：user 模板/注入配置的 DB 覆盖原值（userTemplate/contextConfig，未覆盖为 null）、
 * 注册表全文（registry：默认模板/占位符/注入项/参数范围）——前端据此渲染三段详情。 */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "仅管理员" }, { status: 403 });

  const { rows } = await pool.query(
    `select key, content, enabled, remark, updated_at, updated_by, user_template, context_config from ai_prompts`,
  );
  const overrides = new Map(rows.map((r) => [r.key, r]));
  const items = PROMPT_KEYS.map((key) => {
    const o = overrides.get(key);
    const active = o ? o.enabled : true;
    const spec = AI_INPUT_REGISTRY[key as PromptKey];
    const ctxRaw = active ? ((o?.context_config ?? null) as { inject?: Record<string, boolean>; caps?: Record<string, number> } | null) : null;
    return {
      key,
      title: PROMPT_META[key].title,
      category: PROMPT_META[key].category,
      enabled: active, // 无覆盖 = 用默认值，等效"启用"
      overridden: !!o,
      dbContent: o?.content ?? null,
      remark: o?.remark ?? null,
      updatedAt: o?.updated_at ?? null,
      defaultContent: defaultPrompt(key),
      // 3-A 输入装配：DB 覆盖原值（null=未覆盖用代码默认）+ 合并后的生效配置 + 注册表
      userTemplate: active && typeof o?.user_template === "string" && o.user_template.trim() ? o.user_template : null,
      userTemplateDefault: spec.userTemplate,
      contextConfig: ctxRaw,
      effectiveConfig: mergeContextConfig(key as PromptKey, ctxRaw),
      registry: spec,
    };
  });
  return NextResponse.json({ items });
}

import { spawn } from "node:child_process";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { hasApiKey, transcribeAudio, asrModel } from "@shiguangri/ai";
import { writeAuditRecord } from "@/lib/audit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MAX_BYTES = 15 * 1024 * 1024; // 15MB 上限（约几分钟语音）

/** 音频魔数嗅探：GLM-ASR 只认 wav/mp3，其余格式先经 FFMPEG_PATH 转成 16k 单声道 wav */
function sniffFormat(buf: Buffer): "wav" | "mp3" | "other" {
  if (buf.length > 12 && buf.toString("ascii", 0, 4) === "RIFF" && buf.toString("ascii", 8, 12) === "WAVE") return "wav";
  if (buf.length > 3 && (buf.toString("ascii", 0, 3) === "ID3" || (buf[0] === 0xff && (buf[1] & 0xe0) === 0xe0))) return "mp3";
  return "other";
}

function runFfmpeg(bin: string, args: string[]): Promise<void> {
  return new Promise((resolve, reject) => {
    const p = spawn(bin, args, { stdio: "ignore" });
    p.on("error", (e) => reject(new Error(`ffmpeg 启动失败：${e.message}`)));
    p.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`ffmpeg 退出码 ${code}`))));
  });
}

/** 非 wav/mp3（安卓 MediaRecorder 只能出 3gp/m4a 等）→ 统一转 16k 单声道 wav 再送识别 */
async function toWav(buffer: Buffer, contentType: string): Promise<Buffer> {
  const ffmpeg = process.env.FFMPEG_PATH;
  if (!ffmpeg) {
    throw new Error("该音频格式暂不支持，请使用键盘输入或重试");
  }
  const ext = contentType.includes("mp4") || contentType.includes("m4a") ? "m4a" : contentType.includes("webm") ? "webm" : "bin";
  const dir = await mkdtemp(join(tmpdir(), "asr-"));
  try {
    const src = join(dir, `in.${ext}`);
    const dst = join(dir, "out.wav");
    await writeFile(src, buffer);
    await runFfmpeg(ffmpeg, ["-y", "-i", src, "-ac", "1", "-ar", "16000", "-sample_fmt", "s16", dst]);
    return await readFile(dst);
  } finally {
    await rm(dir, { recursive: true, force: true }).catch(() => {});
  }
}

/**
 * POST /api/asr —— 语音转文字（multipart: file）
 * 转发智谱 GLM-ASR；返回 { text }，空音频返回空文本由前端提示。
 * Web 端已重采样为 wav；安卓受 MediaRecorder 限制产出 m4a 等，由 FFMPEG_PATH 转码兜底。
 */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (!hasApiKey()) return NextResponse.json({ error: "未配置 AI 服务" }, { status: 503 });

  const form = await req.formData().catch(() => null);
  const file = form?.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "缺少音频文件" }, { status: 400 });
  }
  if (file.size === 0) {
    return NextResponse.json({ error: "音频为空，请重试" }, { status: 400 });
  }
  if (file.size > MAX_BYTES) {
    return NextResponse.json({ error: "音频太长（上限 15MB）" }, { status: 400 });
  }

  try {
    let buffer = Buffer.from(await file.arrayBuffer());
    const format = sniffFormat(buffer);
    let filename = file.name || "voice.webm";
    let contentType = file.type || "audio/webm";
    if (format === "other") {
      buffer = Buffer.from(await toWav(buffer, contentType));
      filename = "voice.wav";
      contentType = "audio/wav";
    }
    const startedAt = Date.now();
    let usage = { prompt_tokens: 0, completion_tokens: 0 };
    const text = await transcribeAudio({
      data: buffer,
      filename,
      contentType,
      timeoutMs: 45_000,
      onUsage: (u) => (usage = u),
    });
    void writeAuditRecord({
      userId: user.id,
      stage: "asr",
      model: asrModel(),
      latencyMs: Date.now() - startedAt,
      textLen: text?.length ?? 0,
      ok: Boolean(text),
      promptTokens: usage.prompt_tokens,
      completionTokens: usage.completion_tokens,
    });
    if (!text) {
      return NextResponse.json({ error: "没有听清内容，请再试一次" }, { status: 422 });
    }
    return NextResponse.json({ text });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    void writeAuditRecord({
      userId: user.id,
      stage: "asr",
      model: asrModel(),
      ok: false,
      error: msg.slice(0, 300),
    });
    // 429 多为资源包不足/限流：对用户友好化（管理员侧去智谱控制台买 GLM-ASR 资源包即可恢复）
    const friendly = msg.includes("429") || msg.includes("1113")
      ? "语音识别服务暂不可用（资源包不足或限流），请稍后重试或使用键盘输入"
      : `语音识别失败：${msg}`;
    return NextResponse.json({ error: friendly }, { status: 502 });
  }
}

