import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { IMAGE_MIME_EXT, newStorageKey, saveImageFile, sniffImageMime } from "@/lib/storage";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MAX_PER_ENTRY = 9;
const MAX_BYTES = 5 * 1024 * 1024; // 压缩后兜底上限

/**
 * POST /api/entries/:id/images —— 发布文字动态后并行上传图片（formData 字段 files，多文件）
 * 校验：登录 → entry 属主 → 单条 ≤9 张（含已有）→ 单张 ≤5MB → 魔数白名单；写盘 + 落库（事务）
 */
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await params;

  const entry = (
    await pool.query(`select id from entries where id = $1 and user_id = $2`, [id, user.id])
  ).rows[0];
  if (!entry) return NextResponse.json({ error: "动态不存在" }, { status: 404 });

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "需要 multipart/form-data" }, { status: 400 });
  }
  const files = form.getAll("files").filter((f): f is File => f instanceof File);
  if (files.length === 0) return NextResponse.json({ error: "没有文件" }, { status: 400 });

  const { rows: existing } = await pool.query(
    `select count(*)::int as n from entry_images where entry_id = $1 and user_id = $2`,
    [id, user.id],
  );
  const have = existing[0].n;
  if (have + files.length > MAX_PER_ENTRY) {
    return NextResponse.json({ error: `单条动态最多 ${MAX_PER_ENTRY} 张（已有 ${have} 张）` }, { status: 400 });
  }

  // 逐一校验（大小 + 魔数），全部通过才落库
  const prepared: { mime: string; bytes: number; data: Buffer; key: string }[] = [];
  for (const f of files) {
    if (f.size > MAX_BYTES) {
      return NextResponse.json({ error: `单张图片不能超过 5MB` }, { status: 400 });
    }
    const data = Buffer.from(await f.arrayBuffer());
    const sniffed = sniffImageMime(data);
    if (!sniffed || !(sniffed in IMAGE_MIME_EXT)) {
      return NextResponse.json({ error: "仅支持 jpg/png/webp/gif 图片" }, { status: 400 });
    }
    prepared.push({ mime: sniffed, bytes: data.length, data, key: newStorageKey(sniffed) });
  }

  const client = await pool.connect();
  try {
    await client.query("begin");
    const inserted: { id: string; storageKey: string; mime: string; width: number | null; height: number | null; sort: number }[] = [];
    let sort = have; // 追加到已有图片之后
    for (const p of prepared) {
      const { rows } = await client.query(
        `insert into entry_images (user_id, entry_id, storage_key, mime, bytes, width, height, sort)
         values ($1,$2,$3,$4,$5,$6,$7,$8)
         returning id, storage_key, mime, width, height, sort`,
        [user.id, id, p.key, p.mime, p.bytes, null, null, sort++],
      );
      const r = rows[0];
      inserted.push({ id: r.id, storageKey: r.storage_key, mime: r.mime, width: r.width, height: r.height, sort: r.sort });
    }
    await client.query("commit");
    // 落库成功后写盘；失败则回删行（个人系统：极小概率，保证不留死链）
    try {
      for (const p of prepared) await saveImageFile(p.key, p.data);
    } catch (e) {
      await pool.query(`delete from entry_images where entry_id = $1 and storage_key = any($2)`, [
        id,
        prepared.map((p) => p.key),
      ]).catch(() => {});
      throw e;
    }
    return NextResponse.json({ ok: true, images: inserted });
  } catch (e) {
    await client.query("rollback").catch(() => {});
    console.error("[images] 上传失败:", e);
    return NextResponse.json({ error: "上传失败，请重试" }, { status: 500 });
  } finally {
    client.release();
  }
}

import { NextResponse } from "next/server";
import { pool, findOverlap, overlapError } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { inferInteractionType } from "@shiguangri/shared/social";

export const runtime = "nodejs";

type ManualDomain = "schedule" | "todo" | "finance" | "mood" | "diet" | "people";
const VALID: ManualDomain[] = ["schedule", "todo", "finance", "mood", "diet", "people"];

/**
 * POST /api/entries/:id/manual { domain, payload } —— 手动补充识别产物（不经 AI）
 * 六域各自落库并写登记簿（engine='manual'），来源动态在动态流中完整呈现。
 */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const body = (await req.json().catch(() => ({}))) as {
    domain?: ManualDomain;
    payload?: Record<string, unknown>;
  };
  const domain = body.domain;
  const p = (body.payload ?? {}) as Record<string, any>;
  if (!domain || !VALID.includes(domain)) {
    return NextResponse.json({ error: "domain 需为 schedule/todo/finance/mood/diet/people" }, { status: 400 });
  }

  const entry = (
    await pool.query(`select id, raw_text, created_at from entries where id = $1 and user_id = $2`, [id, user.id])
  ).rows[0];
  if (!entry) return NextResponse.json({ error: "动态不存在" }, { status: 404 });

  const client = await pool.connect();
  try {
    await client.query("begin");
    let message = "";
    let result: unknown = {};

    switch (domain) {
      case "schedule": {
        const title = String(p.title ?? "").trim();
        if (!title || !p.startTime || !p.endTime) {
          await client.query("rollback");
          return NextResponse.json({ error: "需要标题与起止时间" }, { status: 400 });
        }
        // 以动态创建日为基准日，拼接 HH:MM
        const base = new Date(entry.created_at);
        const day = `${base.getFullYear()}-${String(base.getMonth() + 1).padStart(2, "0")}-${String(base.getDate()).padStart(2, "0")}`;
        const start = new Date(`${day}T${p.startTime}:00`).toISOString();
        const end = new Date(`${day}T${p.endTime}:00`).toISOString();
        if (end <= start) {
          await client.query("rollback");
          return NextResponse.json({ error: "结束时间必须晚于开始时间" }, { status: 400 });
        }
        const conflict = await findOverlap(user.id, start, end);
        if (conflict) {
          await client.query("rollback");
          return NextResponse.json({ error: overlapError(conflict) }, { status: 409 });
        }
        const activityId = typeof p.activityId === "string" && p.activityId ? p.activityId : "other";
        await client.query(
          `insert into time_blocks (user_id, entry_id, activity_id, title, start_at, end_at, time_mode, source)
           values ($1,$2,$3,$4,$5,$6,'explicit','manual')`,
          [user.id, id, activityId, title, start, end],
        );
        result = { title, start, end };
        message = `🕒 已手动添加日程「${title}」`;
        break;
      }
      case "todo": {
        const title = String(p.title ?? "").trim();
        if (!title) {
          await client.query("rollback");
          return NextResponse.json({ error: "标题不能为空" }, { status: 400 });
        }
        const dueAt = p.dueAt ? new Date(String(p.dueAt)).toISOString() : null;
        const activityId = typeof p.activityId === "string" && p.activityId ? p.activityId : "other";
        await client.query(
          `insert into todos (user_id, entry_id, title, activity_id, due_at, remind_at, source, space_id)
           values ($1,$2,$3,$4,$5,$6,'manual',(select space_id from entries where id = $2))`,
          [user.id, id, title, activityId, dueAt, dueAt ? new Date(new Date(dueAt).getTime() - 15 * 60_000) : null],
        );
        result = { title, dueAt };
        message = `📋 已手动添加 todo「${title}」`;
        break;
      }
      case "finance": {
        const yuan = Number(p.yuan);
        if (!Number.isFinite(yuan) || yuan <= 0) {
          await client.query("rollback");
          return NextResponse.json({ error: "金额需大于 0" }, { status: 400 });
        }
        const direction = p.direction === "in" ? "in" : "out";
        await client.query(
          `insert into transactions (user_id, entry_id, direction, amount_cents, category, counterparty, note, occurred_at, is_draft)
           values ($1,$2,$3,$4,$5,$6,$7,$8,true)`,
          [
            user.id, id, direction, Math.round(yuan * 100),
            typeof p.category === "string" && p.category ? p.category : "其他",
            typeof p.counterparty === "string" && p.counterparty ? p.counterparty : null,
            entry.raw_text, new Date().toISOString(),
          ],
        );
        result = { direction, yuan };
        message = `💰 已手动添加${direction === "out" ? "支出" : "收入"} ¥${yuan}（待确认）`;
        break;
      }
      case "mood": {
        const label = typeof p.label === "string" ? p.label.trim() : "";
        if (!label) {
          await client.query("rollback");
          return NextResponse.json({ error: "请选择心情" }, { status: 400 });
        }
        await client.query(`update entries set mood = $2, mood_score = $3 where id = $1`, [id, label, Number(p.score ?? 0)]);
        result = { label };
        message = `😊 已设置心情「${label}」`;
        break;
      }
      case "diet": {
        const text = typeof p.text === "string" ? p.text.trim() : "";
        if (!text) {
          await client.query("rollback");
          return NextResponse.json({ error: "请填写吃了什么" }, { status: 400 });
        }
        const meal = ["早餐", "午餐", "晚餐", "加餐", "夜宵", "未知"].includes(String(p.meal)) ? String(p.meal) : "未知";
        const kcal = Number.isFinite(Number(p.kcal)) && Number(p.kcal) > 0 ? Number(p.kcal) : null;
        await client.query(
          `insert into diet_records (user_id, entry_id, meal, items, total_kcal) values ($1,$2,$3,$4,$5)`,
          [user.id, id, meal, JSON.stringify([{ name: text.slice(0, 40), amount: null, kcal }]), kcal],
        );
        result = { meal, text, kcal };
        message = `🍽 已手动添加饮食「${text}」`;
        break;
      }
      case "people": {
        const name = typeof p.name === "string" ? p.name.trim() : "";
        if (!name) {
          await client.query("rollback");
          return NextResponse.json({ error: "请填写姓名" }, { status: 400 });
        }
        const type = ["见面", "通话", "送礼", "收礼", "请客", "帮忙", "其他"].includes(String(p.type)) ? String(p.type) : "见面";
        const c = (
          await client.query(
            `insert into contacts (user_id, name) values ($1, $2)
             on conflict (user_id, name) do update set name = excluded.name returning id`,
            [user.id, name],
          )
        ).rows[0];
        await client.query(
          `insert into interactions (user_id, contact_id, entry_id, type, summary, occurred_at)
           values ($1,$2,$3,$4,$5,$6)`,
          [user.id, c.id, id, type, entry.raw_text.slice(0, 60), new Date().toISOString()],
        );
        result = { name, type };
        message = `👥 已记录与「${name}」的往来`;
        break;
      }
    }

    // 登记簿：手动添加标记为 applied + manual
    await client.query(
      `insert into entry_recognitions (user_id, entry_id, domain, status, result, confidence, engine)
       values ($1,$2,$3,'applied',$4,1,'manual')
       on conflict (entry_id, domain) do update set
         status = 'applied', result = excluded.result, confidence = 1,
         engine = 'manual', updated_at = now()`,
      [user.id, id, domain, JSON.stringify(result ?? {})],
    );

    await client.query("commit");
    return NextResponse.json({ ok: true, message });
  } catch (e) {
    await client.query("rollback");
    return NextResponse.json({ error: String(e) }, { status: 500 });
  } finally {
    client.release();
  }
}

import { NextResponse } from "next/server";
import { pool, findOverlap, overlapError } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { parseInput, CONFIDENCE_THRESHOLD, DOMAIN_LABELS, type Domain, type ParseResult } from "@shiguangri/ai";
import { inferInteractionType } from "@shiguangri/shared/social";
import { checkAiQuota } from "@/lib/quota";
import { writeAuditRecord } from "@/lib/audit";
import { getPromptBundle, assembleUserPrompt, type PromptKey } from "@/lib/prompts";
import { listContactNames } from "@/lib/analyze";
import { toCstWallClock } from "@shiguangri/ai";

export const runtime = "nodejs";


const VALID = ["schedule", "todo", "finance", "mood", "diet", "people"] as const;

/**
 * POST /api/entries/:id/recognize { domain } —— 单域重新识别（替换式）
 * mood: 覆写/清空 | schedule: 冲突检测通过才换块 | todo/finance: 删旧落新 | diet: upsert
 */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const q = await checkAiQuota(user.id);
  if (!q.allowed) {
    return NextResponse.json(
      { error: `AI 免费额度已用完（30 天内 ${q.used}/${q.limit} 次）·升级 Pro 解锁无限识别`, quota: q },
      { status: 402 },
    );
  }
  const { id } = await ctx.params;
  const { domain } = (await req.json().catch(() => ({}))) as { domain?: string };
  if (!domain || !VALID.includes(domain as Domain | "people")) {
    return NextResponse.json(
      { error: "domain 需为 schedule/todo/finance/mood/diet/people" },
      { status: 400 },
    );
  }

  const entry = (
    await pool.query(`select id, raw_text from entries where id = $1 and user_id = $2`, [id, user.id])
  ).rows[0];
  if (!entry) return NextResponse.json({ error: "动态不存在" }, { status: 404 });

  const t0 = Date.now();
  let promptTokens = 0;
  let completionTokens = 0;
  // 输入装配（3-A）：单域 key 按 DB 配置组装 user prompt；people 域联系人受开关控制
  const key = `extract_domain_${domain}` as PromptKey;
  const bundle = await getPromptBundle(key);
  const contactsOn = domain === "people" && bundle.config.inject.contactList;
  const contactNames = contactsOn ? await listContactNames(user.id, bundle.config.caps.contactCount) : undefined;
  const contactList =
    contactsOn && contactNames && contactNames.length
      ? `\n已有联系人（人物识别时称呼对齐到名单原文）：${contactNames.join("、")}`
      : "";
  const userPrompt = assembleUserPrompt(key, bundle, {
    nowCst: toCstWallClock(new Date()),
    contactList,
    text: entry.raw_text,
  });
  const r: ParseResult = await parseInput(entry.raw_text, {
    domain, // 单域专属提示词：只判本域，更准更省
    contactNames,
    systemPrompt: bundle.system,
    userPrompt,
    onUsage: (u) => {
      // 历史消耗口径：修复重问等多轮调用逐次累加，不取最后一次
      promptTokens += u.prompt_tokens;
      completionTokens += u.completion_tokens;
    },
  });
  // 整次重识别一行审计：tokens 为历次 LLM 调用合计（含修复重问）；降级但已耗 token 时如实归属模型
  void writeAuditRecord({
    userId: user.id, entryId: id, stage: "parse",
    model: r.engine !== "rules" || promptTokens > 0 ? process.env.GLM_MODEL ?? "glm-5.3-flash" : null,
    engine: r.engine,
    latencyMs: Date.now() - t0, ok: true,
    promptTokens, completionTokens,
  });
  const client = await pool.connect();
  try {
    await client.query("begin");
    let applied = false;
    let result: unknown = null;
    let message = "";

    switch (domain) {
      case "mood": {
        applied = !!r.mood.label;
        result = r.mood;
        await client.query(`update entries set mood = $1, mood_score = $2 where id = $3`, [
          applied ? r.mood.label : null,
          applied ? r.mood.score : null,
          id,
        ]);
        message = applied ? `😊 识别到心情：${r.mood.label}` : "未识别出心情，已清除原心情";
        break;
      }
      case "schedule": {
        if (!r.scheduleApplicable || r.intent === "todo") {
          // 识别不出：删旧块，动态变纯动态
          await client.query(`delete from time_blocks where entry_id = $1 and user_id = $2`, [id, user.id]);
          result = { reason: "未识别出日程" };
          message = "未识别出日程，已移除原日程块";
          break;
        }
        const conflict = await findOverlap(user.id, r.time.start, r.time.end);
        if (conflict) {
          await client.query("rollback");
          return NextResponse.json(
          { error: overlapError(conflict, { title: r.title, start: r.time.start, end: r.time.end }), conflict },
          { status: 409 },
        );
        }
        await client.query(`delete from time_blocks where entry_id = $1 and user_id = $2`, [id, user.id]);
        const block = (
          await client.query(
            `insert into time_blocks (user_id, entry_id, activity_id, title, start_at, end_at, time_mode, source)
             values ($1,$2,$3,$4,$5,$6,$7,'keyboard') returning *`,
            [user.id, id, r.activity, r.title, r.time.start, r.time.end, r.time.mode],
          )
        ).rows[0];
        applied = true;
        result = { blockId: block.id, title: r.title, startAt: r.time.start, endAt: r.time.end };
        message = `🕒 日程已更新：${r.title}`;
        break;
      }
      case "todo": {
        await client.query(`delete from todos where entry_id = $1 and user_id = $2`, [id, user.id]);
        if (r.intent === "todo") {
          const remind = new Date(new Date(r.time.start).getTime() - 15 * 60_000);
          const todo = (
            await client.query(
              `insert into todos (user_id, entry_id, title, activity_id, due_at, remind_at, source, space_id)
               values ($1,$2,$3,$4,$5,$6,'keyboard',(select space_id from entries where id = $2)) returning id`,
              [user.id, id, r.title, r.activity, r.time.start, remind.toISOString()],
            )
          ).rows[0];
          applied = true;
          result = { todoId: todo.id, title: r.title };
          message = `📋 todo 已更新：${r.title}`;
        } else {
          result = { reason: "未识别出 todo" };
          message = "未识别出 todo，已移除原 todo";
        }
        break;
      }
      case "finance": {
        await client.query(`delete from transactions where entry_id = $1 and user_id = $2`, [id, user.id]);
        if (r.finance.hasAmount && r.finance.amountCents != null) {
          await client.query(
            `insert into transactions (user_id, entry_id, direction, amount_cents, category, counterparty, note, occurred_at)
             values ($1,$2,$3,$4,$5,$6,$7,$8)`,
            [
              user.id, id,
              r.finance.direction === "in" ? "in" : "out",
              Math.abs(r.finance.amountCents),
              r.finance.category ?? "其他",
              r.finance.counterparty ?? null,
              entry.raw_text,
              r.time.end,
            ],
          );
          applied = true;
          result = r.finance;
          message = `💰 收支已更新：¥${(Math.abs(r.finance.amountCents) / 100).toFixed(0)}`;
        } else {
          result = { reason: "未识别出金额" };
          message = "未识别出收支，已移除原流水";
        }
        break;
      }
      case "diet": {
        await client.query(`delete from diet_records where entry_id = $1 and user_id = $2`, [id, user.id]);
        if (r.diet.applicable && r.diet.items.length > 0) {
          await client.query(
            `insert into diet_records (user_id, entry_id, meal, items, total_kcal)
             values ($1,$2,$3,$4,$5)`,
            [user.id, id, r.diet.meal, JSON.stringify(r.diet.items), r.diet.totalKcal ?? null],
          );
          applied = true;
          result = r.diet;
          const kcal = r.diet.totalKcal != null ? ` · ≈${r.diet.totalKcal} kcal` : "";
          message = `🍽 饮食已更新：${r.diet.meal}${kcal}`;
        } else {
          result = { reason: "未识别出饮食" };
          message = "未识别出饮食记录";
        }
        break;
      }
      case "people": {
        // 关系域：删旧往来，按解析结果重建（精确名/别名命中已有联系人则复用，避免称呼变体重建档）
        await client.query(`delete from interactions where entry_id = $1 and user_id = $2`, [id, user.id]);
        let added = 0;
        for (const p of r.people) {
          const hit = await client.query(
            `select id from contacts where user_id = $1 and (name = $2 or alias = $2) limit 1`,
            [user.id, p.name],
          );
          const contactId = hit.rows[0]
            ? hit.rows[0].id
            : (
                await client.query(
                  `insert into contacts (user_id, name) values ($1, $2)
                   on conflict (user_id, name) do update set name = excluded.name returning id`,
                  [user.id, p.name],
                )
              ).rows[0].id;
          const summary = p.event ? (p.event === r.title ? p.event : `${p.event}：${r.title}`) : r.title;
          await client.query(
            `insert into interactions (user_id, contact_id, entry_id, type, summary, occurred_at)
             values ($1,$2,$3,$4,$5,$6)`,
            [user.id, contactId, id, inferInteractionType(p.event), summary, r.time.end],
          );
          added++;
        }
        applied = added > 0;
        result = { people: r.people };
        message = added > 0 ? `👥 关系已更新（${added} 人）` : "未识别出人物，已移除原关联";
        break;
      }
    }

    await client.query(
      `insert into entry_recognitions (user_id, entry_id, domain, status, result, confidence, engine)
       values ($1,$2,$3,$4,$5,$6,$7)
       on conflict (entry_id, domain) do update set
         status = excluded.status, result = excluded.result,
         confidence = excluded.confidence, engine = excluded.engine, updated_at = now()`,
      [user.id, id, domain, applied ? "applied" : "none", JSON.stringify(result ?? {}), confidenceOf(r, domain), r.engine],
    );

    await client.query("commit");
    return NextResponse.json({ ok: true, applied, domain, message: `${domain === "people" ? "关系" : DOMAIN_LABELS[domain as Domain]}：${message}` });
  } catch (e) {
    await client.query("rollback");
    return NextResponse.json({ error: String(e) }, { status: 500 });
  } finally {
    client.release();
  }
}

function confidenceOf(r: ParseResult, domain: string): number {
  switch (domain) {
    case "people": return 0.9;
  }
  switch (domain as Domain) {
    case "schedule": return r.scheduleConfidence;
    case "todo": return r.todoConfidence;
    case "finance": return r.financeConfidence;
    case "mood": return r.mood.confidence;
    case "diet": return r.diet.confidence;
  }
  return 0.9;
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const TZ = "Asia/Shanghai";

/**
 * GET /api/export?format=json|md —— 导出我的全部数据（docs/06 P8：数据可携带）
 * json=全量备份（所有表）；md=可读的动态日记。生产环境建议定期下载 json 备份。
 */
export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const format = new URL(req.url).searchParams.get("format") ?? "json";

  const [entries, blocks, todos, transactions, diets, contacts, interactions, accounts, budgets] = await Promise.all([
    pool.query(
      `select id, raw_text, source, mood, mood_score, (created_at at time zone $2) as created_at
       from entries where user_id = $1 order by created_at`,
      [user.id, TZ],
    ),
    pool.query(
      `select b.title, b.activity_id, a.name as activity, b.start_at, b.end_at, b.duration_min, b.time_mode, b.source
       from time_blocks b join activities a on a.id = b.activity_id and a.user_id = b.user_id
       where b.user_id = $1 order by b.start_at`,
      [user.id],
    ),
    pool.query(`select title, status, due_at, done_at, created_at from todos where user_id = $1 order by created_at`, [user.id]),
    pool.query(
      `select direction, amount_cents, category, counterparty, note, occurred_at, is_draft, account_id
       from transactions where user_id = $1 order by occurred_at`,
      [user.id],
    ),
    pool.query(
      `select d.meal, d.items, d.total_kcal, (e.created_at at time zone $2) as recorded_at
       from diet_records d join entries e on e.id = d.entry_id
       where d.user_id = $1 order by e.created_at`,
      [user.id, TZ],
    ),
    pool.query(
      `select name, alias, group_tag, birthday, birthday_cal, lunar_month, lunar_day, lunar_leap, anniversary, importance, intimacy, notes
       from contacts where user_id = $1 order by created_at`,
      [user.id],
    ),
    pool.query(
      `select c.name as contact, i.type, i.summary, i.occurred_at
       from interactions i join contacts c on c.id = i.contact_id
       where i.user_id = $1 order by i.occurred_at`,
      [user.id],
    ),
    pool.query(`select name, icon, opening_balance_cents, archived from accounts where user_id = $1`, [user.id]),
    pool.query(`select monthly_limit_cents, alert_threshold from budgets where user_id = $1`, [user.id]),
  ]);

  const stamp = new Date().toISOString().slice(0, 10);
  const download = (body: string, ext: string, type: string) =>
    new NextResponse(body, {
      headers: {
        "Content-Type": `${type}; charset=utf-8`,
        "Content-Disposition": `attachment; filename="shiguangri-export-${stamp}.${ext}"`,
      },
    });

  const localYmd = (v: unknown) => { const d = new Date(String(v)); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };
  const localClock = (v: unknown) => { const d = new Date(String(v)); return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`; };

  if (format === "md") {
    const lines: string[] = [
      `# 拾光 · 动态日记`,
      ``,
      `> 导出时间：${new Date().toLocaleString("zh-CN")} · 共 ${entries.rows.length} 条动态`,
      ``,
    ];
    let lastDay = "";
    for (const e of entries.rows) {
      const day = localYmd(e.created_at);
      if (day !== lastDay) {
        lines.push(`\n## ${day}\n`);
        lastDay = day;
      }
      const clock = localClock(e.created_at);
      const mood = e.mood ? `（心情：${e.mood}）` : "";
      lines.push(`- **${clock}** ${e.raw_text}${mood}`);
      // 当天日程块（跨天块按交集归属，与日视图口径一致）
      for (const b of blocks.rows.filter((b: any) => b.start_at && (localYmd(b.start_at) === day || localYmd(b.end_at) === day))) {
        const startTime = localClock(b.start_at);
        const endTime = localClock(b.end_at);
        lines.push(`  - 🕒 ${b.activity ?? ""} ${b.title}（${startTime}–${endTime}，${b.duration_min} 分钟）`);
      }
    }
    lines.push(`\n---\n\n## 日程（全部时间块）\n`);
    for (const b of blocks.rows) {
      lines.push(
        `- ${localYmd(b.start_at)} ${localClock(b.start_at)}–${localClock(b.end_at)} ${b.activity ?? ""} ${b.title}（${b.duration_min} 分钟）`,
      );
    }
    lines.push(`\n## 分类账\n`);
    for (const t of todos.rows) {
      lines.push(`- [${t.status === "done" ? "x" : " "}] ${t.title}${t.due_at ? `（截止 ${localYmd(t.due_at)}）` : ""}`);
    }
    lines.push(`\n## 财务（非草稿）\n`);
    for (const t of transactions.rows.filter((t: any) => !t.is_draft)) {
      lines.push(
        `- ${localYmd(t.occurred_at)} ${t.direction === "out" ? "支出" : "收入"} ¥${(t.amount_cents / 100).toFixed(2)} · ${t.category}${t.counterparty ? ` · ${t.counterparty}` : ""}${t.note ? ` · ${t.note}` : ""}`,
      );
    }
    lines.push(`\n## 人际往来\n`);
    for (const i of interactions.rows) {
      lines.push(`- ${i.occurred_at ? localYmd(i.occurred_at) : ""} [${i.type}] ${i.contact}：${i.summary ?? ""}`);
    }
    return download(lines.join("\n"), "md", "text/markdown");
  }

  // 默认 json 全量备份
  const backup = {
    exported_at: new Date().toISOString(),
    profile: { nickname: user.nickname ?? null, phone: user.phone ?? null },
    entries: entries.rows,
    time_blocks: blocks.rows,
    todos: todos.rows,
    transactions: transactions.rows,
    diet_records: diets.rows,
    contacts: contacts.rows,
    interactions: interactions.rows,
    accounts: accounts.rows,
    budgets: budgets.rows,
  };
  return download(JSON.stringify(backup, null, 2), "json", "application/json");
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

/** POST /api/feed/:id/dismiss-conflict —— 关闭日程冲突警示条（服务端标记 reasonDismissed，多端持久） */
export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await params;
  const { rowCount } = await pool.query(
    `update entry_recognitions
     set result = coalesce(result, '{}'::jsonb) || '{"reasonDismissed": true}'::jsonb
     where entry_id = $1 and user_id = $2 and domain = 'schedule'`,
    [id, user.id],
  );
  if (!rowCount) return NextResponse.json({ error: "无冲突提示可关闭" }, { status: 404 });
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { ruleMood } from "@shiguangri/ai";
import { analyzeAndPersist } from "@/lib/analyze";
import { checkAiQuota } from "@/lib/quota";
import { deleteImageFile } from "@/lib/storage";

export const runtime = "nodejs";

/**
 * PATCH /api/feed/:id —— 动态修正
 * - { mood } 修正心情（原逻辑：null=清除）
 * - { raw_text } 编辑原文：**替换式自动重识别**——清空旧识别产物 → 置 analyzed_at=null（前端进"识别中"态）
 *   → 后台 analyzeAndPersist 全域重识别（同发动态），完成自动打 analyzed_at，无需手动逐域触发
 */
export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await params;
  const body = (await req.json().catch(() => ({}))) as {
    mood?: string | null;
    raw_text?: string;
    spaceId?: string | null; // 手动归属/移除目标空间
  };

  // 手动归属空间：校验空间属主（null=移除归属）
  if (body.spaceId !== undefined) {
    let sid: string | null = null;
    if (body.spaceId) {
      const hit = await pool.query(`select id from goal_spaces where id = $1 and user_id = $2`, [body.spaceId, user.id]);
      if (!hit.rows[0]) return NextResponse.json({ error: "空间不存在" }, { status: 400 });
      sid = hit.rows[0].id;
    }
    const updated = (
      await pool.query(
        `update entries set space_id = $1 where id = $2 and user_id = $3 returning id, space_id`,
        [sid, id, user.id],
      )
    ).rows[0];
    if (!updated) return NextResponse.json({ error: "动态不存在" }, { status: 404 });
    return NextResponse.json({ ok: true, entry: updated });
  }

  if (body.raw_text !== undefined) {
    const text = body.raw_text.trim();
    if (!text) return NextResponse.json({ error: "内容不能为空" }, { status: 400 });
    if (text.length > 2000) return NextResponse.json({ error: "动态最长 2000 字" }, { status: 400 });
    const q = await checkAiQuota(user.id);
    if (!q.allowed) {
      return NextResponse.json(
        { error: `AI 免费额度已用完（30 天内 ${q.used}/${q.limit} 次）·升级 Pro 解锁无限识别`, quota: q },
        { status: 402 },
      );
    }

    const client = await pool.connect();
    let updated;
    try {
      await client.query("begin");
      // 清理旧识别产物（依赖顺序同 DELETE；心情/识别登记簿随 analyze 重写）
      await client.query(`delete from interactions where entry_id = $1 and user_id = $2`, [id, user.id]);
      await client.query(`delete from transactions where entry_id = $1 and user_id = $2`, [id, user.id]);
      await client.query(`delete from todos where entry_id = $1 and user_id = $2`, [id, user.id]);
      await client.query(`delete from time_blocks where entry_id = $1 and user_id = $2`, [id, user.id]);
      await client.query(`delete from diet_records where entry_id = $1 and user_id = $2`, [id, user.id]);
      await client.query(`delete from entry_recognitions where entry_id = $1 and user_id = $2`, [id, user.id]);
      updated = (
        await client.query(
          `update entries set raw_text = $1, mood = null, mood_score = null, analyzed_at = null
           where id = $2 and user_id = $3 returning id, raw_text, analyzed_at`,
          [text, id, user.id],
        )
      ).rows[0];
      if (!updated) {
        await client.query("rollback");
        return NextResponse.json({ error: "动态不存在" }, { status: 404 });
      }
      await client.query("commit");
    } catch (e) {
      await client.query("rollback");
      return NextResponse.json({ error: String(e) }, { status: 500 });
    } finally {
      client.release();
    }
    // 后台全域重识别（同发动态：秒回 + fire-and-forget），成败都打 analyzed_at
    void analyzeAndPersist(user.id, id, text)
      .catch((e) => console.error(`[analyze] entry ${id} 编辑重识别失败:`, e))
      .finally(() =>
        pool.query(`update entries set analyzed_at = now() where id = $1 and analyzed_at is null`, [id]).catch(() => {}),
      );
    return NextResponse.json({ ok: true, entry: updated });
  }

  const label = body.mood?.trim() || null;
  const score = label ? (ruleMood(label)?.score ?? 0) : null;

  const updated = (
    await pool.query(
      `update entries set mood = $1, mood_score = $2
       where id = $3 and user_id = $4 returning id, mood, mood_score`,
      [label, score, id, user.id],
    )
  ).rows[0];
  if (!updated) return NextResponse.json({ error: "动态不存在" }, { status: 404 });
  return NextResponse.json({ entry: updated });
}

/**
 * DELETE /api/feed/[id] —— 删除一条动态及其全部识别产物
 * （entries 对子表多为 on delete set null，故按依赖顺序显式清理，避免留下孤儿日程/待办）
 */
export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await params;
  const client = await pool.connect();
  try {
    await client.query("begin");
    const imageKeys = (
      await client.query(`select storage_key from entry_images where entry_id = $1 and user_id = $2`, [id, user.id])
    ).rows.map((r) => r.storage_key);
    if (imageKeys.length) {
      await client.query(`delete from entry_images where entry_id = $1 and user_id = $2`, [id, user.id]);
    }
    await client.query(`delete from interactions where entry_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from transactions where entry_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from todos where entry_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from time_blocks where entry_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from diet_records where entry_id = $1 and user_id = $2`, [id, user.id]);
    await client.query(`delete from entry_recognitions where entry_id = $1 and user_id = $2`, [id, user.id]);
    const { rowCount } = await client.query(
      `delete from entries where id = $1 and user_id = $2`, // voice_logs 级联删除
      [id, user.id],
    );
    if (!rowCount) {
      await client.query("rollback");
      return NextResponse.json({ error: "动态不存在" }, { status: 404 });
    }
    await client.query("commit");
    // 盘上文件事务外异步清理（失败仅记日志，不阻塞响应）
    for (const k of imageKeys) void deleteImageFile(k);
    return NextResponse.json({ ok: true });
  } catch (e) {
    await client.query("rollback");
    return NextResponse.json({ error: String(e) }, { status: 500 });
  } finally {
    client.release();
  }
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/feed?limit=10&offset=0&q=关键字&spaceId=all|none|<uuid>
 * 动态流：entries 按记录时刻倒序，聚合 AI 识别出的日程/待办/金额/人物/饮食/图片/识别登记簿。
 * q 非空时按关键字检索：原文 + 识别产物（日程/待办标题、交易类别与对方、联系人、饮食条目）。
 * spaceId：空间切换条过滤（all=不过滤 / none=未归属 / 具体值=该空间）。
 */
export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const url = new URL(req.url);
  const limit = Math.min(Math.max(Number(url.searchParams.get("limit") ?? 10), 1), 200);
  const offset = Math.min(Math.max(Number(url.searchParams.get("offset") ?? 0), 0), 100_000);
  const q = (url.searchParams.get("q") ?? "").trim();
  const spaceId = url.searchParams.get("spaceId") ?? "all";

  let spaceSql = "";
  const spaceParamIndex = 4;
  if (spaceId === "none") spaceSql = ` and e.space_id is null`;
  else if (spaceId !== "all" && /^[0-9a-f-]{36}$/.test(spaceId)) spaceSql = ` and e.space_id = $${spaceParamIndex}::uuid`;

  // 关键字检索：动态原文命中，或任一识别产物命中（中英文均可，ilike 不区分大小写）
  const searchSql = q
    ? `and (
         e.raw_text ilike $4
         or exists (select 1 from time_blocks b where b.entry_id = e.id and b.title ilike $4)
         or exists (select 1 from todos t where t.entry_id = e.id and t.title ilike $4)
         or exists (select 1 from transactions x where x.entry_id = e.id
                    and (x.category ilike $4 or x.counterparty ilike $4 or x.note ilike $4))
         or exists (select 1 from interactions i join contacts c on c.id = i.contact_id
                    where i.entry_id = e.id and c.name ilike $4)
         or exists (select 1 from diet_records d where d.entry_id = e.id and d.items::text ilike $4)
       )`
    : "";

  const { rows } = await pool.query(
    `select e.id, e.raw_text, e.source, e.mood, e.mood_score, e.created_at, e.analyzed_at,
       -- 识别超时兜底：analyzed_at 为空且发布超 10 分钟，前端显示「识别未完成」而非无限转圈
       case when e.analyzed_at is null and e.created_at < now() - interval '10 minutes' then 'timeout' end as recognize_state,
       (select jsonb_build_object('id', gs.id, 'name', gs.name, 'icon', gs.icon, 'color', gs.color)
          from goal_spaces gs where gs.id = e.space_id) as space,
       count(*) over () as total_count,
       coalesce((
         select jsonb_agg(jsonb_build_object(
           'id', b.id, 'title', b.title, 'startAt', b.start_at, 'endAt', b.end_at,
           'durationMin', b.duration_min, 'activityId', b.activity_id,
           'activityName', a.name, 'icon', a.icon, 'color', a.color
         ) order by b.start_at)
         from time_blocks b join activities a on a.id = b.activity_id and a.user_id = b.user_id
         where b.entry_id = e.id
       ), '[]') as blocks,
       coalesce((
         select jsonb_agg(jsonb_build_object(
           'id', t.id, 'title', t.title, 'dueAt', t.due_at, 'startAt', t.start_at, 'status', t.status, 'activityId', t.activity_id
         ) order by t.created_at)
         from todos t where t.entry_id = e.id
       ), '[]') as todos,
       coalesce((
         select jsonb_agg(jsonb_build_object(
           'id', x.id, 'amountCents', x.amount_cents, 'direction', x.direction,
           'category', x.category, 'counterparty', x.counterparty
         ))
         from transactions x where x.entry_id = e.id
       ), '[]') as transactions,
       coalesce((
         select jsonb_agg(jsonb_build_object('interactionId', i.id, 'name', c.name, 'summary', i.summary))
         from interactions i join contacts c on c.id = i.contact_id
         where i.entry_id = e.id
       ), '[]') as people,
       coalesce((
         select jsonb_agg(jsonb_build_object(
           'id', g.id, 'storageKey', g.storage_key, 'mime', g.mime, 'width', g.width, 'height', g.height, 'sort', g.sort
         ) order by g.sort, g.created_at)
         from entry_images g where g.entry_id = e.id
       ), '[]') as images,
       (select jsonb_build_object('id', d.id, 'meal', d.meal, 'items', d.items, 'totalKcal', d.total_kcal)
         from diet_records d where d.entry_id = e.id) as diet,
       coalesce((
         select jsonb_object_agg(rg.domain, jsonb_build_object(
           'status', rg.status, 'confidence', rg.confidence, 'reason', rg.result->>'reason', 'engine', rg.engine,
           'reasonDismissed', coalesce(rg.result->>'reasonDismissed', 'false')::boolean))
         from entry_recognitions rg where rg.entry_id = e.id
       ), '{}'::jsonb) as recognitions
     from entries e
     where e.user_id = $1 ${searchSql} ${spaceSql}
     order by e.created_at desc
     limit $2 offset $3`,
    // 转义 ilike 通配符，避免用户输入的 % _ 被当模糊匹配
    q
      ? spaceId !== "all" && spaceId !== "none"
        ? [user.id, limit, offset, `%${q.replace(/[\\%_]/g, "\\$&")}%`, spaceId]
        : [user.id, limit, offset, `%${q.replace(/[\\%_]/g, "\\$&")}%`]
      : spaceId !== "all" && spaceId !== "none"
        ? [user.id, limit, offset, spaceId]
        : [user.id, limit, offset],
  );
  const total = rows[0] ? Number(rows[0].total_count) : 0;
  return NextResponse.json({ moments: rows, total });
}

import { NextResponse } from "next/server";
import { createReadStream, existsSync, statSync } from "node:fs";
import { getCurrentUser } from "@/lib/auth";
import { pool } from "@/lib/db";
import { storagePath } from "@/lib/storage";
import { Readable } from "node:stream";
import { extname } from "node:path";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MIME: Record<string, string> = {
  ".jpg": "image/jpeg",
  ".png": "image/png",
  ".webp": "image/webp",
  ".gif": "image/gif",
};

/**
 * GET /api/files/<yyyy/mm/uuid.ext> —— 图片访问门禁
 * 登录 → 按 storage_key 查 entry_images（无记录 404 / 他人 403）→ 流式返回
 * uuid key 不可枚举；immutable 私有缓存；ETag 走 304
 */
export async function GET(req: Request, { params }: { params: Promise<{ key: string[] }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { key } = await params;
  const storageKey = (key ?? []).join("/");

  const row = (
    await pool.query(`select id, user_id, mime from entry_images where storage_key = $1`, [storageKey])
  ).rows[0];
  if (!row) return NextResponse.json({ error: "文件不存在" }, { status: 404 });
  if (row.user_id !== user.id) return NextResponse.json({ error: "无权访问" }, { status: 403 });

  let path: string;
  try {
    path = storagePath(storageKey);
  } catch {
    return NextResponse.json({ error: "非法路径" }, { status: 400 });
  }
  if (!existsSync(path) || !statSync(path).isFile()) {
    return NextResponse.json({ error: "文件不存在" }, { status: 404 });
  }

  const stat = statSync(path);
  const etag = `"${stat.size}-${stat.mtimeMs}"`;
  if (req.headers.get("if-none-match") === etag) {
    return new NextResponse(null, { status: 304 });
  }
  const mime = MIME[extname(path).toLowerCase()] ?? row.mime ?? "application/octet-stream";
  return new NextResponse(Readable.toWeb(createReadStream(path)) as unknown as ReadableStream, {
    headers: {
      "Content-Type": mime,
      "Content-Length": String(stat.size),
      "Cache-Control": "private, max-age=31536000, immutable",
      ETag: etag,
    },
  });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/finance/overview?month=YYYY-MM —— 月度概览：收支/储蓄率/分类占比/预算进度/环比/草稿数/账户余额 */
export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const url = new URL(req.url);
  const month = url.searchParams.get("month") ?? "";
  if (!/^\d{4}-\d{2}$/.test(month)) {
    return NextResponse.json({ error: "month 需为 YYYY-MM" }, { status: 400 });
  }
  const TZ = "Asia/Shanghai"; // 与时间模块一致：按北京日期切月

  const summary = async (m: string) => {
    const { rows } = await pool.query(
      `select
         coalesce(sum(case when direction = 'out' then amount_cents else 0 end), 0) as out_cents,
         coalesce(sum(case when direction = 'in'  then amount_cents else 0 end), 0) as in_cents
       from transactions
       where user_id = $1 and is_draft = false
         and to_char(occurred_at at time zone $2, 'YYYY-MM') = $3`,
      [user.id, TZ, m],
    );
    const byCat: Record<string, number> = {};
    const cats = await pool.query(
      `select category, sum(amount_cents)::int as cents
       from transactions
       where user_id = $1 and is_draft = false and direction = 'out'
         and to_char(occurred_at at time zone $2, 'YYYY-MM') = $3
       group by category order by cents desc`,
      [user.id, TZ, m],
    );
    for (const r of cats.rows) byCat[r.category] = r.cents;
    return { outCents: Number(rows[0].out_cents), inCents: Number(rows[0].in_cents), byCategory: byCat };
  };

  const [cur, prev] = await Promise.all([summary(month), summary(monthOf(month, -1))]);

  // 近 6 个月（含当月）收支 → 储蓄率趋势；无流水的月份由前端补零
  const { rows: trendRows } = await pool.query(
    `select to_char(occurred_at at time zone $2, 'YYYY-MM') as month,
            sum(case when direction = 'out' then amount_cents else 0 end)::int as out_cents,
            sum(case when direction = 'in'  then amount_cents else 0 end)::int as in_cents
     from transactions
     where user_id = $1 and is_draft = false
       and to_char(occurred_at at time zone $2, 'YYYY-MM') >= $3
     group by 1 order by 1`,
    [user.id, TZ, monthOf(month, -5)],
  );
  const trendMap = new Map(trendRows.map((r) => [r.month, r]));
  const trend = Array.from({ length: 6 }, (_, i) => {
    const m = monthOf(month, i - 5);
    const row = trendMap.get(m);
    const outCents = row ? Number(row.out_cents) : 0;
    const inCents = row ? Number(row.in_cents) : 0;
    return {
      month: m,
      outCents,
      inCents,
      rate: inCents > 0 ? Math.round(((inCents - outCents) / inCents) * 100) : null,
    };
  });

  const { rows: draftRows } = await pool.query(
    `select count(*)::int as n from transactions where user_id = $1 and is_draft = true`,
    [user.id],
  );

  const { rows: budgetRows } = await pool.query(
    `select monthly_limit_cents, alert_threshold from budgets where user_id = $1`,
    [user.id],
  );

  const { rows: accounts } = await pool.query(
    `select a.id, a.name, a.icon, a.opening_balance_cents,
            (a.opening_balance_cents + coalesce((
               select sum(case when t.direction = 'out' then -t.amount_cents else t.amount_cents end)
               from transactions t
               where t.account_id = a.id and t.is_draft = false
             ), 0))::int as balance_cents
     from accounts a
     where a.user_id = $1 and a.archived = false
     order by a.sort_order, a.created_at`,
    [user.id],
  );

  return NextResponse.json({
    month,
    outCents: cur.outCents,
    inCents: cur.inCents,
    byCategory: cur.byCategory,
    prev: { outCents: prev.outCents, inCents: prev.inCents },
    trend,
    draftCount: draftRows[0].n,
    budget: budgetRows[0] ?? { monthly_limit_cents: 0, alert_threshold: 80 },
    accounts,
  });
}

/** 月份平移（-1 上月） */
function monthOf(key: string, delta: number): string {
  const [y, m] = key.split("-").map(Number);
  const d = new Date(y, m - 1 + delta, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

