  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const url = new URL(req.url);
  const from = url.searchParams.get("from") ?? "";
  const to = url.searchParams.get("to") ?? "";
  if (!DATE_RE.test(from) || !DATE_RE.test(to) || from > to) {
    return NextResponse.json({ error: "from/to 需为合法日期且 from ≤ to" }, { status: 400 });
  }

  // 按天交集钳制：跨天块（如昨晚23:00→今早07:00的睡眠）的时长分摊到它覆盖的每一天，
  // 与日视图/周视图的交集口径一致（旧实现按开始日归全长，跨天块会整段记在一天）
  const { rows } = await pool.query(
    `select to_char(d.day, 'YYYY-MM-DD') as date,
            b.activity_id,
            sum(floor(extract(epoch from least((b.end_at at time zone $2), (d.day + interval '1 day'))
                             - greatest((b.start_at at time zone $2), d.day)) / 60))::int as mins
     from time_blocks b
     join lateral generate_series(
            greatest(date_trunc('day', b.start_at at time zone $2), $3::date::timestamp),
            least(date_trunc('day', b.end_at at time zone $2), $4::date::timestamp),
            interval '1 day') d(day) on true
     where b.user_id = $1
       and least((b.end_at at time zone $2), (d.day + interval '1 day')) > greatest((b.start_at at time zone $2), d.day)
     group by 1, 2`,
    [user.id, TZ, from, to],
  );

  const daysMap = new Map<string, { date: string; totalMin: number; byActivity: Record<string, number> }>();
  const totals: Record<string, number> = {};
  for (const r of rows) {
    if (!daysMap.has(r.date)) daysMap.set(r.date, { date: r.date, totalMin: 0, byActivity: {} });
    const d = daysMap.get(r.date)!;
    d.byActivity[r.activity_id] = r.mins;
    d.totalMin += r.mins;
    totals[r.activity_id] = (totals[r.activity_id] ?? 0) + r.mins;
  }
  return NextResponse.json({ days: [...daysMap.values()], totals });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** PG 容器为 UTC，「今天」必须按北京日期切分（凌晨 0~8 点 UTC 日期仍是昨天） */
const TZ = "Asia/Shanghai";

/** GET /api/today —— 工作台数据：今日 TODO（标记今日的，含子任务）+ 今日已完成待办 + 今日时间块 */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  // 主页今日区只展示「手动标记今日」的待办（微软 To Do「我的一天」语义）：
  // today_tag_date = 北京今天，跨零点自动失效，由用户每天自行规划
  const { rows: parents } = await pool.query(
    `select t.*, a.name as activity_name, a.icon, a.color
     from todos t left join activities a on a.id = t.activity_id and a.user_id = t.user_id
     where t.user_id = $1 and t.status = 'pending' and t.parent_todo_id is null
       and t.today_tag_date = (now() at time zone $2)::date
     order by t.is_important desc, t.created_at desc`,
    [user.id, TZ],
  );
  let todos = parents.map((p) => ({ ...p, children: [] }));
  if (parents.length > 0) {
    const ids = parents.map((p) => p.id);
    const { rows: kids } = await pool.query(
      `select t.*, a.name as activity_name, a.icon, a.color
       from todos t left join activities a on a.id = t.activity_id and a.user_id = t.user_id
       where t.user_id = $1 and t.parent_todo_id = any($2::uuid[])
       order by (t.status = 'done'), t.created_at`,
      [user.id, ids],
    );
    const byParent = new Map<string, unknown[]>(parents.map((p) => [p.id, []]));
    for (const k of kids) byParent.get(k.parent_todo_id)?.push(k);
    todos = parents.map((p) => ({ ...p, children: byParent.get(p.id) ?? [] }));
  }
  const { rows: doneToday } = await pool.query(
    `select t.*, a.name as activity_name, a.icon
     from todos t left join activities a on a.id = t.activity_id and a.user_id = t.user_id
     where t.user_id = $1 and t.status = 'done'
       and (t.done_at at time zone $2)::date = (now() at time zone $2)::date
     order by t.done_at desc`,
    [user.id, TZ],
  );
  // 今日块：按「区间与今天有交集」取——跨天块（如昨晚23:00→今早07:00的睡眠）也要出现在今天，
  // 否则它的凌晨段在界面上不可见，但冲突检测仍会拦截，造成"有冲突却看不到块"的错觉
  const { rows: blocks } = await pool.query(
    `select b.*, a.name as activity_name, a.icon, a.color
     from time_blocks b join activities a on a.id = b.activity_id and a.user_id = b.user_id
     where b.user_id = $1
       and tstzrange(b.start_at, b.end_at, '[)') && tstzrange(
            date_trunc('day', now() at time zone $2) at time zone $2,
            (date_trunc('day', now() at time zone $2) + interval '1 day') at time zone $2)
     order by b.start_at desc`,
    [user.id, TZ],
  );
  const { rows: activities } = await pool.query(
    `select id, name, icon, color, sort_order from activities
     where user_id = $1 order by sort_order`,
    [user.id],
  );
  // 今日卡路里合计（饮食域）：只计「今天记录」的动态的饮食记录，按北京自然日切。
  // 旧口径用 created_at±12h 窗口与今天求交集，会把昨天 12:00 后记录的正餐/夜宵
  // 也算进今天（窗口宽达 24 小时，跨天双向渗漏），导致当日卡路里明显虚高。
  const { rows: kcalRows } = await pool.query(
    `select coalesce(sum(d.total_kcal), 0)::int as kcal
     from diet_records d
     join entries e on e.id = d.entry_id
     where d.user_id = $1
       and coalesce(d.total_kcal, 0) > 0
       and e.created_at >= date_trunc('day', now() at time zone $2) at time zone $2
       and e.created_at < (date_trunc('day', now() at time zone $2) + interval '1 day') at time zone $2`,
    [user.id, TZ],
  );
  const todayKcal = kcalRows[0]?.kcal ?? 0;
  return NextResponse.json({ todos, doneToday, blocks, activities, todayKcal });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { chat, extractJson } from "@shiguangri/ai";
import { z } from "zod";
import { getPromptBundle, assembleUserPrompt } from "@/lib/prompts";
import { loadProfileBlock } from "@/lib/review-input";
import { checkAiQuota } from "@/lib/quota";
import { writeAuditRecord } from "@/lib/audit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const ActionList = z.object({
  reasoning: z.string().optional(),
  actions: z.array(z.object({ title: z.string().min(1).max(30) })).min(0).max(10),
});

/**
 * POST /api/todos/:id/decompose  body: { mode?: 'append' | 'replace', hint?: string }
 * 统一拆解路由，按 id 节点类型分流（REQ-001 R3 · 插入式）：
 * - 顶层待办：生成 ≤10 个行动，追加到行动列表尾部；已有未完成行动且未传 mode → 409 {needMode}
 *   （前端弹「追加 / 重新生成」）；mode=replace 仅清空未完成行动（已完成与重复计数保留）
 * - 行动（有 parent）：细化 ≤3 个同级更小行动，插入到该行动之后（原行动保留，后续 sort 平移）
 */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const t0 = Date.now();
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const q = await checkAiQuota(user.id);
  if (!q.allowed) {
    return NextResponse.json(
      { error: `AI 免费额度已用完（30 天内 ${q.used}/${q.limit} 次）·升级 Pro 解锁无限拆解`, quota: q },
      { status: 402 },
    );
  }
  const { id } = await ctx.params;
  const { mode } = (await req.json().catch(() => ({}))) as { mode?: "append" | "replace" };

  const todo = (
    await pool.query(`select * from todos where id = $1 and user_id = $2`, [id, user.id])
  ).rows[0];
  if (!todo) return NextResponse.json({ error: "todo 不存在" }, { status: 404 });

  const isAction = todo.kind === "action"; // N6：行动（有父或独立）均 kind='action'
  const hasParent = !!todo.parent_todo_id;
  const isDecomposable = todo.status === "pending";
  if (!isDecomposable) return NextResponse.json({ error: "已完成的 todo 不再拆解" }, { status: 400 });

  // ---- 行动上下文（空间名/描述、父待办、已有行动清单用于去重） ----
  const space = todo.space_id
    ? (await pool.query(`select name, description from goal_spaces where id = $1`, [todo.space_id])).rows[0]
    : null;
  const parent = isAction && hasParent
    ? (await pool.query(`select title, note, due_at from todos where id = $1`, [todo.parent_todo_id])).rows[0]
    : null;
  // 去重范围：有父行动=同父兄弟；独立行动=全部独立行动；顶层 todo=其子行动
  const siblings = isAction && hasParent
    ? (
        await pool.query(
          `select id, title, status from todos
           where user_id = $1 and parent_todo_id = $2 and kind = 'action' and id <> $3
           order by sort`,
          [user.id, todo.parent_todo_id, todo.id],
        )
      ).rows
    : isAction
      ? (
          await pool.query(
            `select id, title, status from todos
             where user_id = $1 and parent_todo_id is null and kind = 'action' and id <> $2
             order by sort`,
            [user.id, todo.id],
          )
        ).rows
      : (
          await pool.query(
            `select id, title, status from todos
             where user_id = $1 and parent_todo_id = $2 and kind = 'action'
             order by sort`,
            [user.id, todo.id],
          )
        ).rows;
  const existingTitles = siblings.filter((s) => s.status === "pending").map((s) => s.title);

  // ---- 组装 prompt（3-A：system/user 模板/注入配置三件套按 DB 覆盖装配） ----
  const promptKey = isAction ? "action_decompose" : "todo_decompose";
  const bundle = await getPromptBundle(promptKey);
  const existingOn = bundle.config.inject.existingBlock;
  const cap = bundle.config.caps.existingCount;
  const listed = existingOn ? existingTitles.slice(0, cap) : [];
  const spaceCtxOn = bundle.config.inject.spaceBlock;
  const profileCtxOn = bundle.config.inject.profileBlock;
  const profileBlock = profileCtxOn ? await loadProfileBlock(user.id) : null;
  const note = todo.note || (isAction ? parent?.note : null) || null;
  const userPrompt = assembleUserPrompt(promptKey, bundle, {
    todoBlock: `${isAction ? `所属 todo：${parent?.title ?? ""}` : `todo：${todo.title}`}${note ? `\n相关描述：${note}` : ""}`,
    spaceBlock: spaceCtxOn && space ? `所属空间：${space.name}${space.description ? `（${space.description}）` : ""}` : "",
    existingBlock: listed.length
      ? `已有行动（禁止生成语义重复项）：\n${listed.map((t) => `- ${t}`).join("\n")}`
      : existingOn
        ? "已有行动：无"
        : "",
    profileBlock: profileCtxOn && profileBlock ? `用户画像（供参考）：\n${profileBlock}` : "",
    target: isAction ? `「${todo.title}」` : "上述 todo",
    modeSuffix: mode === "replace" ? "（重新生成：只输出新的行动清单）" : "",
  });
  const system = bundle.system;

  // ---- 调 LLM（temperature 0.3；失败走一次 repair 风格重试） ----
  let raw = "";
  let parsed = null as z.infer<typeof ActionList> | null;
  let promptTokens = 0;
  let completionTokens = 0;
  const onUsage = (u: { prompt_tokens: number; completion_tokens: number }) => {
    promptTokens += u.prompt_tokens;
    completionTokens += u.completion_tokens;
  };
  try {
    raw = await chat({ system, user: userPrompt, temperature: 0.3, maxTokens: 2000, timeoutMs: 60_000, onUsage });
    parsed = ActionList.safeParse(extractJson(raw)).data ?? null;
    if (!parsed) {
      raw = await chat({ system, user: `${userPrompt}\n\n上次的输出未通过校验，请修正后重新输出完整 JSON（结构不变，只输出 JSON）。`, temperature: 0.3, maxTokens: 2000, timeoutMs: 60_000, onUsage });
      parsed = ActionList.safeParse(extractJson(raw)).data ?? null;
    }
  } catch (e) {
    void writeAuditRecord({
      userId: user.id, entryId: null, stage: "decompose",
      model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "decompose",
      latencyMs: Date.now() - t0, ok: false, error: String(e).slice(0, 300),
      promptTokens, completionTokens,
    });
    return NextResponse.json({ error: `AI 拆解失败，请稍后再试（${String(e).slice(0, 80)}）` }, { status: 502 });
  }
  void writeAuditRecord({
    userId: user.id, entryId: null, stage: "decompose",
    model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "decompose",
    latencyMs: Date.now() - t0, ok: true,
    promptTokens, completionTokens,
  });
  if (!parsed || parsed.actions.length === 0) {
    return NextResponse.json({ error: "AI 没有给出可用的拆解结果，请稍后再试" }, { status: 502 });
  }

  // ---- 落库（插入式 sort 定位） ----
  const limit = isAction ? 3 : 10;
  const actions = parsed.actions.slice(0, limit);
  const client = await pool.connect();
  try {
    await client.query("begin");

    let insertSort: number;
    let insertParent: string | null;
    if (isAction && hasParent) {
      // 有父行动：插入到锚点行动之后，后续同父行动 sort 平移
      await client.query(
        `update todos set sort = sort + $1
         where user_id = $2 and parent_todo_id = $3 and kind = 'action' and sort > $4`,
        [actions.length, user.id, todo.parent_todo_id, todo.sort],
      );
      insertSort = todo.sort + 1;
      insertParent = todo.parent_todo_id;
    } else if (isAction) {
      // 独立行动：产出独立行动插入其后，后续独立行动 sort 平移（顶层 todo 恒 sort=0，不受扰动）
      await client.query(
        `update todos set sort = sort + $1
         where user_id = $2 and parent_todo_id is null and kind = 'action' and sort > $3`,
        [actions.length, user.id, todo.sort],
      );
      insertSort = todo.sort + 1;
      insertParent = null;
    } else {
      // 拆顶层 todo：mode 处理已有未完成行动
      const { rows: pendingRows } = await client.query(
        `select id from todos where user_id = $1 and parent_todo_id = $2 and status = 'pending'`,
        [user.id, todo.id],
      );
      if (pendingRows.length > 0 && mode !== "append" && mode !== "replace") {
        await client.query("rollback");
        return NextResponse.json({ needMode: true, existing: pendingRows.length }, { status: 409 });
      }
      if (mode === "replace") {
        await client.query(
          `delete from todos where user_id = $1 and parent_todo_id = $2 and status = 'pending'`,
          [user.id, todo.id],
        );
      }
      const maxRow = (
        await client.query(
          `select coalesce(max(sort), 0)::int as m from todos where user_id = $1 and parent_todo_id = $2`,
          [user.id, todo.id],
        )
      ).rows[0];
      insertSort = maxRow.m + 1;
      insertParent = todo.id;
    }

    const inserted: { id: string; title: string; sort: number }[] = [];
    for (const a of actions) {
      const { rows } = await client.query(
        `insert into todos (user_id, title, source, parent_todo_id, activity_id, space_id, sort, repeat_daily, kind)
         values ($1, $2, 'ai', $3, $4, $5, $6, false, 'action') returning id, title, sort`,
        [user.id, a.title, insertParent, todo.activity_id, todo.space_id, insertSort++],
      );
      inserted.push(rows[0]);
    }
    await client.query("commit");
    return NextResponse.json({ ok: true, actions: inserted, engine: isAction ? "action-decompose" : "todo-decompose" });
  } catch (e) {
    await client.query("rollback").catch(() => {});
    console.error("[decompose] 落库失败:", e);
    return NextResponse.json({ error: "拆解结果保存失败" }, { status: 500 });
  } finally {
    client.release();
  }
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

/** 记录日（06:00 日切）：00:00–05:59 完成仍计入前一记录日 */
const EFF_TODAY = "((now() at time zone 'Asia/Shanghai') - interval '6 hours')::date";

/** PATCH /api/todos/:id —— { done: true } 勾选完成；{ undone: true } 恢复；或传字段修改待办 */
export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const body = (await req.json().catch(() => ({}))) as {
    done?: boolean;
    undone?: boolean;
    title?: string;
    dueAt?: string | null; // ISO；null=清除时间
    startAt?: string | null; // ISO；null=清除起始（区间 todo 用）
    activityId?: string;
    important?: boolean; // ⭐ 重要标记（仅顶层任务，行动随父）
    today?: boolean; // ☀️ 今日标记：true=北京今天，false=清除（跨零点自动失效）
    note?: string | null; // 行动描述内容（≤1000 字；null=清除）
    spaceId?: string | null; // 目标空间归属（null=移除归属）
    repeatDaily?: boolean; // 🔁 每日重复（仅行动）
  };

  // ---- 模式零：恢复为未完成（撤销完成状态；历史版本完成时生成过日程块，一并删除） ----
  if (body.undone === true) {
    const client = await pool.connect();
    try {
      await client.query("begin");
      const todo = (
        await client.query(
          `select * from todos where id = $1 and user_id = $2 and status = 'done'`,
          [id, user.id],
        )
      ).rows[0];
      if (!todo) {
        await client.query("rollback");
        return NextResponse.json({ error: "todo 不存在或未完成" }, { status: 404 });
      }
      if (todo.done_block_id) await client.query(`delete from time_blocks where id = $1`, [todo.done_block_id]);
      const restored = (
        await client.query(
          `update todos set status = 'pending', done_at = null, done_entry_id = null, done_block_id = null
           where id = $1 returning *`,
          [id],
        )
      ).rows[0];
      await client.query("commit");
      return NextResponse.json({ todo: restored });
    } catch (e) {
      await client.query("rollback");
      return NextResponse.json({ error: String(e) }, { status: 500 });
    } finally {
      client.release();
    }
  }

  // ---- 模式一：勾选完成（仅改状态；日程与待办解耦，完成不再生成时间块） ----
  // 每日重复行动：完成次数按记录日去重累加（同记录日反复勾→取消→再勾只计 1 次），并写 last_done_date；
  // 06:00 日切后由列表读取惰性恢复为未完成（undone 不回退计数）
  if (body.done === true) {
    const todo = (
      await pool.query(
        `update todos set
           status = 'done', done_at = now(),
           repeat_done_count = repeat_done_count
             + case when repeat_daily and coalesce(last_done_date, 'epoch'::date) < ${EFF_TODAY} then 1 else 0 end,
           last_done_date = case when repeat_daily then ${EFF_TODAY} else last_done_date end
         where id = $1 and user_id = $2 and status = 'pending' returning *`,
        [id, user.id],
      )
    ).rows[0];
    if (!todo) return NextResponse.json({ error: "todo 不存在或已完成" }, { status: 404 });
    return NextResponse.json({ todo });
  }

  // ---- 模式二：修改字段 ----
  // 今日/重要标记只作用于顶层任务（行动的上下文随父，避免「标记了却不出现在视图」的困惑）
  if (body.important !== undefined || body.today !== undefined) {
    const isChild = (
      await pool.query(`select parent_todo_id from todos where id = $1 and user_id = $2`, [id, user.id])
    ).rows[0]?.parent_todo_id;
    if (isChild) {
      return NextResponse.json({ error: "行动不支持单独标记，请标记父 todo" }, { status: 400 });
    }
  }
  // 每日重复仅对行动生效（kind='action'，N6 后含独立行动；顶层待办不设重复）
  if (body.repeatDaily !== undefined) {
    const kind = (
      await pool.query(`select kind from todos where id = $1 and user_id = $2`, [id, user.id])
    ).rows[0]?.kind;
    if (kind !== "action") {
      return NextResponse.json({ error: "每日重复仅支持行动" }, { status: 400 });
    }
  }
  // 空间归属校验（REQ-002 N1）：
  // ① 有父行动不可单独关联空间（409，随父 todo）；② 新关联/切换只允许 active 空间（400，归档空间可移除不可新挂）
  // ③ spaceId:null 移除关联恒允许
  let spaceId: string | null = null;
  if (body.spaceId) {
    const own = await pool.query(`select parent_todo_id from todos where id = $1 and user_id = $2`, [id, user.id]);
    if (own.rows[0]?.parent_todo_id) {
      return NextResponse.json({ error: "行动随父 todo 关联空间，不可单独设置" }, { status: 409 });
    }
    const hit = await pool.query(`select id, status from goal_spaces where id = $1 and user_id = $2`, [body.spaceId, user.id]);
    if (!hit.rows[0]) return NextResponse.json({ error: "空间不存在" }, { status: 400 });
    if (hit.rows[0].status !== "active") return NextResponse.json({ error: "空间已归档，不可新关联" }, { status: 400 });
    spaceId = hit.rows[0].id;
  }
  const sets: string[] = [];
  const vals: unknown[] = [];
  if (body.title != null) { vals.push(body.title.trim()); sets.push(`title = $${vals.length}`); }
  if (body.dueAt !== undefined) {
    vals.push(body.dueAt); // null 允许，清除时间
    sets.push(`due_at = $${vals.length}::timestamptz`);
    sets.push(`remind_at = ($${vals.length}::timestamptz - interval '15 minutes')`);
  }
  if (body.startAt !== undefined) {
    vals.push(body.startAt); // null 允许，清除起始
    sets.push(`start_at = $${vals.length}::timestamptz`);
  }
  if (body.activityId != null) { vals.push(body.activityId); sets.push(`activity_id = $${vals.length}`); }
  if (body.note !== undefined) {
    const note = body.note?.trim() ? body.note.trim() : null;
    if (note && note.length > 1000) {
      return NextResponse.json({ error: "详情内容太长了（≤1000 字）" }, { status: 400 });
    }
    vals.push(note);
    sets.push(`note = $${vals.length}`);
  }
  if (body.important !== undefined) { vals.push(Boolean(body.important)); sets.push(`is_important = $${vals.length}`); }
  if (body.today !== undefined) {
    // true → 标记为北京今天；false → 清除。查询按 today_tag_date = 今天 过滤，跨零点自动失效
    vals.push(Boolean(body.today));
    sets.push(`today_tag_date = case when $${vals.length} then (now() at time zone 'Asia/Shanghai')::date else null end`);
  }
  if (body.spaceId !== undefined) { vals.push(spaceId); sets.push(`space_id = $${vals.length}::uuid`); }
  if (body.repeatDaily !== undefined) { vals.push(Boolean(body.repeatDaily)); sets.push(`repeat_daily = $${vals.length}`); }
  if (sets.length === 0) {
    return NextResponse.json({ error: "没有可更新的字段" }, { status: 400 });
  }
  vals.push(id, user.id);
  const updated = (
    await pool.query(
      `update todos set ${sets.join(", ")}
       where id = $${vals.length - 1} and user_id = $${vals.length}
       returning *`,
      vals,
    )
  ).rows[0];
  if (!updated) return NextResponse.json({ error: "todo 不存在" }, { status: 404 });
  // N1：归属变更时带最新空间摘要，供行内徽标即时更新
  let space: { id: string; name: string; icon: string; color: string; status: string } | null = null;
  if (body.spaceId !== undefined && updated.space_id) {
    space =
      (
        await pool.query(
          `select id, name, icon, color, status from goal_spaces where id = $1 and user_id = $2`,
          [updated.space_id, user.id],
        )
      ).rows[0] ?? null;
  }
  return NextResponse.json({ todo: updated, space });
}

/** DELETE /api/todos/:id —— 删除待办（已完成的也可删） */
export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const deleted = (
    await pool.query(
      `delete from todos where id = $1 and user_id = $2 returning id, title`,
      [id, user.id],
    )
  ).rows[0];
  if (!deleted) return NextResponse.json({ error: "todo 不存在" }, { status: 404 });
  return NextResponse.json({ ok: true, title: deleted.title });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import type { TodoItem, TodoRow } from "@shiguangri/shared/types";

export const runtime = "nodejs";

/** PG 侧「北京今天」表达式（跨零点惰性失效的今日标记比对基准） */
const BJ_TODAY = "(now() at time zone 'Asia/Shanghai')::date";
/** 记录日（06:00 日切，REQ-001 R3）：00:00–05:59 仍算前一记录日（与全局凌晨回填口径一致） */
const EFF_TODAY = "((now() at time zone 'Asia/Shanghai') - interval '6 hours')::date";

const SELECT_TODO = `
  select t.*, a.name as activity_name, a.icon, a.color
  from todos t left join activities a on a.id = t.activity_id and a.user_id = t.user_id`;

/** 惰性日切：每日重复的已完成行动，记录日推进后首次读取即恢复为未完成（系统惯例：读时判断，无 cron） */
async function restoreRepeating(userId: string): Promise<void> {
  await pool.query(
    `update todos set status = 'pending', done_at = null
     where user_id = $1 and repeat_daily and status = 'done'
       and coalesce(last_done_date, 'epoch'::date) < ${EFF_TODAY}`,
    [userId],
  );
}

/** 智能列表视图：today=今日标记 / important=⭐ / all=全部未完成 / done=已完成 / today-actions=首页今日行动清单（行动级） */
export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const view = new URL(req.url).searchParams.get("view") ?? "all";

  // 计数徽标：四个智能列表的顶层待办数（done 含子待办，勾一个减一个）；今日含过期未完成
  const { rows: countRows } = await pool.query(
    `select
       count(*) filter (where status = 'pending' and parent_todo_id is null and (today_tag_date = ${BJ_TODAY} or (due_at is not null and (due_at at time zone 'Asia/Shanghai')::date < ${BJ_TODAY})))::int as today,
       count(*) filter (where status = 'pending' and is_important and parent_todo_id is null)::int as important,
       count(*) filter (where status = 'pending' and parent_todo_id is null)::int as all_pending,
       count(*) filter (where status = 'done')::int as done
     from todos where user_id = $1`,
    [user.id],
  );
  const counts = {
    today: countRows[0]?.today ?? 0,
    important: countRows[0]?.important ?? 0,
    all: countRows[0]?.all_pending ?? 0,
    done: countRows[0]?.done ?? 0,
  };

  // 首页「今日行动清单」v2（REQ-002 N6）：全部行动（kind='action'，含独立行动）+ 今天到期/过期的顶层 todo
  // 行动：① 每日重复 ② 独立行动标记今日 ③ 行动自身今日到期（含已完成）④ 行动自身已过期未完成
  //       ⑤ 父待办标记今日 ⑥ 父待办今日到期（有父行动随父，现状规则）
  // 顶层 todo：自身今日到期（含已完成——进「今日已完成」可恢复区）或 已过期未完成
  if (view === "today-actions") {
    await restoreRepeating(user.id);
    const { rows } = await pool.query(
      `select x.* from (
         select a.*, p.title as parent_title, p.due_at as parent_due
         from todos a left join todos p on p.id = a.parent_todo_id
         where a.user_id = $1 and a.kind = 'action'
           and ( a.repeat_daily
              or a.today_tag_date = ${BJ_TODAY}
              or ((a.due_at at time zone 'Asia/Shanghai')::date = ${BJ_TODAY})
              or ((a.due_at at time zone 'Asia/Shanghai')::date < ${BJ_TODAY} and a.status = 'pending')
              or p.today_tag_date = ${BJ_TODAY}
              or ((p.due_at at time zone 'Asia/Shanghai')::date = ${BJ_TODAY} and p.status = 'pending') )
         union all
         select t.*, null::text as parent_title, t.due_at as parent_due
         from todos t
         where t.user_id = $1 and t.parent_todo_id is null and t.kind = 'todo'
           and (
             (t.status in ('pending', 'done') and (t.due_at at time zone 'Asia/Shanghai')::date = ${BJ_TODAY})
             or (t.status = 'pending' and t.due_at is not null and (t.due_at at time zone 'Asia/Shanghai')::date < ${BJ_TODAY})
           )
       ) x
       order by (x.status = 'done'), x.parent_due nulls last, x.created_at, x.sort
       limit 200`,
      [user.id],
    );
    return NextResponse.json({ actions: rows, counts });
  }

  // 06:00 日切恢复在四视图读取前执行（重复行动次日回到未完成）
  await restoreRepeating(user.id);

  // 顶层待办：视图过滤 + 排序（重要在前，同组新建在前；done 视图按完成时间倒序）
  const where =
    view === "today" ? `parent_todo_id is null and status = 'pending' and (today_tag_date = ${BJ_TODAY} or (due_at is not null and (due_at at time zone 'Asia/Shanghai')::date < ${BJ_TODAY}))`
    : view === "important" ? `parent_todo_id is null and status = 'pending' and is_important`
    : view === "done" ? `parent_todo_id is null and status = 'done'`
    : `parent_todo_id is null and status = 'pending'`;
  const order = view === "done" ? "t.done_at desc" : "t.is_important desc, t.created_at desc";
  const { rows: parents } = await pool.query(
    `${SELECT_TODO} where t.user_id = $1 and ${where} order by ${order} limit 200`,
    [user.id],
  );

  // 行动随待办返回（仅一层）：未完成在前、完成沉底，按 sort（插入式拆解的定位）
  let todos: TodoItem[] = parents.map((p) => ({ ...p, children: [] }));
  if (parents.length > 0) {
    const ids = parents.map((p) => p.id);
    const { rows: kids } = await pool.query(
      `${SELECT_TODO} where t.user_id = $1 and t.parent_todo_id = any($2::uuid[])
       order by (t.status = 'done'), t.sort, t.created_at`,
      [user.id, ids],
    );
    const byParent = new Map<string, TodoRow[]>(parents.map((p) => [p.id, []]));
    for (const k of kids) byParent.get(k.parent_todo_id)?.push(k);
    todos = parents.map((p) => ({ ...p, children: byParent.get(p.id) ?? [] }));
  }

  return NextResponse.json({ todos, counts });
}

/**
 * POST /api/todos —— 手动新增待办/行动：只需标题，不做时间控制（due_at 留空，
 * 时间感由「无时间」标签呈现，之后仍可在待办行内编辑里补充）。
 * - parentId 建行动（最多一层）；important/today 直接带标记（仅顶层）
 * - spaceId 关联目标空间（校验属主）
 * - afterId 插入式定位（AI 拆解/手动插入）：新行动排在 afterId 行动之后，后续行动 sort 平移
 * - repeatDaily 每日重复（仅行动；06:00 日切惰性恢复）
 */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const body = (await req.json().catch(() => ({}))) as {
    title?: string;
    activityId?: string;
    parentId?: string;
    important?: boolean;
    today?: boolean;
    dueAt?: string | null; // ISO；null/缺省=无时间（之后行内编辑补充）
    note?: string | null; // 行动描述内容（≤1000 字）
    spaceId?: string | null;
    afterId?: string | null;
    repeatDaily?: boolean;
    kind?: "todo" | "action"; // N6 行动解耦：kind='action' 且不传 parentId = 独立行动
  };
  const title = (body.title ?? "").trim();
  if (!title) return NextResponse.json({ error: "标题不能为空" }, { status: 400 });
  if (title.length > 200) return NextResponse.json({ error: "标题太长了（≤200 字）" }, { status: 400 });
  const note = body.note?.trim() ? body.note.trim() : null;
  if (note && note.length > 1000) return NextResponse.json({ error: "详情内容太长了（≤1000 字）" }, { status: 400 });
  const kind = body.kind === "action" ? "action" : "todo";

  // 行动：校验父属主 + 最多一层（父自身不得再有 parent、须 kind='todo' 且未完成）；行动空间缺省继承父待办
  let parentId: string | null = null;
  let parentSpaceId: string | null = null;
  if (body.parentId) {
    const hit = await pool.query(
      `select id, space_id from todos where id = $1 and user_id = $2 and parent_todo_id is null and kind = 'todo' and status = 'pending'`,
      [body.parentId, user.id],
    );
    if (!hit.rows[0]) {
      return NextResponse.json({ error: "只能给未完成的顶层 todo 添加行动" }, { status: 400 });
    }
    parentId = hit.rows[0].id;
    parentSpaceId = hit.rows[0].space_id ?? null;
  }

  // 空间归属：显式指定校验属主；行动未显式指定时继承父待办
  let spaceId: string | null = null;
  if (body.spaceId) {
    const hit = await pool.query(`select id from goal_spaces where id = $1 and user_id = $2`, [body.spaceId, user.id]);
    if (!hit.rows[0]) return NextResponse.json({ error: "空间不存在" }, { status: 400 });
    spaceId = hit.rows[0].id;
  } else if (parentId && body.spaceId === undefined) {
    spaceId = parentSpaceId;
  }

  // 分类：显式指定且属于该用户则用之，否则回退「其他」；再没有就置空（前端显示 📌）
  let activityId: string | null = null;
  if (body.activityId) {
    const hit = await pool.query(`select id from activities where id = $1 and user_id = $2`, [
      body.activityId,
      user.id,
    ]);
    activityId = hit.rows[0]?.id ?? null;
  }
  if (!activityId) {
    const other = await pool.query(
      `select id from activities where user_id = $1 order by (id = 'other') desc, sort_order limit 1`,
      [user.id],
    );
    activityId = other.rows[0]?.id ?? null;
  }

  // 标记只作用于顶层任务（行动随父走）：today=true 写入北京今天的日期
  const marked = !parentId;
  const dueAt = body.dueAt ?? null;

  // 行动插入式定位：afterId（同父行动）之后插入，后续行动 sort 平移；无 afterId 追加尾部
  let sort: number;
  if (parentId) {
    if (body.afterId) {
      const anchor = (
        await pool.query(
          `select sort from todos where id = $1 and user_id = $2 and parent_todo_id = $3`,
          [body.afterId, user.id, parentId],
        )
      ).rows[0];
      if (!anchor) return NextResponse.json({ error: "插入位置不存在" }, { status: 400 });
      await pool.query(
        `update todos set sort = sort + 1 where user_id = $1 and parent_todo_id = $2 and sort > $3`,
        [user.id, parentId, anchor.sort],
      );
      sort = anchor.sort + 1;
    } else {
      const max = (
        await pool.query(`select coalesce(max(sort), 0)::int as m from todos where user_id = $1 and parent_todo_id = $2`, [
          user.id,
          parentId,
        ])
      ).rows[0].m;
      sort = max + 1;
    }
  } else {
    sort = 0;
  }

  const todo = (
    await pool.query(
      `insert into todos (user_id, title, activity_id, source, parent_todo_id, is_important, today_tag_date, due_at, remind_at, note, space_id, sort, repeat_daily, kind)
       values ($1, $2, $3, 'manual', $4, $5,
               ${marked && body.today ? BJ_TODAY : "null"},
               $6, $7, $8, $9, $10, $11, $12) returning *`,
      [
        user.id, title, activityId, parentId, marked && body.important ? true : false,
        dueAt, dueAt ? new Date(new Date(dueAt).getTime() - 15 * 60_000).toISOString() : null,
        note, spaceId, sort,
        parentId || kind === "action" ? body.repeatDaily === true : false, // 每日重复仅对行动生效（含独立行动）
        // 子行动恒为 kind='action'（028 修复：此前带 parentId 新建的行动落了默认 'todo'，导致重复开关 400、行动统计漏计）
        parentId ? "action" : kind,
      ],
    )
  ).rows[0];
  return NextResponse.json({ todo });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

interface Usage {
  calls: number;
  promptTokens: number;
  completionTokens: number;
}

/** GET /api/tokens/usage —— 管理员查看自己与被邀请人的 GLM token 消耗（全部累计 + 近 30 天） */
export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  if (user.role !== "admin") {
    return NextResponse.json({ error: "仅管理员可查看消耗" }, { status: 403 });
  }

  // 一个聚合同时出两个时间窗（近 30 天 / 全部累计）；parse/review/asr 全阶段
  const { rows: selfRows } = await pool.query(
    `select count(*)::int as calls,
            coalesce(sum(prompt_tokens), 0)::bigint as prompt,
            coalesce(sum(completion_tokens), 0)::bigint as completion,
            count(*) filter (where created_at > now() - interval '30 days')::int as calls_30d,
            coalesce(sum(prompt_tokens) filter (where created_at > now() - interval '30 days'), 0)::bigint as prompt_30d,
            coalesce(sum(completion_tokens) filter (where created_at > now() - interval '30 days'), 0)::bigint as completion_30d
     from audit_logs where user_id = $1 and coalesce(model, '') not like 'jev%'`,
    [user.id],
  );
  const s = selfRows[0];
  const self: { all: Usage; d30: Usage } = {
    all: { calls: Number(s.calls), promptTokens: Number(s.prompt), completionTokens: Number(s.completion) },
    d30: { calls: Number(s.calls_30d), promptTokens: Number(s.prompt_30d), completionTokens: Number(s.completion_30d) },
  };

  const { rows: inviteeRows } = await pool.query(
    `select p.id, p.nickname, p.phone, p.created_at,
            count(a.id)::int as calls,
            coalesce(sum(a.prompt_tokens), 0)::bigint as prompt,
            coalesce(sum(a.completion_tokens), 0)::bigint as completion,
            count(a.id) filter (where a.created_at > now() - interval '30 days')::int as calls_30d,
            coalesce(sum(a.prompt_tokens) filter (where a.created_at > now() - interval '30 days'), 0)::bigint as prompt_30d,
            coalesce(sum(a.completion_tokens) filter (where a.created_at > now() - interval '30 days'), 0)::bigint as completion_30d
     from invite_codes i
     join profiles p on p.id = i.used_by
     left join audit_logs a on a.user_id = p.id and coalesce(a.model, '') not like 'jev%'
     where i.created_by = $1 and i.used_by is not null
     group by p.id
     order by sum(a.prompt_tokens) + sum(a.completion_tokens) desc nulls last, p.created_at desc`,
    [user.id],
  );
  const invitees = inviteeRows.map((r) => ({
    id: r.id,
    nickname: r.nickname ?? "未命名",
    phoneTail: r.phone ? r.phone.slice(-4) : null,
    createdAt: r.created_at,
    all: { calls: Number(r.calls), promptTokens: Number(r.prompt), completionTokens: Number(r.completion) },
    d30: { calls: Number(r.calls_30d), promptTokens: Number(r.prompt_30d), completionTokens: Number(r.completion_30d) },
  }));

  const { rows: modelRows } = await pool.query(
    `select model,
            count(*)::int as calls,
            coalesce(sum(prompt_tokens), 0)::bigint as prompt,
            coalesce(sum(completion_tokens), 0)::bigint as completion,
            count(*) filter (where created_at > now() - interval '30 days')::int as calls_30d,
            coalesce(sum(prompt_tokens) filter (where created_at > now() - interval '30 days'), 0)::bigint as prompt_30d,
            coalesce(sum(completion_tokens) filter (where created_at > now() - interval '30 days'), 0)::bigint as completion_30d
     from audit_logs
     where (user_id = $1
        or user_id in (select used_by from invite_codes where created_by = $1 and used_by is not null))
       and coalesce(model, '') not like 'jev%'
     group by model
     order by sum(prompt_tokens) + sum(completion_tokens) desc`,
    [user.id],
  );
  const byModel = modelRows.map((r) => ({
    // 纯离线规则兜底（未调用 LLM）的审计行没有模型名，显示成可读标签而不是空白
    model: r.model || "(离线规则·无模型)",
    all: { calls: Number(r.calls), promptTokens: Number(r.prompt), completionTokens: Number(r.completion) },
    d30: { calls: Number(r.calls_30d), promptTokens: Number(r.prompt_30d), completionTokens: Number(r.completion_30d) },
  }));

  return NextResponse.json({ self, invitees, byModel });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

/** PATCH /api/transactions/:id —— 修正流水（方向/金额/类别/交易对象/账户）；{confirm:true} 草稿转正 */
export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const body = (await req.json().catch(() => ({}))) as {
    direction?: "out" | "in";
    amountCents?: number; // 正整数（方向由 direction 决定）
    category?: string;
    counterparty?: string | null;
    accountId?: string | null;
    confirm?: boolean; // 草稿 → 已确认入账
  };

  const sets: string[] = [];
  const vals: unknown[] = [];
  if (body.direction === "out" || body.direction === "in") {
    vals.push(body.direction);
    sets.push(`direction = $${vals.length}`);
  }
  if (body.amountCents != null) {
    if (!Number.isInteger(body.amountCents) || body.amountCents <= 0) {
      return NextResponse.json({ error: "金额必须为正整数（单位分）" }, { status: 400 });
    }
    vals.push(body.amountCents);
    sets.push(`amount_cents = $${vals.length}`);
  }
  if (body.category?.trim()) {
    vals.push(body.category.trim());
    sets.push(`category = $${vals.length}`);
  }
  if (body.counterparty !== undefined) {
    vals.push(body.counterparty?.trim() || null);
    sets.push(`counterparty = $${vals.length}`);
  }
  if (body.accountId !== undefined) {
    if (body.accountId === null) {
      vals.push(null);
      sets.push(`account_id = $${vals.length}`);
    } else {
      const owned = await pool.query(
        `select id from accounts where id = $1 and user_id = $2 and archived = false`,
        [body.accountId, user.id],
      );
      if (owned.rows.length === 0) {
        return NextResponse.json({ error: "账户不存在" }, { status: 400 });
      }
      vals.push(body.accountId);
      sets.push(`account_id = $${vals.length}`);
    }
  }
  if (body.confirm === true) {
    vals.push(false);
    sets.push(`is_draft = $${vals.length}`);
  }
  if (sets.length === 0) {
    return NextResponse.json({ error: "没有可更新的字段" }, { status: 400 });
  }
  vals.push(id, user.id);

  const updated = (
    await pool.query(
      `update transactions set ${sets.join(", ")}
       where id = $${vals.length - 1} and user_id = $${vals.length} returning *`,
      vals,
    )
  ).rows[0];
  if (!updated) return NextResponse.json({ error: "流水不存在" }, { status: 404 });
  return NextResponse.json({ transaction: updated });
}

/** DELETE /api/transactions/:id —— 删除识别错的流水 */
export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const { id } = await ctx.params;
  const deleted = (
    await pool.query(
      `delete from transactions where id = $1 and user_id = $2 returning id`,
      [id, user.id],
    )
  ).rows[0];
  if (!deleted) return NextResponse.json({ error: "流水不存在" }, { status: 404 });
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { dedupeKey, parseBill, type ImportRow } from "@shiguangri/shared/csv-import";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/transactions/import —— 支付宝/微信 CSV 账单导入
 * body: { text, platform?, accountId?, dryRun? }
 * dryRun=true 只解析与去重做预览，不落库；false 时直接入账（is_draft=false, source=csv_import）
 */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });

  const body = (await req.json().catch(() => ({}))) as {
    text?: string;
    platform?: "alipay" | "wechat";
    accountId?: string | null;
    dryRun?: boolean;
  };
  const text = body.text ?? "";
  if (text.trim().length < 10) {
    return NextResponse.json({ error: "账单内容为空 —— 请上传 CSV 文件或粘贴账单文本" }, { status: 400 });
  }
  if (text.length > 5_000_000) {
    return NextResponse.json({ error: "账单文件过大（>5MB），请分段导出后导入" }, { status: 400 });
  }

  // 解析（平台自动识别；解析失败抛中文错误）
  let parsed;
  try {
    parsed = parseBill(text, body.platform);
  } catch (e) {
    return NextResponse.json({ error: e instanceof Error ? e.message : String(e) }, { status: 400 });
  }
  const { platform, rows, skips } = parsed;

  // 账户归属校验
  let accountId: string | null = null;
  if (body.accountId) {
    const owned = await pool.query(
      `select id, name from accounts where id = $1 and user_id = $2 and archived = false`,
      [body.accountId, user.id],
    );
    if (owned.rows.length === 0) {
      return NextResponse.json({ error: "账户不存在" }, { status: 400 });
    }
    accountId = owned.rows[0].id;
  }

  // ---- 去重 ----
  // 1) 批内去重（同一次导入里的重复行，保留首条）
  const seen = new Set<string>();
  const uniqueRows: ImportRow[] = [];
  let batchDup = 0;
  for (const row of rows) {
    const key = dedupeKey(row);
    if (seen.has(key)) { batchDup++; continue; }
    seen.add(key);
    uniqueRows.push(row);
  }

  // 2) 与库中已有流水比对：有单号查单号；无单号查 时间+金额+方向+对方 指纹（限定已导入流水的时间窗）
  let dbDup = 0;
  const externalNos = uniqueRows.map((r) => r.externalNo).filter((n): n is string => !!n);
  const existNos = new Set<string>();
  if (externalNos.length > 0) {
    const { rows: exist } = await pool.query(
      `select external_no from transactions where user_id = $1 and external_no = any($2)`,
      [user.id, externalNos],
    );
    for (const r of exist) existNos.add(r.external_no);
  }
  const noNoRows = uniqueRows.filter((r) => !r.externalNo);
  const existFps = new Set<string>();
  if (noNoRows.length > 0) {
    const times = noNoRows.map((r) => r.occurredAt).sort();
    const { rows: exist } = await pool.query(
      `select (occurred_at at time zone 'Asia/Shanghai')::text as t, amount_cents, counterparty, direction, source
       from transactions
       where user_id = $1 and source in ('csv_import','manual')
         and occurred_at between $2::timestamptz and $3::timestamptz`,
      [user.id, times[0], times[times.length - 1]],
    );
    for (const r of exist) {
      existFps.add(`fp:${r.t}|${r.amount_cents}|${r.counterparty ?? ""}|${r.direction}`);
    }
  }

  const toImport: ImportRow[] = [];
  for (const row of uniqueRows) {
    if (row.externalNo) {
      if (existNos.has(row.externalNo)) { dbDup++; continue; }
    } else {
      // 库中指纹用北京时间文本（at time zone 'Asia/Shanghai'），本地同样换算后比对
      const bj = new Date(new Date(row.occurredAt).getTime() + 8 * 3600_000)
        .toISOString()
        .slice(0, 19)
        .replace("T", " ");
      if (existFps.has(`fp:${bj}|${row.amountCents}|${row.counterparty ?? ""}|${row.direction}`)) {
        dbDup++;
        continue;
      }
    }
    toImport.push(row);
  }

  // 分类统计（预览展示）
  const categories: Record<string, number> = {};
  for (const r of toImport) categories[r.category] = (categories[r.category] ?? 0) + 1;
  const skipSummary: Record<string, number> = {};
  for (const s of skips) skipSummary[s.reason] = (skipSummary[s.reason] ?? 0) + 1;

  if (body.dryRun) {
    return NextResponse.json({
      platform,
      total: rows.length + skips.length,
      importable: toImport.length,
      batchDup,
      dbDup,
      skipped: skips.length,
      skipSummary,
      categories,
      outCents: toImport.filter((r) => r.direction === "out").reduce((s, r) => s + r.amountCents, 0),
      inCents: toImport.filter((r) => r.direction === "in").reduce((s, r) => s + r.amountCents, 0),
      sample: toImport.slice(0, 8),
    });
  }

  if (toImport.length === 0) {
    return NextResponse.json({
      platform,
      imported: 0,
      dbDup,
      batchDup,
      skipped: skips.length,
      skipSummary,
      message: "没有新流水 —— 全部为重复或不可导入行",
    });
  }

  // ---- 批量插入（分块；外部单号唯一索引兜底并发重复）----
  let imported = 0;
  const CHUNK = 100;
  for (let i = 0; i < toImport.length; i += CHUNK) {
    const chunk = toImport.slice(i, i + CHUNK);
    const values: unknown[] = [user.id, accountId];
    const tuples = chunk.map((r, j) => {
      const b = j * 7;
      values.push(r.direction, r.amountCents, r.category, r.counterparty, r.note, r.occurredAt, r.externalNo);
      return `($1, $${b + 3}, $${b + 4}, $${b + 5}, $${b + 6}, $${b + 7}, $${b + 8}, $${b + 9}, 'csv_import', false, $2)`;
    });
    const { rowCount } = await pool.query(
      `insert into transactions
         (user_id, direction, amount_cents, category, counterparty, note, occurred_at, external_no, source, is_draft, account_id)
       values ${tuples.join(",")}
       on conflict (user_id, external_no) where external_no is not null do nothing`,
      values,
    );
    imported += rowCount ?? 0;
  }

  return NextResponse.json({
    platform,
    imported,
    dbDup,
    batchDup,
    skipped: skips.length,
    skipSummary,
    categories,
  });
}

import { NextResponse } from "next/server";
import { pool } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { TX_CATEGORIES } from "@shiguangri/shared/finance";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const TZ = "Asia/Shanghai";

/** GET /api/transactions?month=YYYY-MM&status=all|draft|confirmed —— 月度流水列表 */
export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const url = new URL(req.url);
  const month = url.searchParams.get("month") ?? "";
  const status = url.searchParams.get("status") ?? "all";
  if (!/^\d{4}-\d{2}$/.test(month)) {
    return NextResponse.json({ error: "month 需为 YYYY-MM" }, { status: 400 });
  }
  const draftCond =
    status === "draft" ? " and t.is_draft = true" : status === "confirmed" ? " and t.is_draft = false" : "";

  const { rows } = await pool.query(
    `select t.id, t.direction, t.amount_cents, t.category, t.counterparty, t.note,
            t.occurred_at, t.is_draft, t.source, t.entry_id, t.account_id,
            a.name as account_name, a.icon as account_icon
     from transactions t
     left join accounts a on a.id = t.account_id
     where t.user_id = $1${draftCond}
       and to_char(t.occurred_at at time zone $2, 'YYYY-MM') = $3
     order by t.occurred_at desc, t.created_at desc`,
    [user.id, TZ, month],
  );
  return NextResponse.json({ transactions: rows });
}

/** POST /api/transactions —— 手动记账（直接为已确认流水） */
export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const body = (await req.json().catch(() => ({}))) as {
    direction?: "out" | "in";
    amountCents?: number;
    category?: string;
    accountId?: string | null;
    occurredAt?: string;
    note?: string | null;
    counterparty?: string | null;
  };

  if (body.direction !== "out" && body.direction !== "in") {
    return NextResponse.json({ error: "方向需为 out/in" }, { status: 400 });
  }
  if (!Number.isInteger(body.amountCents) || (body.amountCents ?? 0) <= 0) {
    return NextResponse.json({ error: "金额必须大于 0" }, { status: 400 });
  }
  const category = body.category?.trim() || "其他";
  if (!TX_CATEGORIES.includes(category)) {
    return NextResponse.json({ error: "无效分类" }, { status: 400 });
  }
  const occurredAt = body.occurredAt ? new Date(body.occurredAt) : new Date();
  if (isNaN(occurredAt.getTime())) {
    return NextResponse.json({ error: "时间格式不正确" }, { status: 400 });
  }

  // 账户归属校验（只能挂自己的账户）
  let accountId: string | null = null;
  if (body.accountId) {
    const owned = await pool.query(
      `select id from accounts where id = $1 and user_id = $2 and archived = false`,
      [body.accountId, user.id],
    );
    if (owned.rows.length === 0) {
      return NextResponse.json({ error: "账户不存在" }, { status: 400 });
    }
    accountId = owned.rows[0].id;
  }

  const created = (
    await pool.query(
      `insert into transactions (user_id, direction, amount_cents, category, account_id, counterparty, note, occurred_at, source, is_draft)
       values ($1, $2, $3, $4, $5, $6, $7, $8, 'manual', false) returning *`,
      [
        user.id,
        body.direction,
        body.amountCents,
        category,
        accountId,
        body.counterparty?.trim() || null,
        body.note?.trim() || null,
        occurredAt.toISOString(),
      ],
    )
  ).rows[0];
  return NextResponse.json({ transaction: created });
}

import { pool, findOverlap, overlapError } from "@/lib/db";
import {
  parseInput, parseHybridInput, SpaceClassification, chat, jevAsk, jevEnabled,
  spaceClassifyQuestions, HybridUnavailableError,
} from "@shiguangri/ai";
import { assembleUserPrompt, getPromptBundle } from "./prompts";
import { ACTIVITY_NAMES, toCstWallClock } from "@shiguangri/ai";
import { inferGroupFromContext, inferInteractionType } from "@shiguangri/shared/social";
import { CONFIDENCE_THRESHOLD, type Domain } from "@shiguangri/ai";
import { writeAuditRecord } from "@/lib/audit";
import { jevShadowCompare } from "@/lib/jev-shadow";
import { getJevMode } from "./ai-mode";

/** 空间自动归属置信阈值（低于不写入） */
const SPACE_CONFIDENCE_THRESHOLD = 0.7;

/**
 * AI 空间归属（REQ-001 R3）：五域识别完成后，若有 active 空间则轻量分类一次；
 * 置信 ≥0.7 且 spaceId 在候选内 → 写入 entries.space_id 并让本动态的待办继承。
 * 失败静默（记 audit_logs stage='space_classify'），不影响主识别流程。
 */
async function classifySpace(userId: string, entryId: string, rawText: string): Promise<void> {
  try {
    const bundle = await getPromptBundle("space_classify");
    const { rows: spaces } = await pool.query(
      `select id, name, description from goal_spaces where user_id = $1 and status = 'active' order by sort limit ${bundle.config.caps.spaceCount}`,
      [userId],
    );
    if (spaces.length === 0) return; // 无 active 空间：跳过分类调用

    // 3-D：接管模式下空间分类整切 Jev（闭集 noul + choice）；失败静默回落下方 GLM 路径
    if ((await getJevMode()) === "on" && jevEnabled()) {
      try {
        const t0 = Date.now();
        const jevCandidates: Record<string, string> = {};
        for (const s of spaces) jevCandidates[s.id] = `${s.name}${s.description ? `：${s.description}` : ""}`;
        const state = `用户随口记录了一句话：\n「${rawText.slice(0, 500)}」`;
        const res = await jevAsk(state, spaceClassifyQuestions(jevCandidates));
        const belongs = res.answers["space_belongs"];
        const which = res.answers["space_which"];
        const pBelongs =
          belongs?.probabilities && typeof belongs.probabilities.true === "number" ? belongs.probabilities.true : null;
        const choice = typeof which?.value === "string" ? which.value : null;
        const confidence =
          choice && choice !== "__none__" ? which?.probabilities?.[choice] ?? which?.confidence ?? null : null;
        const accepted =
          pBelongs !== null &&
          pBelongs >= 0.5 &&
          choice !== null &&
          choice !== "__none__" &&
          confidence !== null &&
          confidence >= SPACE_CONFIDENCE_THRESHOLD &&
          spaces.some((s) => s.id === choice);
        if (accepted) {
          await pool.query(`update entries set space_id = $1 where id = $2 and user_id = $3`, [choice, entryId, userId]);
          await pool.query(`update todos set space_id = $1 where entry_id = $2 and user_id = $3 and space_id is null`, [
            choice, entryId, userId,
          ]);
        }
        void writeAuditRecord({
          userId, entryId, stage: "space_classify",
          model: process.env.JEV_MODEL ?? "jev-latest", engine: "space-classify-jev",
          latencyMs: Date.now() - t0, ok: true,
          error: accepted ? undefined : `skip: p=${pBelongs?.toFixed(2) ?? "null"} choice=${choice} conf=${confidence === null ? "null" : confidence.toFixed(2)}`,
        });
        return;
      } catch (e) {
        // Jev 调用失败：记审计后静默落回 GLM 分类（不进外层 catch——那里语义是「整体失败」）
        console.warn("[space-classify] Jev 归属失败，回落 GLM:", String(e).slice(0, 120));
        void writeAuditRecord({
          userId, entryId, stage: "space_classify",
          model: process.env.JEV_MODEL ?? "jev-latest", engine: "space-classify-jev",
          ok: false, error: String(e).slice(0, 200),
        });
      }
    }

    const candidates = spaces.map((s) => `- ${s.id}：${s.name}${s.description ? `（${s.description}）` : ""}`).join("\n");
    const userPrompt = assembleUserPrompt("space_classify", bundle, { candidates, text: rawText.slice(0, 500) });
    const t0 = Date.now();
    const raw = await chat({
      system: bundle.system,
      user: userPrompt,
      temperature: 0,
      maxTokens: 256,
      timeoutMs: 45_000,
    });
    const parsed = SpaceClassification.safeParse(JSON.parse(extractJsonLoose(raw)));
    if (!parsed.success) return;
    const { spaceId, confidence } = parsed.data;
    if (!spaceId || confidence < SPACE_CONFIDENCE_THRESHOLD) return;
    if (!spaces.some((s) => s.id === spaceId)) return; // spaceId 不在候选内：忽略

    await pool.query(`update entries set space_id = $1 where id = $2 and user_id = $3`, [spaceId, entryId, userId]);
    // 待办继承动态的空间（AI 从带空间动态识别出的待办自动归类）
    await pool.query(`update todos set space_id = $1 where entry_id = $2 and user_id = $3 and space_id is null`, [
      spaceId,
      entryId,
      userId,
    ]);
    void writeAuditRecord({
      userId, entryId, stage: "space_classify",
      model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "space-classify",
      latencyMs: Date.now() - t0, ok: true,
    });
  } catch (e) {
    console.warn("[space-classify] 归属失败（静默忽略）:", String(e).slice(0, 160));
    void writeAuditRecord({
      userId, entryId, stage: "space_classify",
      model: process.env.GLM_MODEL ?? "glm-5.3-flash", engine: "space-classify",
      ok: false, error: String(e).slice(0, 300),
    });
  }
}

/** 宽松提取 JSON（分类输出可能带代码围栏） */
function extractJsonLoose(raw: string): string {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = fenced ? fenced[1] : raw;
  const start = body.indexOf("{");
  const end = body.lastIndexOf("}");
  return start >= 0 && end > start ? body.slice(start, end + 1) : body;
}

/** 登记簿 upsert：每次识别写一行（entry+domain 唯一） */
export async function recordRecognition(
  client: import("pg").PoolClient,
  userId: string,
  entryId: string,
  domain: Domain,
  status: "applied" | "pending" | "none",
  result: unknown,
  confidence: number,
  engine: string,
) {
  await client.query(
    `insert into entry_recognitions (user_id, entry_id, domain, status, result, confidence, engine)
     values ($1,$2,$3,$4,$5,$6,$7)
     on conflict (entry_id, domain) do update set
       status = excluded.status, result = excluded.result,
       confidence = excluded.confidence, engine = excluded.engine, updated_at = now()`,
    [userId, entryId, domain, status, JSON.stringify(result ?? {}), confidence, engine],
  );
}

export interface AnalyzeOutcome {
  /** 日程与已有块冲突时的对块标题（null=无冲突） */
  conflictTitle: string | null;
  pendingDomains: string[];
  /** 与前端 toast 语义一致的 kind */
  kind: "todo" | "block" | "moment";
}

/** 用户已有联系人名单（按最近往来排序，人物识别时供 AI 对齐称呼，条数上限由注入配置控制，默认 100） */
export async function listContactNames(userId: string, limit = 100): Promise<string[]> {
  const { rows } = await pool.query(
    `select c.name from contacts c
     left join (select contact_id, max(occurred_at) as last_at from interactions where user_id = $1 group by contact_id) i
       on i.contact_id = c.id
     where c.user_id = $1
     order by i.last_at desc nulls last, c.created_at desc
     limit $2`,
    [userId, limit],
  );
  return rows.map((r) => r.name).filter(Boolean);
}

/** 解析审计（docs/06 欠账：引擎/模型/耗时/token → audit_logs 成本监控）；失败静默不影响主流程 */
async function writeAudit(
  userId: string,
  entryId: string,
  fields: {
    engine: string;
    model: string | null;
    durationMs: number;
    textLen: number;
    ok: boolean;
    error?: string;
    promptTokens?: number;
    completionTokens?: number;
  },
) {
  await writeAuditRecord({
    userId,
    entryId,
    stage: "parse",
    engine: fields.engine,
    model: fields.model,
    latencyMs: fields.durationMs,
    textLen: fields.textLen,
    ok: fields.ok,
    error: fields.error,
    promptTokens: fields.promptTokens,
    completionTokens: fields.completionTokens,
  });
}

/**
 * 对一条已存在的动态做完整五域识别并落库（发布后后台执行，也被确认/重识别复用）。
 * 心情直接回写 entries；识别结束（成功或失败）由调用方/finally 写 entries.analyzed_at。
 */
export async function analyzeAndPersist(userId: string, entryId: string, rawText: string): Promise<AnalyzeOutcome> {
  const startedAt = Date.now();
  let engine = "rules";
  let model: string | null = null;
  let promptTokens = 0;
  let completionTokens = 0;
  const client = await pool.connect();
  try {
    // 输入装配（3-A）：按 DB 配置开关/参数组装 user prompt；联系人注入关闭时不取数
    const bundle = await getPromptBundle("extract_full");
    const contactsOn = bundle.config.inject.contactList;
    const contactNames = contactsOn ? await listContactNames(userId, bundle.config.caps.contactCount) : [];
    const catList = bundle.config.inject.catList
      ? (Object.keys(ACTIVITY_NAMES) as (keyof typeof ACTIVITY_NAMES)[])
          .slice(0, bundle.config.caps.catCount)
          .map((k) => `${k}=${ACTIVITY_NAMES[k]}`)
          .join("、")
      : "";
    const contactList =
      contactsOn && contactNames.length
        ? `\n已有联系人（人物识别时称呼对齐到名单原文）：${contactNames.join("、")}`
        : "";
    const userPrompt = assembleUserPrompt("extract_full", bundle, {
      nowCst: toCstWallClock(new Date()),
      catList,
      contactList,
      text: rawText,
    });
    // 3-D：管理台模式 on 且 Jev 可用 → 混合引擎（Jev 闭集 + GLM 瘦身开放词汇）；
    // 混合任一环失败 → 回落全量 GLM（其内部再失败才 rules），降级链 Jev→GLM→rules 完整
    const mode = await getJevMode();
    const onUsage = (u: { prompt_tokens: number; completion_tokens: number }) => {
      // 历史消耗口径：修复重问等多轮调用逐次累加，不取最后一次
      promptTokens += u.prompt_tokens;
      completionTokens += u.completion_tokens;
    };
    const fullOpts = {
      contactNames: contactsOn ? contactNames : undefined,
      systemPrompt: bundle.system,
      userPrompt,
      onUsage,
    };
    const r =
      mode === "on" && jevEnabled()
        ? await (async () => {
            const slimBundle = await getPromptBundle("extract_open_vocab");
            const slimUserPrompt = assembleUserPrompt("extract_open_vocab", slimBundle, {
              nowCst: toCstWallClock(new Date()),
              contactList:
                slimBundle.config.inject.contactList && contactNames.length
                  ? `\n已有联系人（称呼对齐到名单原文）：${contactNames.join("、")}`
                  : "",
              text: rawText,
            });
            try {
              return await parseHybridInput(rawText, {
                contactNames: slimBundle.config.inject.contactList ? contactNames : undefined,
                slimSystemPrompt: slimBundle.system,
                slimUserPrompt,
                onUsage,
              });
            } catch (e) {
              const reason = e instanceof HybridUnavailableError ? e.reason : String(e).slice(0, 120);
              console.warn(`[ai] 混合引擎不可用（${reason}），回落全量 GLM，entry=${entryId}`);
              return parseInput(rawText, fullOpts);
            }
          })()
        : await parseInput(rawText, fullOpts);
    engine = r.engine;
    if (r.fallbackReason) console.warn(`[ai] 本次为规则降级（${r.fallbackReason}），entry=${entryId}`);
    // 规则兜底但 LLM 已被调用过（如输出不合格重问后仍失败）时也记模型名：token 消耗要如实归属
    if (r.engine !== "rules" || promptTokens > 0) model = process.env.GLM_MODEL ?? "glm-5.3-flash";
    const pendingDomains: string[] = [];

    await client.query("begin");

    // 心情域：置信度足够才回写动态本体
    const moodOk = !!r.mood.label && r.mood.confidence >= CONFIDENCE_THRESHOLD;
    if (r.mood.label && moodOk) {
      await client.query(`update entries set mood = $2, mood_score = $3 where id = $1`, [entryId, r.mood.label, r.mood.score]);
    }
    if (r.mood.label && !moodOk) pendingDomains.push("mood");

    let conflictTitle: string | null = null;

    // ---- 日程域 ----
    if (r.intent === "todo") {
      await recordRecognition(client, userId, entryId, "schedule", "none", { reason: "未来计划不占时间轴" }, r.scheduleConfidence, r.engine);
    } else if (r.scheduleApplicable && r.scheduleConfidence >= CONFIDENCE_THRESHOLD) {
      const conflict = await findOverlap(userId, r.time.start, r.time.end);
      if (conflict) {
        // 冲突降级为纯动态（保留心情/金额/人物草稿），原因写登记簿供卡片展示
        conflictTitle = conflict.title;
        await recordRecognition(client, userId, entryId, "schedule", "none", { reason: overlapError(conflict, { title: r.title, start: r.time.start, end: r.time.end }) }, r.scheduleConfidence, r.engine);
        await recordRecognition(client, userId, entryId, "finance", r.finance.hasAmount ? (r.financeConfidence >= CONFIDENCE_THRESHOLD ? "applied" : "pending") : "none", r.finance, r.financeConfidence, r.engine);
        if (r.finance.hasAmount && r.financeConfidence >= CONFIDENCE_THRESHOLD) {
          await insertTransaction(client, userId, entryId, r, rawText);
        }
        await persistPeople(client, userId, entryId, r);
      } else {
        const block = (
          await client.query(
            `insert into time_blocks (user_id, entry_id, activity_id, title, start_at, end_at, time_mode, source)
             values ($1,$2,$3,$4,$5,$6,$7,'keyboard') returning *`,
            [userId, entryId, r.activity, r.title, r.time.start, r.time.end, r.time.mode],
          )
        ).rows[0];
        await recordRecognition(client, userId, entryId, "schedule", "applied", { blockId: block.id, title: r.title }, r.scheduleConfidence, r.engine);
      }
    } else if (r.scheduleApplicable) {
      pendingDomains.push("schedule");
    } else {
      await recordRecognition(client, userId, entryId, "schedule", "none", { reason: "无事件信号" }, r.scheduleConfidence, r.engine);
    }

    // ---- 待办域 ----
    // 进行中（已开始未结束）的显式区间：日程块照落，再补一条收尾待办（起始=区间起点，到期=区间终点）
    if (r.intent === "todo" || r.ongoing) {
      if (r.ongoing || r.todoConfidence >= CONFIDENCE_THRESHOLD) {
        const dueAt = r.ongoing ? r.time.end : r.time.start;
        const remind = new Date(new Date(dueAt).getTime() - 15 * 60_000);
        const todo = (
          await client.query(
            `insert into todos (user_id, entry_id, title, activity_id, start_at, due_at, remind_at, source)
             values ($1,$2,$3,$4,$5,$6,$7,'keyboard') returning *`,
            [userId, entryId, r.title, r.activity, r.time.start, dueAt, remind.toISOString()],
          )
        ).rows[0];
        await recordRecognition(client, userId, entryId, "todo", "applied", { todoId: todo.id, title: r.title, dueAt, startAt: r.time.start, ongoing: r.ongoing }, r.todoConfidence, r.engine);
      } else {
        pendingDomains.push("todo");
      }
    } else {
      await recordRecognition(client, userId, entryId, "todo", "none", { reason: "非未来计划" }, r.todoConfidence, r.engine);
    }

    // ---- 财务域（冲突路径已落过则跳过）----
    if (!conflictTitle) {
      if (r.finance.hasAmount && r.financeConfidence >= CONFIDENCE_THRESHOLD) {
        await insertTransaction(client, userId, entryId, r, rawText);
        await recordRecognition(client, userId, entryId, "finance", "applied", r.finance, r.financeConfidence, r.engine);
      } else if (r.finance.hasAmount) {
        pendingDomains.push("finance");
      } else {
        await recordRecognition(client, userId, entryId, "finance", "none", { reason: "无金额" }, r.financeConfidence, r.engine);
      }
      await persistPeople(client, userId, entryId, r);
    }

    // ---- 饮食域 ----
    if (r.diet.applicable && r.diet.confidence >= CONFIDENCE_THRESHOLD) {
      await client.query(
        `insert into diet_records (user_id, entry_id, meal, items, total_kcal)
         values ($1,$2,$3,$4,$5)`,
        [userId, entryId, r.diet.meal, JSON.stringify(r.diet.items), r.diet.totalKcal ?? null],
      );
      await recordRecognition(client, userId, entryId, "diet", "applied", r.diet, r.diet.confidence, r.engine);
    } else if (r.diet.applicable) {
      pendingDomains.push("diet");
    } else {
      await recordRecognition(client, userId, entryId, "diet", "none", { reason: "无食物信号" }, r.diet.confidence, r.engine);
    }

    await client.query("commit");
    void writeAudit(userId, entryId, {
      engine, model, durationMs: Date.now() - startedAt, textLen: rawText.length, ok: true,
      promptTokens, completionTokens,
    });
    // 空间归属（失败静默）：有 active 空间即发起轻量分类（依据是原文本身，与是否落库产物无关）
    void classifySpace(userId, entryId, rawText).catch(() => {});
    // Jev 影子对照（3-C：JEV_MODE=shadow 时与 GLM 结果逐闭集字段比对，仅审计，零用户影响）
    void jevShadowCompare(userId, entryId, rawText, r);
    return {
      conflictTitle,
      pendingDomains,
      kind: r.intent === "todo" ? "todo" : r.intent === "schedule" ? "block" : "moment",
    };
  } catch (e) {
    try {
      await client.query("rollback");
    } catch {
      /* 事务尚未开启（识别阶段失败）时忽略 */
    }
    void writeAudit(userId, entryId, {
      engine, model, durationMs: Date.now() - startedAt, textLen: rawText.length, ok: false, error: String(e).slice(0, 300),
      promptTokens, completionTokens,
    });
    throw e;
  } finally {
    client.release();
  }
}

/** 财务流水落库（主路径与冲突降级路径共用，保证只插一条） */
async function insertTransaction(
  client: import("pg").PoolClient,
  userId: string,
  entryId: string,
  r: import("@shiguangri/ai").ParseResult,
  rawText: string,
) {
  await client.query(
    `insert into transactions (user_id, entry_id, direction, amount_cents, category, counterparty, note, occurred_at)
     values ($1,$2,$3,$4,$5,$6,$7,$8)`,
    [
      userId, entryId,
      r.finance.direction === "in" ? "in" : "out",
      Math.abs(r.finance.amountCents ?? 0),
      r.finance.category ?? "其他",
      r.finance.counterparty ?? null,
      rawText,
      r.time.end,
    ],
  );
}

/** 人际草稿：动态提到的人自动建档 + 记往来（精确名/别名命中已有联系人则复用，避免称呼变体重建档） */
async function persistPeople(
  client: import("pg").PoolClient,
  userId: string,
  entryId: string,
  r: import("@shiguangri/ai").ParseResult,
) {
  for (const p of r.people) {
    // 先精确名/别名匹配（如识别出"王建军"而已有联系人"老王"的别名为它）
    const hit = await client.query(
      `select id, name from contacts where user_id = $1 and (name = $2 or alias = $2) limit 1`,
      [userId, p.name],
    );
    let contactId: string;
    if (hit.rows[0]) {
      contactId = hit.rows[0].id;
    } else {
      contactId = (
        await client.query(
          `insert into contacts (user_id, name) values ($1, $2)
           on conflict (user_id, name) do update set name = excluded.name returning id`,
          [userId, p.name],
        )
      ).rows[0].id;
    }
    const summary = p.event ? (p.event === r.title ? p.event : `${p.event}：${r.title}`) : r.title;
    await client.query(
      `insert into interactions (user_id, contact_id, entry_id, type, summary, occurred_at)
       values ($1,$2,$3,$4,$5,$6)`,
      [userId, contactId, entryId, inferInteractionType(p.event), summary, r.time.end],
    );
  }
}

/**
 * 复盘输入装配（REQ-003 3-A）：review 四档（day/week/month/year）的共享构建路径。
 * 路由与 /admin 装配预览都走 buildReviewCtx——保证「预览即所见即所得」。
 * - 注入开关（bundle.config.inject）关闭的块不取数、不进 ctx
 * - 明细行上限（bundle.config.caps）下沉 SQL LIMIT（cap=0 不设限），并配 count(*) 保留
 *   「（另有 N 条…未展示）」截断注记的真实条数语义
 * - year 动态明细维持心情强度优先抽样（entryCap = 抽样条数，0 = 全量不抽样）
 */
import { pool } from "./db";
import {
  blockLines, entryLines, fetchChainSummaries, loadProfileBlock, sampleEntryRows, todoDoneLines,
} from "./review-input";
import { assembleUserPrompt, type PromptBundle, type PromptKey } from "./prompts";

const TZ = "Asia/Shanghai";

export type ReviewKind = "day" | "week" | "month" | "year";
export interface ReviewPeriod { date?: string; month?: string; year?: string }

const pad2 = (n: number) => String(n).padStart(2, "0");
const localYmd = (x: Date) => `${x.getFullYear()}-${pad2(x.getMonth() + 1)}-${pad2(x.getDate())}`;
const fmtMin = (m: number) => (m >= 60 ? `${Math.floor(m / 60)}小时${m % 60 ? `${m % 60}分` : ""}` : `${m}分`);

/** 行上限截断（含真实总数的截断注记；cap=0 全量保留。修正原 withCap 的「条条/条个」叠字） */
function capLines(lines: string[], cap: number, label: string, total: number): string[] {
  const effective = cap > 0 ? Math.min(cap, lines.length) : lines.length;
  const out = lines.slice(0, effective);
  if (total > effective) out.push(`（另有 ${total - effective} ${label}未展示）`);
  return out;
}

export interface ReviewBuild {
  from: string;
  to: string;
  /** 装配 ctx（已按开关/上限裁剪） */
  ctx: Record<string, string>;
  /** 装配好的最终 user prompt（与线上一致） */
  userPrompt: string;
  /** 数据最近变动时刻（缓存失效门禁用） */
  latest: Date | null;
  /** 路由响应附带的聚合摘要 */
  summary: { timeParts: string[]; todoDone: number };
}

/** 四档复盘共享构建：聚合事实 + 注入/上限裁剪后的明细块 + 小结链 + 画像 → 最终 user prompt */
export async function buildReviewCtx(
  userId: string,
  kind: ReviewKind,
  period: ReviewPeriod,
  bundle: PromptBundle,
): Promise<ReviewBuild> {
  const cfg = bundle.config;
  const key = `review_${kind}` as PromptKey;

  // ---- 期间换算（周一为一周开始；月为自然月；年为自然年）----
  let from: string;
  let to: string;
  let periodLabel: string;
  if (kind === "day") {
    const date = period.date ?? localYmd(new Date());
    from = to = date;
    periodLabel = `日期：${date}`;
  } else if (kind === "week") {
    const d = new Date((period.date ?? localYmd(new Date())) + "T00:00:00");
    const monday = new Date(d.getTime() - ((d.getDay() + 6) % 7) * 86_400_000);
    from = localYmd(monday);
    to = localYmd(new Date(monday.getTime() + 6 * 86_400_000));
    periodLabel = `周期：${from} 至 ${to}`;
  } else if (kind === "month") {
    const month = period.month ?? localYmd(new Date()).slice(0, 7);
    const [y, m] = month.split("-").map(Number);
    from = `${month}-01`;
    to = localYmd(new Date(y, m, 0));
    periodLabel = `周期：${month}月（${from} 至 ${to}）`;
  } else {
    const year = period.year ?? String(new Date().getFullYear());
    from = `${year}-01-01`;
    to = `${year}-12-31`;
    periodLabel = `周期：${year} 年（${from} 至 ${to}）`;
  }

  const baseParams = [userId, TZ, from, to];
  const entryCap = cfg.caps.entryCap ?? 0;
  const blockCap = cfg.caps.blockCap ?? 0;
  const todoCap = cfg.caps.todoCap ?? 0;

  // ---- 聚合 + 明细并行取数（注入关闭的明细不取数；cap>0 下沉 SQL LIMIT）----
  const [timeRows, todoRows, txRows, interactRows, kcalRows, entryRows, subRows, rawEntryRows, blockRows, todoListRows, entryCountRows, blockCountRows, todoCountRows] =
    await Promise.all([
      pool.query(
        `select a.name, a.icon,
                sum(floor(extract(epoch from least((b.end_at at time zone $2), ($4::date + 1))
                         - greatest((b.start_at at time zone $2), $3::date)) / 60))::int as mins
         from time_blocks b join activities a on a.id = b.activity_id and a.user_id = b.user_id
         where b.user_id = $1
           and (b.end_at at time zone $2) > $3::date and (b.start_at at time zone $2) < ($4::date + 1)
         group by 1, 2 order by mins desc limit 5`,
        baseParams,
      ),
      pool.query(
        `select count(*)::int as n from todos
         where user_id = $1 and status = 'done'
           and (done_at at time zone $2)::date between $3::date and $4::date`,
        baseParams,
      ),
      pool.query(
        `select coalesce(sum(case when direction='out' then amount_cents else 0 end),0)::int as out_cents,
                coalesce(sum(case when direction='in' then amount_cents else 0 end),0)::int as in_cents
         from transactions
         where user_id = $1 and is_draft = false
           and (occurred_at at time zone $2)::date between $3::date and $4::date`,
        baseParams,
      ),
      pool.query(
        `select c.name, count(*)::int as n from interactions i join contacts c on c.id = i.contact_id
         where i.user_id = $1 and (i.occurred_at at time zone $2)::date between $3::date and $4::date
         group by 1 order by n desc limit ${kind === "day" ? 5 : 3}`,
        baseParams,
      ),
      // day 独有：饮食总热量事实行
      kind === "day"
        ? pool.query(
            `select coalesce(sum(d.total_kcal), 0)::int as kcal
             from diet_records d join entries e on e.id = d.entry_id
             where d.user_id = $1 and (e.created_at at time zone $2)::date between $3::date and $4::date`,
            baseParams,
          )
        : Promise.resolve({ rows: [{ kcal: 0 }] }),
      pool.query(
        `select count(*)::int as n,
                count(distinct (created_at at time zone $2)::date)::int as days,
                coalesce(array_agg(distinct mood) filter (where mood is not null), '{}') as moods
         from entries
         where user_id = $1 and (created_at at time zone $2)::date between $3::date and $4::date`,
        baseParams,
      ),
      buildSubRows(userId, kind, from, to),
      // 原始明细：year 全量取回（抽样与总数需要）；其余按 cap LIMIT；注入关闭则不查
      cfg.inject.entryDetail
        ? pool.query(
            `select raw_text, mood, mood_score, created_at from entries
             where user_id = $1 and (created_at at time zone $2)::date between $3::date and $4::date
             order by created_at${kind !== "year" && entryCap > 0 ? ` limit ${entryCap}` : ""}`,
            baseParams,
          )
        : Promise.resolve({ rows: [] as Record<string, unknown>[] }),
      cfg.inject.blockDetail
        ? pool.query(
            `select b.title, b.start_at, b.end_at, a.icon, a.name
             from time_blocks b join activities a on a.id = b.activity_id and a.user_id = b.user_id
             where b.user_id = $1
               and (b.end_at at time zone $2) > $3::date and (b.start_at at time zone $2) < ($4::date + 1)
             order by b.start_at${blockCap > 0 ? ` limit ${blockCap}` : ""}`,
            baseParams,
          )
        : Promise.resolve({ rows: [] as Record<string, unknown>[] }),
      cfg.inject.todoDetail
        ? pool.query(
            `select title, done_at from todos
             where user_id = $1 and status = 'done' and (done_at at time zone $2)::date between $3::date and $4::date
             order by done_at${todoCap > 0 ? ` limit ${todoCap}` : ""}`,
            baseParams,
          )
        : Promise.resolve({ rows: [] as Record<string, unknown>[] }),
      // 截断注记所需真实总数（仅 cap>0 且注入开启才查；year 由明细行数直接得）
      cfg.inject.entryDetail && kind !== "year" && entryCap > 0
        ? pool.query(
            `select count(*)::int as n from entries where user_id = $1 and (created_at at time zone $2)::date between $3::date and $4::date`,
            baseParams,
          )
        : Promise.resolve({ rows: [{ n: 0 }] }),
      cfg.inject.blockDetail && blockCap > 0
        ? pool.query(
            `select count(*)::int as n from time_blocks b
             where b.user_id = $1
               and (b.end_at at time zone $2) > $3::date and (b.start_at at time zone $2) < ($4::date + 1)`,
            baseParams,
          )
        : Promise.resolve({ rows: [{ n: 0 }] }),
      cfg.inject.todoDetail && todoCap > 0
        ? pool.query(
            `select count(*)::int as n from todos
             where user_id = $1 and status = 'done' and (done_at at time zone $2)::date between $3::date and $4::date`,
            baseParams,
          )
        : Promise.resolve({ rows: [{ n: 0 }] }),
    ]);

  const timeParts = (timeRows.rows as { icon: string; name: string; mins: number }[]).map(
    (r) => `${r.icon}${r.name} ${fmtMin(r.mins)}`,
  );
  const todoDone = (todoRows.rows[0] as { n: number }).n;

  // ---- facts（聚合 + 子周期对比行）----
  const facts = [
    periodLabel,
    `时间投入：${timeParts.length ? timeParts.join("、") : "无"}`,
    `完成 todo：${todoDone} 件`,
    `支出 ¥${((txRows.rows[0] as { out_cents: number }).out_cents / 100).toFixed(0)} · 收入 ¥${((txRows.rows[0] as { in_cents: number }).in_cents / 100).toFixed(0)}`,
    interactRows.rows.length
      ? `人际互动：${(interactRows.rows as { name: string; n: number }[]).map((r) => `${r.name}${r.n}次`).join("、")}`
      : "人际互动：无",
    `动态 ${(entryRows.rows[0] as { n: number }).n} 条（覆盖 ${(entryRows.rows[0] as { days: number }).days} 天）${(entryRows.rows[0] as { moods: string[] }).moods.length ? `（心情：${(entryRows.rows[0] as { moods: string[] }).moods.join("、")}）` : ""}`,
    ...(kind === "day" && (kcalRows.rows[0] as { kcal: number }).kcal > 0 ? [`饮食约 ${(kcalRows.rows[0] as { kcal: number }).kcal} kcal`] : []),
    ...buildSubLines(kind, period, subRows, from, to),
  ];

  // ---- 明细块（按注入开关与上限裁剪）----
  const entryDetail = cfg.inject.entryDetail
    ? buildEntryBlock(kind, rawEntryRows.rows as EntryRowT[], entryCap, (entryCountRows.rows[0] as { n: number }).n)
    : "";
  const blockDetail = cfg.inject.blockDetail
    ? ["日程块：", ...capLines(blockLines(blockRows.rows as BlockRowT[]), blockCap, "个日程", (blockCountRows.rows[0] as { n: number }).n)].join("\n")
    : "";
  const todoDetail = cfg.inject.todoDetail
    ? ["完成 todo：", ...capLines(todoDoneLines(todoListRows.rows as TodoRowT[]), todoCap, "条 todo", (todoCountRows.rows[0] as { n: number }).n)].join("\n")
    : "";

  // ---- 小结链 + 画像（注入关闭不取数）----
  const chainBlock = cfg.inject.chainBlock ? await buildChain(userId, kind, period) : "";
  const profileCtx = cfg.inject.profileBlock ? await buildProfileCtxValue(userId) : "";

  const ctx: Record<string, string> = {
    facts: facts.join("\n"),
    chainBlock,
    entryDetail,
    blockDetail,
    todoDetail,
    profileBlock: profileCtx,
  };
  const userPrompt = assembleUserPrompt(key, bundle, ctx);

  return {
    from,
    to,
    ctx,
    userPrompt,
    latest: await buildLatest(userId, kind, period),
    summary: { timeParts, todoDone },
  };
}

type EntryRowT = { created_at: string | Date; raw_text: string; mood?: string | null; mood_score?: number | null };
type BlockRowT = { start_at: string | Date; end_at: string | Date; title: string; icon: string; name: string };
type TodoRowT = { done_at: string | Date | null; title: string };

/** year 动态块：心情强度优先抽样（entryCap=条数，0=全量）；其余档：直接逐条（cap 已在 SQL 层生效，total 为真实总数用于截断注记） */
function buildEntryBlock(kind: ReviewKind, rows: EntryRowT[], entryCap: number, entryTotal = rows.length): string {
  if (kind === "year") {
    const sampled = entryCap > 0 ? sampleEntryRows(rows, entryCap) : rows;
    const total = rows.length;
    const used = sampled.length;
    return [
      "代表性原始动态（时间 原文 心情）：",
      [...entryLines(sampled), ...(total > used ? [`（全年共 ${total} 条动态，以上为代表性抽样 ${used} 条）`] : [])].join("\n"),
    ].join("\n");
  }
  return ["原始动态（时间 原文 心情）：", ...capLines(entryLines(rows), entryCap, "条动态", Math.max(rows.length, entryTotal))].join("\n");
}

/** 小结链块：周←7日 / 月←各周 / 年←12月，只取已有缓存（与原 fetchChainSummaries 调用一致） */
async function buildChain(userId: string, kind: ReviewKind, period: ReviewPeriod): Promise<string> {
  if (kind === "day") return "";
  if (kind === "week") {
    const WD = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"];
    const d = new Date((period.date ?? localYmd(new Date())) + "T00:00:00");
    const monday = new Date(d.getTime() - ((d.getDay() + 6) % 7) * 86_400_000);
    const lines = await fetchChainSummaries(
      userId,
      "week",
      Array.from({ length: 7 }, (_, i) => {
        const day = new Date(monday.getTime() + i * 86_400_000);
        return { key: localYmd(day), label: `${WD[i]}(${Number(localYmd(day).slice(5, 7))}/${Number(localYmd(day).slice(8, 10))})` };
      }),
    );
    return lines.length ? "本周各日小结：\n" + lines.join("\n") : "";
  }
  if (kind === "month") {
    const month = period.month ?? localYmd(new Date()).slice(0, 7);
    const [yy, mm] = month.split("-").map(Number);
    const firstDow = (new Date(yy, mm - 1, 1).getDay() + 6) % 7;
    const weekKeys: string[] = [];
    for (let t = new Date(yy, mm - 1, 1).getTime() - firstDow * 86_400_000; t <= new Date(yy, mm, 0).getTime(); t += 7 * 86_400_000) {
      weekKeys.push(localYmd(new Date(t)));
    }
    const lines = await fetchChainSummaries(
      userId,
      "month",
      weekKeys.map((k) => ({ key: k, label: `${Number(k.slice(5, 7))}/${Number(k.slice(8, 10))}周` })),
    );
    return lines.length ? "本月各周小结：\n" + lines.join("\n") : "";
  }
  const year = period.year ?? String(new Date().getFullYear());
  const lines = await fetchChainSummaries(
    userId,
    "year",
    Array.from({ length: 12 }, (_, i) => ({ key: `${year}-${pad2(i + 1)}`, label: `${i + 1}月` })),
  );
  return lines.length ? "全年各月月报小结：\n" + lines.join("\n") : "";
}

