                      <span className={bjDate(space.target_date) < bjToday() ? "text-danger" : undefined}>
                        ⏳ {bjDate(space.target_date)}
                        {bjDate(space.target_date) < bjToday() && " 已过期"}
                      </span>
                    ) : (
                      <span className="text-ink-faint">＋ 设目标</span>
                    )}
                  </button>
                )}
                {days != null && <span>第 {days} 天</span>}
