                      /* ---- 行内编辑器（与日程 todo-board 同交互；点空白/Esc 取消，有改动轻提示） ---- */
                      <Dismissable
                        onClose={() => {
                          const dirty = editTitle !== t.title || editDue !== isoToLocalInput(t.due_at) || editActivity !== (t.activity_id ?? "other");
