                        title={`${t.title}（点击编辑）`}
                      >
                        {t.title}
                      </button>
                      {t.children.length > 0 && <span className="shrink-0 text-[11px] tabular-nums text-ink-faint">{(() => { const p = childProgress(t.children); return p ? `${p.n}/${p.m}` : ""; })()}</span>}
