        {tab === "reflection" && (
          <div className="mb-4">
            <div className="mb-3 flex justify-end">
              <button
                onClick={() => {
                  setEditingReflection(null);
                  setEditorOpen(true);
                }}
                className="btn-primary rounded-xl px-4 py-2 text-sm font-medium"
              >
                ✍️ 写感悟
              </button>
            </div>
