              spaceId={id}
              notify={setMsg}
              onChanged={() => void load()}
              onEdit={({ id: rid }) => {
                // 打开编辑器前拉取全文
                void (async () => {
                  const r = await fetch(`/api/spaces/${id}/reflections/${rid}`);
                  const j = await r.json();
                  if (!r.ok) {
                    setMsg({ ok: false, text: j.error ?? "全文加载失败" });
                    return;
                  }
                  setEditingReflection({ id: rid, content: j.reflection.content });
                  setEditorOpen(true);
                })();
              }}
            />
          </div>
        )}

