            <button
              onClick={openMomentLink}
              className="ml-auto rounded-lg border border-line-soft px-2.5 py-1 text-[11px] font-normal text-ink-mute transition hover:border-emerald-500/50 hover:text-accent"
            >
              🔗 关联动态
            </button>
          </h2>
