                          <button
                            key={t.id}
                            onClick={() => void linkExisting(t.id)}
                            className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash"
                          >
                            <span className="w-5 shrink-0 text-center text-sm leading-none">{t.is_important ? "⭐" : "○"}</span>
                            <span className="min-w-0 flex-1 truncate" title={t.title}>
                              {t.kind === "action" && (
                                <span className="mr-1 inline-flex items-center rounded bg-slate-500/15 px-1 py-0.5 align-middle text-[10px] text-ink-dim">
                                  行动
                                </span>
                              )}
                              {t.title}
                            </span>
                            {tag && <span className={`shrink-0 text-[10px] ${tag.cls}`}>{tag.text}</span>}
                          </button>
                        );
                      })}
                      {shown.length === 0 && (
                        <p className="px-2 py-6 text-center text-[11px] text-ink-faint">
                          {linkItems.length === 0
                            ? "没有未关联的 TODO/行动 —— 顶层条目都已归属空间"
                            : "没有匹配的 TODO/行动"}
                        </p>
                      )}
                    </div>
                    <button
                      onClick={() => setLinkOpen(false)}
                      className="mt-2 w-full rounded-lg border border-line-soft py-1.5 text-[11px] text-ink-mute transition hover:bg-soft"
                    >
                      关闭
                    </button>
                  </>
                );
              })()}
            </Dismissable>,
            document.body,
          )}

        {/* C1 关联动态浮层（桌面居中 / 移动端底部弹层） */}
        {momentLinkOpen &&
          createPortal(
            <Dismissable
              onClose={() => setMomentLinkOpen(false)}
              className="fixed inset-x-0 bottom-0 z-[61] max-h-[70dvh] overflow-y-auto rounded-t-2xl border border-line-soft bg-elevated p-3 safe-bottom shadow-2xl shadow-scrim/70 sm:inset-x-auto sm:bottom-auto sm:top-1/2 sm:left-1/2 sm:w-80 sm:-translate-x-1/2 sm:-translate-y-1/2 sm:rounded-xl sm:p-3"
            >
              <p className="mb-2 flex items-center justify-between px-0.5">
                <span className="text-xs font-semibold text-ink">关联未归属动态</span>
                <span className="text-[10px] tabular-nums text-ink-faint">{momentTotal} 条未归属</span>
              </p>
              <input
                autoFocus
                value={momentQuery}
                onChange={(e) => {
                  setMomentQuery(e.target.value);
                  void loadUnlinkedMoments(e.target.value, 0);
                }}
                placeholder="搜索原文关键字…"
                className="mb-2 w-full rounded-lg border border-line-strong bg-surface px-2.5 py-1.5 text-xs outline-none focus:border-sky-500"
              />
              <div className="max-h-[46dvh] space-y-0.5 overflow-y-auto sm:max-h-72">
                {momentItems.map((m) => (
                  <button
                    key={m.id}
                    onClick={() => void linkMoment(m.id)}
                    className="w-full rounded-lg px-2.5 py-2 text-left transition hover:bg-wash"
                  >
                    <span className="block text-[10px] text-ink-faint">
                      {new Date(m.created_at).toLocaleString("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" })}
                    </span>
                    <span className="mt-0.5 line-clamp-2 block text-xs text-ink">{m.raw_text}</span>
                  </button>
                ))}
                {momentItems.length === 0 && !momentLoading && (
                  <p className="px-2 py-6 text-center text-[11px] text-ink-faint">
                    {momentQuery ? "没有匹配的动态" : "没有未归属的动态 —— 全部都已归入空间"}
                  </p>
                )}
                {momentLoading && <p className="px-2 py-4 text-center text-[11px] text-ink-faint">加载中…</p>}
              </div>
              {momentItems.length < momentTotal && (
                <button
                  onClick={() => void loadUnlinkedMoments(momentQuery, momentItems.length)}
                  className="mt-2 w-full rounded-lg border border-line-soft py-1.5 text-[11px] text-ink-mute transition hover:bg-soft"
                >
                  加载更多（还有 {momentTotal - momentItems.length} 条）
                </button>
              )}
              <button
                onClick={() => setMomentLinkOpen(false)}
                className="mt-2 w-full rounded-lg border border-line-soft py-1.5 text-[11px] text-ink-mute transition hover:bg-soft"
              >
                关闭
              </button>
            </Dismissable>,
            document.body,
          )}

        {/* 空间操作菜单（⋯ 收纳归档/删除；桌面锚定浮层 / 移动端底部弹层） */}
        {spaceMenu && space &&
          createPortal(
            <Dismissable
              onClose={() => setSpaceMenu(false)}
              className="fixed inset-x-0 bottom-0 z-[61] max-h-[70dvh] overflow-y-auto rounded-t-2xl border border-line-soft bg-elevated p-3 safe-bottom shadow-2xl shadow-scrim/70 sm:inset-x-auto sm:bottom-auto sm:w-56 sm:rounded-xl sm:p-2"
              style={spaceMenuPos ? { top: spaceMenuPos.top, left: spaceMenuPos.left } : undefined}
            >
              <div className="mx-auto mb-2 h-1 w-10 rounded-full bg-soft sm:hidden" />
              <p className="mb-1.5 truncate px-1.5 text-[11px] font-medium text-ink-dim">{space.name}</p>
              <div className="space-y-0.5">
                {space.status === "archived" ? (
                  <button
                    onClick={() => setStatus("active")}
                    className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash"
                  >
                    <span className="w-5 shrink-0 text-center text-sm leading-none">📤</span>
                    <span className="min-w-0 flex-1">恢复空间</span>
                  </button>
                ) : (
                  <button
                    onClick={() => setStatus("archived")}
                    className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-warn transition hover:bg-wash"
                  >
                    <span className="w-5 shrink-0 text-center text-sm leading-none">📦</span>
                    <span className="min-w-0 flex-1">归档空间</span>
                  </button>
                )}
                <button
                  onClick={removeSpace}
                  className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-danger transition hover:bg-rose-500/10"
                >
                  <span className="w-5 shrink-0 text-center text-sm leading-none">🗑</span>
                  <span className="min-w-0 flex-1">删除空间</span>
                </button>
              </div>
            </Dismissable>,
            document.body,
          )}

        {menuRow &&
          createPortal(
            <Dismissable
              onClose={() => setMenuRow(null)}
              className="fixed inset-x-0 bottom-0 z-[61] max-h-[70dvh] overflow-y-auto rounded-t-2xl border border-line-soft bg-elevated p-3 safe-bottom shadow-2xl shadow-scrim/70 sm:inset-x-auto sm:bottom-auto sm:w-56 sm:rounded-xl sm:p-2"
              style={menuPos ? { top: menuPos.top, left: menuPos.left } : undefined}
            >
              <div className="mx-auto mb-2 h-1 w-10 rounded-full bg-soft sm:hidden" />
              <p className="mb-1.5 truncate px-1.5 text-[11px] font-medium text-ink-dim">{menuRow.todo.title}</p>
                <div className="space-y-0.5">
                  {menuRow.isChild ? (
                    <>
                      <button
                        onClick={() => { const c = menuRow.todo; setMenuRow(null); openNote(c); }}
                        className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash"
                      >
                        <span className="w-5 shrink-0 text-center text-sm leading-none">✏️</span>
                        <span className="min-w-0 flex-1">编辑标题 / 描述</span>
                      </button>
                      {menuRow.todo.status !== "done" && (
                        <button
                          onClick={() => { setMenuRow(null); decompose({ id: menuRow.todo.id, title: menuRow.todo.title, isAction: true }); }}
                          disabled={busyId === menuRow.todo.id}
                          className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash disabled:opacity-40"
                        >
                          <span className="w-5 shrink-0 text-center text-sm leading-none">{busyId === menuRow.todo.id ? "⏳" : "✨"}</span>
                          <span className="min-w-0 flex-1">
                            AI 细化为更小行动
                            <span className="block truncate text-[10px] text-ink-faint">插入到该行动之后</span>
                          </span>
                        </button>
                      )}
                      <button
                        onClick={() => { setMenuRow(null); removeTodo(menuRow.todo.id, menuRow.todo.title); }}
                        className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-danger transition hover:bg-rose-500/10"
                      >
                        <span className="w-5 shrink-0 text-center text-sm leading-none">🗑</span>
                        <span className="min-w-0 flex-1">删除行动</span>
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        onClick={() => { const t = menuRow.todo; setMenuRow(null); startEdit(t); }}
                        className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash"
                      >
                        <span className="w-5 shrink-0 text-center text-sm leading-none">✏️</span>
                        <span className="min-w-0 flex-1">编辑标题与时间</span>
                      </button>
                      <button
                        onClick={() => { const t = menuRow.todo; setMenuRow(null); setPickerRow({ id: t.id, spaceId: t.space_id }); }}
                        className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash"
                      >
                        <span className="w-5 shrink-0 text-center text-sm leading-none">🎯</span>
                        <span className="min-w-0 flex-1">关联空间</span>
                      </button>
                      {menuRow.todo.status !== "done" && (
                        <button
                          onClick={() => { setMenuRow(null); decompose({ id: menuRow.todo.id, title: menuRow.todo.title, isAction: false }); }}
                          disabled={busyId === menuRow.todo.id}
                          className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-ink transition hover:bg-wash disabled:opacity-40"
                        >
                          <span className="w-5 shrink-0 text-center text-sm leading-none">{busyId === menuRow.todo.id ? "⏳" : "✨"}</span>
                          <span className="min-w-0 flex-1">
                            AI 拆解为可执行的行动
                            <span className="block truncate text-[10px] text-ink-faint">拆出 ≤10 个行动</span>
                          </span>
                        </button>
                      )}
                      <button
                        onClick={() => { setMenuRow(null); removeTodo(menuRow.todo.id, menuRow.todo.title); }}
                        className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-xs text-danger transition hover:bg-rose-500/10"
                      >
                        <span className="w-5 shrink-0 text-center text-sm leading-none">🗑</span>
                        <span className="min-w-0 flex-1">
                          删除 todo
                          <span className="block truncate text-[10px] text-ink-faint">其下行动一并删除</span>
                        </span>
                      </button>
                    </>
                  )}
                </div>
            </Dismissable>,
            document.body,
          )}

        {/* N2 感悟编辑器（底部抽屉，N3 点空白取消） */}
        <ReflectionEditor
          open={editorOpen}
          initial={editingReflection?.content ?? ""}
          busy={refEditorBusy}
          notify={setMsg}
          onCancel={() => setEditorOpen(false)}
          onSave={saveReflection}
        />

        {/* N1 行级空间关联浮层 */}
        {pickerRow &&
          createPortal(
            <SpacePicker
              spaces={allSpaces}
              currentId={pickerRow.spaceId}
              busy={false}
              onPick={(sid) => void pickSpace(pickerRow.id, sid)}
              onRemove={() => void pickSpace(pickerRow.id, null)}
              onClose={() => setPickerRow(null)}
            />,
            document.body,
          )}
      </div>
    </main>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import TodoLogo from "./todo-logo";
import { TodoCircle, dueTag } from "./todo-bits";
import { Dismissable } from "./dismissable";
import type { TodayAction } from "@/lib/types";

/**
 * 首页「今日行动清单」（REQ-001 R3 + REQ-002 N6）：
 * - 展示行动级条目：① 🔁 每日重复；② 独立行动标记今日/今日到期；③ 有父行动随父待办今日
 * - N6：顶部「添加行动」输入行——回车即建独立行动（默认标记今日），做完勾掉
 * - N3：行内编辑器点空白/Esc 取消（有改动轻提示）
 * - 数据自取 /api/todos?view=today-actions（06:00 记录日惰性日切在服务端读取时触发）
 */
export default function ActionsToday({ notify }: { notify: (e: { ok: boolean; text: string } | null) => void }) {
  const [actions, setActions] = useState<TodayAction[] | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  // N6 添加行动
  const [newTitle, setNewTitle] = useState("");
  const [adding, setAdding] = useState(false);
  // N6/N3 行内编辑
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [editDue, setEditDue] = useState("");
  const editInputRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/todos?view=today-actions");
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "加载失败");
      setActions(j.actions ?? []);
    } catch (e) {
      setActions([]);
      notify({ ok: false, text: `行动清单加载失败：${e instanceof Error ? e.message : e}` });
    }
  }, [notify]);

  useEffect(() => {
    void load();
  }, [load]);

  /** N6：直接添加独立行动（默认标记今日，当日出现在清单） */
  async function addAction() {
    const t = newTitle.trim();
    if (!t || adding) return;
    setAdding(true);
    try {
      const r = await fetch("/api/todos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: t, kind: "action", today: true }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "创建失败");
      setNewTitle("");
      notify({ ok: true, text: `⚡ 已添加行动「${t}」` });
      await load();
    } catch (e) {
      notify({ ok: false, text: e instanceof Error ? e.message : String(e) });
    } finally {
      setAdding(false);
    }
  }

  async function toggleDone(a: TodayAction) {
    const done = a.status === "done";
    setBusyId(a.id);
    await fetch(`/api/todos/${a.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(done ? { undone: true } : { done: true }),
    });
    setBusyId(null);
    if (a.repeat_daily && !done) {
      notify({ ok: true, text: `🎉 完成「${a.title}」，已坚持 ×${a.repeat_done_count + 1}` });
    }
    await load();
  }

  /** N6：删除行动（独立/有父皆可，confirm 确认） */
  async function removeAction(a: TodayAction) {
    if (!window.confirm(`删除行动「${a.title}」？`)) return;
    await fetch(`/api/todos/${a.id}`, { method: "DELETE" });
    notify({ ok: true, text: "🗑 行动已删除" });
    await load();
  }

  /** N6/N3：行内编辑（标题+截止），Enter 保存、点空白/Esc 取消 */
  function startEdit(a: TodayAction) {
    setEditingId(a.id);
    setEditTitle(a.title);
    setEditDue(
      a.due_at
        ? (() => {
            const d = new Date(a.due_at);
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}T${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
          })()
        : "",
    );
    setTimeout(() => editInputRef.current?.focus(), 60);
  }

  async function saveEdit() {
    if (!editingId || !editTitle.trim()) return;
    await fetch(`/api/todos/${editingId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: editTitle.trim(),
        dueAt: editDue ? new Date(editDue).toISOString() : null,
      }),
    });
    setEditingId(null);
    await load();
  }

  const pending = (actions ?? []).filter((a) => a.status === "pending");
  const done = (actions ?? []).filter((a) => a.status === "done");

  /** 行动行（独立行动无父上下文行） */
  function ActionRow({ a }: { a: TodayAction }) {
    const tag = dueTag(a.due_at) ?? dueTag(a.parent_due);
    return (
      <div className="min-w-0 flex-1">
        <p className="flex min-w-0 items-center gap-2">
          <span className="min-w-0 truncate text-sm text-ink">{a.title}</span>
          {!a.parent_title && (
            <span className="shrink-0 rounded-lg bg-slate-500/15 px-1.5 py-0.5 text-[10px] font-medium text-ink-dim" title="独立行动（不属于任何 todo）">
              行动
            </span>
          )}
          {a.repeat_daily && (
            <span className="shrink-0 rounded-lg bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-medium text-success" title="每日重复">
              🔁 {a.repeat_done_count > 0 ? `×${a.repeat_done_count}` : ""}
            </span>
          )}
          {a.note && <span className="shrink-0 text-[10px] text-ink-faint" title="有描述">📄</span>}
        </p>
        {(a.parent_title || tag) && (
          <p className="mt-0.5 flex items-center gap-1.5 text-[11px] text-ink-faint">
            {a.parent_title && <span className="min-w-0 truncate">来自「{a.parent_title}」</span>}
            {tag && <span className={`shrink-0 ${tag.cls}`}>{tag.text}</span>}
          </p>
        )}
      </div>
    );
  }

  return (
    <section className="glass mb-5 rounded-2xl p-5" id="actions">
      {/* 标题行 */}
      <div className="mb-2 flex items-center justify-between">
        <h2 className="flex items-center gap-2 text-sm font-semibold text-ink-soft">
          <TodoLogo size={17} />
          <span>今日行动</span>
          {(actions?.length ?? 0) > 0 && (
            <span className="whitespace-nowrap text-xs font-normal text-ink-dim">
              {done.length}/{actions!.length} 完成
            </span>
          )}
        </h2>
        <a href="/schedule?tab=todo" className="shrink-0 rounded-lg px-2.5 py-1 text-xs font-medium text-accent transition hover:bg-sky-500/10">
          规划 →
        </a>
      </div>

      {actions === null ? (
        <p className="py-2 text-xs text-ink-dim">加载中…</p>
      ) : (
        <>
          {/* N6：添加行动行（回车即建，默认标记今日） */}
          <div className="mb-2 flex items-center gap-2.5 rounded-xl border border-dashed border-line-strong px-2.5 py-2 transition focus-within:border-sky-500/60">
            <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 border-dashed border-slate-500 opacity-70" />
            <input
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.nativeEvent.isComposing) void addAction();
              }}
              maxLength={200}
              placeholder="添加行动，回车保存（自动标记今日）"
              className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-ink-faint"
            />
            {newTitle.trim() && (
              <button
                onClick={() => void addAction()}
                disabled={adding}
                className="btn-primary shrink-0 rounded-lg px-3 py-1 text-[11px] font-medium disabled:opacity-50"
              >
                {adding ? "保存中…" : "添加"}
              </button>
            )}
          </div>

          {pending.length === 0 && done.length === 0 ? (
            <div className="py-2 text-center">
              <p className="text-xs text-ink-dim">今天还没有行动 —— 在上面直接添加一条，把 todo 标为今日（☀️），或在 todo 里 ✨ 拆解出可执行的行动</p>
              <a href="/schedule?tab=todo" className="mt-2 inline-block text-xs font-medium text-accent hover:underline">
                去「日程 · todo」规划 →
              </a>
            </div>
          ) : (
            <>
              <ul className="space-y-0.5">
                {pending.map((a) => {
                  // 到期提示：行动自身优先，父待办兜底（独立行动只有自身 due）
                  const tag = dueTag(a.due_at) ?? dueTag(a.parent_due);
                  const isEditing = editingId === a.id;
                  return (
                    <li key={a.id} className="group flex items-center gap-3 rounded-lg px-2 py-1.5 transition hover:bg-elevated/60">
                      {isEditing ? (
                        /* N3/N6 行内编辑：标题 + 截止；点空白/Esc 取消 */
                        <Dismissable
                          onClose={() => {
                            const dirty = editTitle !== a.title || editDue !== (a.due_at ? new Date(a.due_at).toISOString().slice(0, 16) : "");
                            if (dirty) notify({ ok: true, text: "已取消，未保存" });
                            setEditingId(null);
                          }}
                          className="min-w-0 flex-1 rounded-lg border border-sky-500/40 bg-elevated/60 p-2"
                        >
                          <input
                            ref={editInputRef}
                            value={editTitle}
                            onChange={(e) => setEditTitle(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter" && !e.nativeEvent.isComposing) void saveEdit();
                              if (e.key === "Escape") setEditingId(null);
                            }}
                            className="w-full rounded border border-line-strong bg-surface px-2 py-1 text-sm outline-none focus:border-sky-500"
                          />
                          <div className="mt-1.5 flex items-center gap-2">
                            <input
                              type="datetime-local"
                              value={editDue}
                              onChange={(e) => setEditDue(e.target.value)}
                              className="rounded border border-line-strong bg-surface px-2 py-1 text-[11px] tabular-nums outline-none focus:border-sky-500"
                            />
                            <div className="ml-auto flex gap-2">
                              <button onClick={() => setEditingId(null)} className="rounded px-2 py-1 text-[11px] text-ink-mute hover:bg-soft">取消</button>
                              <button onClick={() => void saveEdit()} disabled={!editTitle.trim()} className="rounded bg-sky-600 px-2.5 py-1 text-[11px] font-medium text-white hover:bg-sky-500 disabled:opacity-50">保存</button>
                            </div>
                          </div>
                        </Dismissable>
                      ) : (
                        <>
                          <TodoCircle size="md" done={false} onClick={() => toggleDone(a)} />
                          <ActionRow a={a} />
                          {/* N6 行操作（hover 显 / 触屏常显） */}
                          <span className="row-actions hidden shrink-0 items-center gap-0.5 group-hover:flex">
                            <button onClick={() => startEdit(a)} title="编辑行动" className="rounded px-1.5 py-0.5 text-xs text-ink-mute opacity-70 transition hover:bg-soft hover:text-ink">✏️</button>
                            <button onClick={() => void removeAction(a)} title="删除行动" className="rounded px-1.5 py-0.5 text-xs text-ink-mute opacity-70 transition hover:bg-soft hover:text-danger">🗑</button>
                          </span>
                        </>
                      )}
                    </li>
                  );
                })}
              </ul>

              {/* 今日已完成 */}
              {done.length > 0 && (
                <details className="mt-2 border-t border-line-soft pt-2">
                  <summary className="cursor-pointer text-xs text-ink-dim">今日已完成 {done.length} 项（可恢复）</summary>
                  <ul className="mt-1.5 space-y-1">
                    {done.map((a) => (
                      <li key={a.id} className="group flex items-center gap-3 rounded-lg px-2 py-1">
                        <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-600/80 text-[9px] text-white">✓</span>
                        <span className="min-w-0 flex-1 truncate text-xs text-ink-dim line-through">{a.title}</span>
                        {a.repeat_daily && a.repeat_done_count > 0 && (
                          <span className="shrink-0 text-[10px] text-success">×{a.repeat_done_count}</span>
                        )}
                        <button
                          onClick={() => toggleDone(a)}
                          title="恢复为未完成"
                          className="row-actions hidden shrink-0 rounded px-1.5 py-0.5 text-xs text-ink-mute hover:bg-soft hover:text-warn group-hover:block"
                        >
                          ↩️
                        </button>
                      </li>
                    ))}
                  </ul>
                </details>
              )}
            </>
          )}
        </>
      )}
    </section>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { TagChip, FilterChip } from "./tag-chip";

/**
 * /admin · AI 管理模块（REQ-001 R4 + REQ-003 3-A 三段式详情）：
 * - 左列 prompt 清单（分类分组、覆盖态徽标、启用开关）；移动端横滑、PC 左栏
 * - 右侧三段：① System prompt（编辑/对比默认值/✨AI 优化）
 *              ② 输入装配（user 模板编辑 + 占位符校验/一键补齐 + 注入开关 + 参数 + 装配预览·零 token）
 *              ③ 版本历史（三件套快照，载入单件/整体回滚；启用开关关闭=整 key 回退代码默认）
 * - 保存一次提交三段（未改字段原样回传语义：改回默认值 = 清除该覆盖）
 */

interface InjectSpec { key: string; label: string; desc: string; source: string; required?: boolean; default: boolean }
interface CapSpec { key: string; label: string; min: number; max: number; default: number }
interface RegistrySpec {
  userTemplate: string;
  placeholders: string[];
  injects: InjectSpec[];
  caps: CapSpec[];
}
interface CtxConfig { inject?: Record<string, boolean>; caps?: Record<string, number> }

interface PromptItem {
  key: string;
  title: string;
  category: "识别" | "复盘" | "目标" | "系统";
  enabled: boolean;
  overridden: boolean;
  dbContent: string | null;
  remark: string | null;
  updatedAt: string | null;
  defaultContent: string;
  userTemplate: string | null;
  userTemplateDefault: string;
  contextConfig: CtxConfig | null;
  effectiveConfig: { inject: Record<string, boolean>; caps: Record<string, number> };
  registry: RegistrySpec;
}

interface Version {
  id: number;
  content: string;
  payload: { system?: string; userTemplate?: string | null; contextConfig?: CtxConfig | null } | null;
  restored_from: number | null;
  created_at: string;
  created_by_name: string | null;
  size: number;
}

const zhTime = (iso: string | null) => {
  if (!iso) return "—";
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getMonth() + 1)}/${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
};

/** 占位符完整性校验（与服务端同规则）：缺失与未知清单 */
function validateTpl(tpl: string, placeholders: string[]): { missing: string[]; unknown: string[] } {
  const found = new Set<string>();
  const re = /\{([a-zA-Z_]\w*)\}/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(tpl))) found.add(m[1]);
  const known = new Set(placeholders);
  return { missing: placeholders.filter((p) => !found.has(p)), unknown: [...found].filter((p) => !known.has(p)) };
}

type Section = "system" | "input" | "versions";

/** 调用引擎模式（REQ-003 3-C 管理台开关）：off=全 GLM / shadow=影子对照 / on=实时接管（3-D 已上线） */
type EngineMode = "off" | "shadow" | "on";
const MODE_META: Record<EngineMode, { label: string; desc: string }> = {
  off: { label: "关闭", desc: "全部走 GLM，Jev 不参与" },
  shadow: { label: "影子对照", desc: "GLM 行为不变；每次识别后台同题调 Jev，只写一致率审计" },
  on: { label: "实时接管", desc: "闭集判断与空间归属切 Jev，开放词汇由 GLM 瘦身提取；Jev 失败自动回落全量 GLM" },
};

export default function AdminAiPanel({ notify }: { notify: (text: string, ok?: boolean) => void }) {
  const [items, setItems] = useState<PromptItem[] | null>(null);
  const [sel, setSel] = useState<PromptItem | null>(null);
  const [draft, setDraft] = useState("");
  const [enabled, setEnabled] = useState(true);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showCompare, setShowCompare] = useState(false);
  const [optHint, setOptHint] = useState("");
  const [optimizing, setOptimizing] = useState(false);
  const [suggestion, setSuggestion] = useState<string | null>(null);
  // 引擎模式开关
  const [engineMode, setEngineMode] = useState<EngineMode>("off");
  const [engineEnvDefault, setEngineEnvDefault] = useState<EngineMode>("off");
  const [engineSaving, setEngineSaving] = useState(false);
  // 3-A 输入装配
  const [tplDraft, setTplDraft] = useState("");
  const [injectDraft, setInjectDraft] = useState<Record<string, boolean>>({});
  const [capsDraft, setCapsDraft] = useState<Record<string, number>>({});
  const [previewSample, setPreviewSample] = useState("");
  const [previewPeriod, setPreviewPeriod] = useState("");
  const [previewing, setPreviewing] = useState(false);
  const [previewText, setPreviewText] = useState<string | null>(null);
  // 版本历史
  const [versions, setVersions] = useState<Version[] | null>(null);
  const [showVersions, setShowVersions] = useState(false);

  const load = useCallback(async () => {
    const r = await fetch("/api/admin/prompts");
    const j = await r.json();
    if (!r.ok) {
      notify(j.error ?? "加载失败", false);
      return;
    }
    setItems(j.items as PromptItem[]);
    return j.items as PromptItem[];
  }, [notify]);

  const loadVersions = useCallback(async (key: string) => {
    const r = await fetch(`/api/admin/prompts/${key}`);
    setVersions(r.ok ? (await r.json()).versions : null);
  }, []);

  useEffect(() => {
    load().then((list) => {
      if (list?.length) pick(list[0]);
    });
    fetch("/api/admin/ai-mode").then(async (r) => {
      if (!r.ok) return;
      const j = await r.json();
      setEngineMode(j.mode);
      setEngineEnvDefault(j.envDefault);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function switchEngineMode(mode: EngineMode) {
    if (engineSaving || mode === engineMode) return;
    setEngineSaving(true);
    try {
      const r = await fetch("/api/admin/ai-mode", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mode }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "切换失败");
      setEngineMode(mode);
      notify(`调用引擎已切换为「${MODE_META[mode].label}」，立即生效`);
    } catch (e) {
      notify(e instanceof Error ? e.message : String(e), false);
    } finally {
      setEngineSaving(false);
    }
  }

  function pick(item: PromptItem) {
    setSel(item);
    setDraft(item.dbContent ?? item.defaultContent);
    setEnabled(item.enabled);
    setDirty(false);
    setSuggestion(null);
    setShowCompare(false);
    setTplDraft(item.userTemplate ?? item.userTemplateDefault);
    setInjectDraft({ ...item.effectiveConfig.inject });
    setCapsDraft({ ...item.effectiveConfig.caps });
    setPreviewText(null);
    setPreviewSample("");
    setPreviewPeriod("");
    void loadVersions(item.key);
  }

  const tplMissing = sel ? validateTpl(tplDraft, sel.registry.placeholders).missing : [];
  const tplUnknown = sel ? validateTpl(tplDraft, sel.registry.placeholders).unknown : [];
  const tplDirty = sel ? tplDraft !== sel.userTemplateDefault || !!sel.userTemplate : false;
  const cfgDirty = sel
    ? sel.registry.injects.some((i) => (injectDraft[i.key] ?? i.default) !== (sel.effectiveConfig.inject[i.key] ?? i.default)) ||
      sel.registry.caps.some((c) => (capsDraft[c.key] ?? c.default) !== (sel.effectiveConfig.caps[c.key] ?? c.default))
    : false;

  async function save() {
    if (!sel || !draft.trim() || saving) return;
    if (tplMissing.length || tplUnknown.length) {
      notify(`user 模板占位符未通过：${[...tplMissing.map((x) => `{${x}}缺失`), ...tplUnknown.map((x) => `{${x}}未知`)].join("、")}`, false);
      return;
    }
    setSaving(true);
    try {
      const r = await fetch(`/api/admin/prompts/${sel.key}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          content: draft,
          enabled,
          // 改回默认值 = 清除覆盖（null）；有改动才提交覆盖
          userTemplate: tplDirty ? tplDraft : null,
          contextConfig: cfgDirty ? { inject: injectDraft, caps: capsDraft } : null,
        }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "保存失败");
      notify(`「${sel.title}」已保存并即时生效`);
      const list = await load();
      const fresh = list?.find((x) => x.key === sel.key);
      if (fresh) pick(fresh);
    } catch (e) {
      notify(e instanceof Error ? e.message : String(e), false);
    } finally {
      setSaving(false);
    }
  }

  async function revertDefault() {
    if (!sel || !window.confirm(`恢复「${sel.title}」为代码默认值？（删除 DB 覆盖：system/user 模板/注入配置全部回退，立即生效）`)) return;
    const r = await fetch(`/api/admin/prompts/${sel.key}`, { method: "DELETE" });
    if (r.ok) {
      notify(`「${sel.title}」已恢复代码默认`);
      const list = await load();
      const fresh = list?.find((x) => x.key === sel.key);
      if (fresh) pick(fresh);
    } else notify("操作失败", false);
  }

  async function rollback(v: Version) {
    if (!sel || !window.confirm(`整体回滚到 ${zhTime(v.created_at)} 的版本？（system + user 模板 + 注入配置三件套，立即生效）`)) return;
    const r = await fetch(`/api/admin/prompts/${sel.key}/restore`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ versionId: v.id }),
    });
    const j = await r.json();
    if (!r.ok) {
      notify(j.error ?? "回滚失败", false);
      return;
    }
    notify(`已回滚到 ${zhTime(v.created_at)} 的版本`);
    const list = await load();
    const fresh = list?.find((x) => x.key === sel.key);
    if (fresh) pick(fresh);
  }

  async function optimize() {
    if (!sel || optimizing) return;
    setOptimizing(true);
    setSuggestion(null);
    try {
      const r = await fetch(`/api/admin/prompts/${sel.key}/optimize`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ hint: optHint }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "优化失败");
      setSuggestion(j.suggestion);
    } catch (e) {
      notify(e instanceof Error ? e.message : String(e), false);
    } finally {
      setOptimizing(false);
    }
  }

  async function runPreview() {
    if (!sel || previewing) return;
    setPreviewing(true);
    try {
      const r = await fetch(`/api/admin/prompts/${sel.key}/preview`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sample: previewSample || undefined, period: previewPeriod || undefined }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error ?? "预览失败");
      setPreviewText(j.userPrompt);
    } catch (e) {
      notify(e instanceof Error ? e.message : String(e), false);
    } finally {
      setPreviewing(false);
    }
  }

  if (!items) return <p className="py-10 text-center text-xs text-ink-dim">加载中…</p>;

  const categories: PromptItem["category"][] = ["识别", "复盘", "目标", "系统"];
  const isReview = sel?.key.startsWith("review_") ?? false;
  const periodPlaceholder = sel?.key === "review_month" ? "期间 YYYY-MM（空=本月）" : sel?.key === "review_year" ? "期间 YYYY（空=今年）" : "期间 YYYY-MM-DD（空=今天）";

  return (
    <div>
      {/* 调用引擎模式开关（REQ-003 3-C 管理台开关） */}
      <div className="glass mb-4 rounded-2xl p-4">
        <div className="mb-2 flex flex-wrap items-center gap-2">
          <h3 className="text-sm font-semibold text-ink">🧭 调用引擎模式</h3>
          <TagChip label="Jev 影子观察期" tone="amber" size="sm" />
          <span className="flex-1" />
          <span className="text-[10px] text-ink-faint">服务器 env 默认：{MODE_META[engineEnvDefault].label}</span>
        </div>
        <div className="grid gap-2 md:grid-cols-3">
          {(Object.keys(MODE_META) as EngineMode[]).map((m) => {
            const active = engineMode === m;
            return (
              <button
                key={m}
                onClick={() => void switchEngineMode(m)}
                disabled={engineSaving}
                title="点击切换，立即生效"
                className={`rounded-xl border p-3 text-left transition disabled:cursor-not-allowed ${
                  active
                    ? "border-sky-500/60 bg-sky-500/10"
                    : "border-line-soft bg-bg/30 hover:border-sky-500/40"
                }`}
              >
                <span className={`flex items-center gap-1.5 text-xs font-medium ${active ? "text-accent" : "text-ink"}`}>
                  {MODE_META[m].label}
                  {active && <span className="rounded bg-sky-500/20 px-1.5 py-0.5 text-[9px] text-accent">生效中</span>}
                  {engineSaving && <span className="text-[9px] text-ink-faint">切换中…</span>}
                </span>
                <span className="mt-1 block text-[10px] leading-relaxed text-ink-dim">{MODE_META[m].desc}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div className="lg:grid lg:grid-cols-[230px_1fr] lg:gap-5">
      {/* prompt 清单：移动横滑 / PC 左栏 */}
      <div className="scrollbar-none -mx-5 mb-3 flex gap-1.5 overflow-x-auto px-5 pb-1 lg:mx-0 lg:mb-0 lg:block lg:space-y-2.5 lg:overflow-visible lg:px-0">
        {categories.map((cat) => {
          const list = items.filter((x) => x.category === cat);
          if (!list.length) return null;
          return (
            <div key={cat} className="flex gap-1.5 lg:block lg:space-y-1">
              <p className="hidden px-1 text-[10px] font-medium uppercase tracking-wider text-ink-faint lg:block">{cat}</p>
              {list.map((it) => (
                <button
                  key={it.key}
                  onClick={() => pick(it)}
                  className={`flex shrink-0 items-center gap-1.5 whitespace-nowrap rounded-xl px-3 py-2 text-xs transition-all duration-200 lg:w-full ${
                    sel?.key === it.key
                      ? "bg-gradient-to-r from-sky-500 to-indigo-500 font-medium text-white shadow-md shadow-sky-500/25"
                      : "text-ink-mute hover:bg-wash hover:text-ink"
                  }`}
                >
                  {it.title}
                  {it.overridden && (
                    <span
                      title={it.enabled ? "DB 覆盖生效中" : "覆盖已停用（用代码默认）"}
                      className={`h-1.5 w-1.5 shrink-0 rounded-full ${it.enabled ? "bg-emerald-400" : "bg-amber-400"}`}
                    />
                  )}
                </button>
              ))}
            </div>
          );
        })}
      </div>

      {/* 三段式编辑器 */}
      {sel && (
        <div className="min-w-0">
          {/* 标题行 */}
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <h3 className="text-sm font-semibold text-ink">{sel.title}</h3>
            <TagChip label={sel.key} tone="slate" size="sm" />
            {sel.overridden ? (
              <TagChip icon="🟢" label="DB 覆盖" tone="emerald" size="sm" title={`更新于 ${zhTime(sel.updatedAt)}`} />
            ) : (
              <TagChip label="代码默认" tone="sky" size="sm" />
            )}
            {!sel.enabled && <TagChip icon="⏸" label="已停用·用默认" tone="amber" size="sm" />}
            <span className="flex-1" />
            {dirty && <TagChip label="未保存" tone="amber" size="sm" />}
            <button
              onClick={save}
              disabled={saving || !draft.trim()}
              className="btn-primary rounded-xl px-4 py-1.5 text-xs font-medium disabled:opacity-50"
            >
              {saving ? "保存中…" : "保存（立即生效）"}
            </button>
            {sel.overridden && (
              <button onClick={revertDefault} className="rounded-lg border border-line-soft bg-surface/60 px-3 py-1.5 text-xs text-ink-soft transition hover:border-rose-500/50 hover:text-danger">
                恢复代码默认
              </button>
            )}
          </div>

          {/* ===== 第一段：System prompt ===== */}
          <section className="glass mb-3 rounded-2xl p-4">
            <div className="mb-2 flex flex-wrap items-center gap-2">
              <FilterChip label="① System prompt" active variant="pill" onClick={() => {}} />
              <span className="flex-1" />
              <button
                onClick={() => setShowCompare((v) => !v)}
                className="rounded-lg border border-line-soft bg-surface/60 px-2.5 py-1 text-[11px] text-ink-soft transition hover:border-sky-500/50"
              >
                {showCompare ? "收起对比" : "对比默认值"}
              </button>
            </div>

            {/* AI 优化入口 */}
            <div className="mb-2 flex flex-wrap items-center gap-1.5">
              <input
                value={optHint}
                onChange={(e) => setOptHint(e.target.value)}
                placeholder="优化意图（可空，如：更严格约束日期）"
                maxLength={200}
                className="min-w-40 flex-1 rounded-lg border border-line-soft bg-surface/60 px-2.5 py-1.5 text-xs outline-none placeholder:text-ink-faint focus:border-violet-500"
              />
              <button
                onClick={optimize}
                disabled={optimizing}
                className="whitespace-nowrap rounded-lg border border-purple-500/40 bg-purple-500/10 px-3 py-1.5 text-xs font-medium text-ai transition hover:bg-purple-500/20 disabled:opacity-50"
              >
                {optimizing ? "优化中…" : "✨ AI 优化"}
              </button>
            </div>

            {/* AI 建议对比（并排） */}
            {suggestion !== null && (
              <div className="mb-3 rounded-xl border border-purple-500/30 bg-purple-500/[0.06] p-3">
                <p className="mb-2 flex items-center gap-2 text-xs font-medium text-ai">
                  <TagChip icon="✨" label="AI 优化建议" tone="violet" size="sm" />
                  <span className="font-normal text-ink-dim">采纳后仅填入编辑器，检查无误再手动保存</span>
                  <span className="flex-1" />
                  <button
                    onClick={() => {
                      setDraft(suggestion);
                      setDirty(true);
                      setSuggestion(null);
                      notify("已采纳到编辑器（未保存）");
                    }}
                    className="rounded-lg bg-violet-600 px-3 py-1 text-[11px] font-medium text-white hover:bg-violet-500"
                  >
                    采纳
                  </button>
                  <button onClick={() => setSuggestion(null)} className="rounded-lg px-2.5 py-1 text-[11px] text-ink-mute hover:bg-soft">
                    放弃
                  </button>
                </p>
                <div className="grid gap-2 md:grid-cols-2">
                  <div>
                    <p className="mb-1 text-[10px] text-ink-faint">当前（编辑器）</p>
                    <pre className="max-h-64 overflow-auto whitespace-pre-wrap rounded-lg bg-bg/60 p-2 text-[10px] leading-relaxed text-ink-soft">{draft}</pre>
                  </div>
                  <div>
                    <p className="mb-1 text-[10px] text-ink-faint">AI 建议</p>
                    <pre className="max-h-64 overflow-auto whitespace-pre-wrap rounded-lg bg-bg/60 p-2 text-[10px] leading-relaxed text-ink">{suggestion}</pre>
                  </div>
                </div>
              </div>
            )}

            {/* 编辑器 + 对比默认值 */}
            <div className={showCompare ? "grid gap-2 md:grid-cols-2" : ""}>
              <textarea
                value={draft}
                onChange={(e) => {
                  setDraft(e.target.value.slice(0, 50000));
                  setDirty(true);
                }}
                rows={12}
                spellCheck={false}
                className="input-glow w-full resize-y rounded-xl border border-line-soft bg-bg/40 p-3 font-mono text-[11px] leading-relaxed text-ink outline-none"
              />
              {showCompare && (
                <pre className="max-h-[320px] overflow-auto whitespace-pre-wrap rounded-xl border border-line-soft bg-bg/60 p-3 font-mono text-[11px] leading-relaxed text-ink-mute">
                  {sel.defaultContent}
                </pre>
              )}
            </div>
            <p className="mt-1.5 text-[10px] text-ink-faint">{draft.length}/50000 · 关闭下方「启用此覆盖」或点「恢复代码默认」= 整 key 回退代码默认</p>
          </section>

          {/* ===== 第二段：输入装配（3-A） ===== */}
          <section className="glass mb-3 rounded-2xl p-4">
            <div className="mb-2 flex flex-wrap items-center gap-2">
              <FilterChip label="② 输入装配（user）" active variant="pill" onClick={() => {}} />
              {tplDirty && <TagChip label="模板已覆盖" tone="emerald" size="sm" />}
              {cfgDirty && <TagChip label="配置已调整" tone="emerald" size="sm" />}
            </div>

            {/* user 模板编辑 */}
            <p className="mb-1 flex flex-wrap items-center gap-1.5 text-[11px] text-ink-dim">
              <span className="font-medium text-ink-soft">user 模板</span>
              <span>合法占位符：</span>
              {sel.registry.placeholders.map((p) => {
                const missing = tplMissing.includes(p);
                return (
                  <button
                    key={p}
                    onClick={() => {
                      if (!missing) return;
                      const fixed = tplDraft.replace(/\s*$/, "") + "\n" + sel.registry.placeholders.filter((x) => validateTpl(tplDraft, sel.registry.placeholders).missing.includes(x)).map((x) => `{${x}}`).join(" ");
                      setTplDraft(fixed);
                      notify("已补齐缺失占位符（追加在模板末尾，可自行调整位置）");
                    }}
                    className={`rounded px-1.5 py-0.5 font-mono text-[10px] transition ${
                      missing ? "bg-rose-500/15 text-danger hover:bg-rose-500/25" : "bg-sky-500/10 text-accent hover:bg-sky-500/20"
                    }`}
                    title={missing ? "缺失中——点击追加到模板末尾" : "已包含"}
                  >
                    {`{${p}}`}
                  </button>
                );
              })}
              {tplDraft !== sel.userTemplateDefault && (
                <button
                  onClick={() => {
                    setTplDraft(sel.userTemplateDefault);
                    notify("user 模板已还原为代码默认（保存后清除覆盖）");
                  }}
                  className="rounded px-1.5 py-0.5 text-[10px] text-ink-mute hover:bg-soft hover:text-accent"
                >
                  还原默认
                </button>
              )}
            </p>
            <textarea
              value={tplDraft}
              onChange={(e) => {
                setTplDraft(e.target.value.slice(0, 50000));
                setDirty(true);
              }}
              rows={5}
              spellCheck={false}
              className="w-full resize-y rounded-xl border border-line-soft bg-bg/40 p-3 font-mono text-[11px] leading-relaxed text-ink outline-none focus:border-sky-500/60"
            />
            {(tplMissing.length > 0 || tplUnknown.length > 0) && (
              <p className="mt-1 text-[11px] text-danger">
                占位符校验：{tplMissing.length ? `缺失 ${tplMissing.map((x) => `{${x}}`).join("、")}（点上方红色占位符一键补齐）` : ""}
                {tplUnknown.length ? ` 未知 ${tplUnknown.map((x) => `{${x}}`).join("、")}` : ""}
              </p>
            )}

            {/* 注入开关 */}
            <p className="mb-1 mt-3 text-[11px] font-medium text-ink-soft">注入项</p>
            <ul className="space-y-1">
              {sel.registry.injects.map((i) => {
                const on = injectDraft[i.key] ?? i.default;
                const locked = !!i.required;
                return (
                  <li key={i.key} className="flex items-start gap-2.5 rounded-lg border border-line-soft bg-bg/30 px-2.5 py-1.5">
                    <input
                      type="checkbox"
                      checked={locked ? true : on}
                      disabled={locked}
                      onChange={(e) => {
                        setInjectDraft((d) => ({ ...d, [i.key]: e.target.checked }));
                        setDirty(true);
                      }}
                      title={locked ? "必需注入项，不可关闭" : on ? "点击关闭（线上装配即不含该块）" : "点击开启"}
                      className="mt-0.5 h-3.5 w-3.5 accent-sky-500"
                    />
                    <span className="min-w-0 flex-1">
                      <span className={`text-xs font-medium ${locked ? "text-ink-dim" : on ? "text-ink" : "text-ink-faint"}`}>
                        {i.label}
                        {locked && <span className="ml-1.5 rounded bg-amber-500/15 px-1 py-0.5 text-[9px] text-warn">必需</span>}
                        {!on && !locked && <span className="ml-1.5 text-[9px] text-ink-faint">已关闭</span>}
                      </span>
                      <span className="block truncate text-[10px] text-ink-faint" title={i.desc}>{i.desc}</span>
                    </span>
                    <span className="shrink-0 text-[9px] text-ink-faint" title={i.source}>{i.source}</span>
                  </li>
                );
              })}
            </ul>

            {/* 参数 */}
            {sel.registry.caps.length > 0 && (
              <>
                <p className="mb-1 mt-3 text-[11px] font-medium text-ink-soft">参数（0 = 不设限；保存即在线上生效，明细类上限在 SQL 查询层生效）</p>
                <div className="flex flex-wrap gap-2">
                  {sel.registry.caps.map((c) => (
                    <label key={c.key} className="flex items-center gap-1.5 rounded-lg border border-line-soft bg-bg/30 px-2.5 py-1.5 text-[11px] text-ink-dim">
                      {c.label}
                      <input
                        type="number"
                        min={c.min}
                        max={c.max}
                        value={capsDraft[c.key] ?? c.default}
                        onChange={(e) => {
                          const v = e.target.value === "" ? "" : Math.max(c.min, Math.min(c.max, Math.round(Number(e.target.value))));
                          setCapsDraft((d) => ({ ...d, [c.key]: v as number }));
                          setDirty(true);
                        }}
                        className="w-16 rounded border border-line bg-surface px-1.5 py-0.5 text-right tabular-nums text-ink outline-none focus:border-sky-500"
                      />
                    </label>
                  ))}
                </div>
              </>
            )}

            {/* 装配预览 */}
            <p className="mb-1 mt-3 text-[11px] font-medium text-ink-soft">装配预览（不调 LLM、零 token；按上方当前配置与你的真实数据装配）</p>
            <div className="flex flex-wrap items-center gap-1.5">
              <input
                value={previewSample}
                onChange={(e) => setPreviewSample(e.target.value)}
                placeholder="样例话术（可空=取你最近一条真实数据）"
                maxLength={500}
                className="min-w-40 flex-1 rounded-lg border border-line-soft bg-surface/60 px-2.5 py-1.5 text-xs outline-none placeholder:text-ink-faint focus:border-sky-500"
              />
              {isReview && (
                <input
                  value={previewPeriod}
                  onChange={(e) => setPreviewPeriod(e.target.value)}
                  placeholder={periodPlaceholder}
                  maxLength={10}
                  className="w-44 rounded-lg border border-line-soft bg-surface/60 px-2.5 py-1.5 text-xs outline-none placeholder:text-ink-faint focus:border-sky-500"
                />
              )}
              <button
                onClick={runPreview}
                disabled={previewing}
                className="whitespace-nowrap rounded-lg border border-sky-500/40 bg-sky-500/10 px-3 py-1.5 text-xs font-medium text-accent transition hover:bg-sky-500/20 disabled:opacity-50"
              >
                {previewing ? "装配中…" : "🔍 装配预览"}
              </button>
            </div>
            {previewText !== null && (
              <pre className="mt-2 max-h-80 overflow-auto whitespace-pre-wrap rounded-xl border border-sky-500/30 bg-sky-500/[0.04] p-3 font-mono text-[10px] leading-relaxed text-ink">
                {previewText}
              </pre>
            )}
          </section>

          {/* ===== 第三段：版本历史 ===== */}
          <section className="glass mb-3 rounded-2xl p-4">
            <div className="mb-2 flex flex-wrap items-center gap-2">
              <FilterChip label="③ 版本历史" active variant="pill" onClick={() => {}} />
              <span className="flex-1" />
              <button
                onClick={() => setShowVersions((v) => !v)}
                className="rounded-lg border border-line-soft bg-surface/60 px-2.5 py-1 text-[11px] text-ink-soft transition hover:border-sky-500/50"
              >
                {showVersions ? "收起" : "展开"} {versions?.length ? `(${versions.length})` : ""}
              </button>
            </div>
            {showVersions && (
              <>
                {!versions ? (
                  <p className="text-[11px] text-ink-faint">加载中…</p>
                ) : versions.length === 0 ? (
                  <p className="text-[11px] text-ink-faint">还没有保存记录 —— 每次保存会自动留三件套快照</p>
                ) : (
                  <ul className="space-y-1">
                    {versions.map((v) => (
                      <li key={v.id} className="flex flex-wrap items-center gap-2 text-[11px] text-ink-mute">
                        <span className="tabular-nums">{zhTime(v.created_at)}</span>
                        <span className="tabular-nums">{v.size} 字</span>
                        {v.payload ? <TagChip label="三件套" tone="sky" size="sm" title="含 system + user 模板 + 注入配置" /> : <TagChip label="仅 system" tone="slate" size="sm" />}
                        {v.restored_from && <TagChip label="回滚" tone="amber" size="sm" title={`来自版本 #${v.restored_from}`} />}
                        <span className="truncate text-ink-faint">{v.created_by_name ?? "—"}</span>
                        <span className="flex-1" />
                        <button
                          onClick={() => {
                            setDraft(v.payload?.system ?? v.content);
                            setDirty(true);
                            notify("已载入该版本 system 到编辑器（未保存）");
                          }}
                          className="rounded px-2 py-0.5 text-ink-soft hover:bg-soft hover:text-accent"
                        >
                          载入 system
                        </button>
                        <button
                          onClick={() => void rollback(v)}
                          className="rounded px-2 py-0.5 text-ink-soft hover:bg-soft hover:text-warn"
                          title="整体恢复该版本的三件套并立即生效"
                        >
                          回滚
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </>
            )}
            <p className="mt-2 text-[10px] text-ink-faint">保存即生效（≤60s 缓存、主动失效）；启用开关关闭 = 整 key 回退代码默认</p>
            <label className="mt-1 flex cursor-pointer items-center gap-1.5 text-xs text-ink-mute" title="关闭后此 key 使用代码默认值">
              <input type="checkbox" checked={enabled} onChange={(e) => { setEnabled(e.target.checked); setDirty(true); }} className="h-3.5 w-3.5 accent-sky-500" />
              启用此覆盖
            </label>
          </section>
        </div>
      )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { parseYmd, todayStr, ymd } from "@/lib/date";
import BlockDraftForm, { type BlockDraftValue } from "@/components/block-draft-form";
import type { Activity, Block } from "@/lib/types";

const PX_PER_MIN = 0.75; // 一天 1080px，一小时 45px

interface Props {
  date: string; // YYYY-MM-DD
  blocks: Block[];
  activities: Activity[];
  onCreate: (payload: { title: string; startAt: string; endAt: string; activityId: string }) => Promise<boolean>;
  onEditBlock: (b: Block) => void;
  /** 数据是否仍在加载：加载结束后才做一次定位，避免定位到空数据 */
  loading?: boolean;
}

const pad = (n: number) => String(Math.floor(n)).padStart(2, "0");
function hmOf(minutes: number): string {
  return `${pad(Math.floor(minutes / 60))}:${pad(minutes % 60)}`;
}

export default function DayTimeline({ date, blocks, activities, onCreate, onEditBlock, loading = false }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const lastAutoDate = useRef<string | null>(null);
  const isToday = date === todayStr();
  const dayStart = useMemo(() => parseYmd(date), [date]);

  const [nowMin, setNowMin] = useState(() => {
    const n = new Date();
    return n.getHours() * 60 + n.getMinutes();
  });
  const [draft, setDraft] = useState<BlockDraftValue | null>(null);
  const [saving, setSaving] = useState(false);
  const formRef = useRef<HTMLDivElement>(null);

  // 表单打开时滚入视口：时间轴自动定位到当前时刻后，点击深处缺口时表单在区域顶部、视口之外，看起来像"没反应"
  useEffect(() => {
    if (draft) formRef.current?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [draft]);

  useEffect(() => {
    if (!isToday) return;
    const t = setInterval(() => {
      const n = new Date();
      setNowMin(n.getHours() * 60 + n.getMinutes());
    }, 60_000);
    return () => clearInterval(t);
  }, [isToday]);

  // 每个日期只在数据到位后自动定位一次：今天→当前时刻；其他日期→第一块日程（无块回顶部）
  useEffect(() => {
    const el = containerRef.current;
    if (!el || loading || lastAutoDate.current === date) return;
    lastAutoDate.current = date;
    if (isToday) {
      el.scrollTop = Math.max(0, nowMin * PX_PER_MIN - 160);
      return;
    }
    const starts = blocks.map((b) => minOfDay(b.start_at));
    el.scrollTop = starts.length ? Math.max(0, Math.min(...starts) * PX_PER_MIN - 160) : 0;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [date, loading, isToday, blocks]);

  /** ISO → 当天分钟数（跨天块钳到 0~1440） */
  const minOfDay = (iso: string) => {
    const m = Math.floor((new Date(iso).getTime() - dayStart.getTime()) / 60_000);
    return Math.max(0, Math.min(1440, m));
  };
  const isoFromMinutes = (minutes: number) =>
    new Date(dayStart.getTime() + minutes * 60_000).toISOString();

  // 合并已记录区间 → 未记录缺口（>2 分钟）
  const gaps = useMemo(() => {
    const sorted = blocks
      .map((b) => ({ s: minOfDay(b.start_at), e: minOfDay(b.end_at) }))
      .sort((a, b) => a.s - b.s);
    const merged: { s: number; e: number }[] = [];
    for (const seg of sorted) {
      const last = merged[merged.length - 1];
      if (last && seg.s <= last.e) last.e = Math.max(last.e, seg.e);
      else merged.push({ ...seg });
    }
    const out: { s: number; e: number }[] = [];
    let cursor = 0;
    for (const seg of merged) {
      if (seg.s - cursor > 2) out.push({ s: cursor, e: Math.min(seg.s, 1440) });
      cursor = Math.max(cursor, seg.e);
    }
    if (1440 - cursor > 2) out.push({ s: cursor, e: 1440 });
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [blocks, date]);

  /** 在绝对分钟处打开补录：定位到该时刻所在的 1 小时整点区间（钳进缺口；贴边不足 5 分钟回退缺口末段一小时） */
  function openSlotAt(absMin: number) {
    const gap = gaps.find((g) => absMin >= g.s && absMin <= g.e);
    if (!gap) return;
    const hourStart = Math.floor(absMin / 60) * 60;
    let s = Math.max(gap.s, hourStart);
    let e = Math.min(gap.e, hourStart + 60);
    if (e - s < 5) {
      s = Math.max(gap.s, gap.e - 60);
      e = gap.e;
    }
    setDraft({ title: "", start: hmOf(s), end: hmOf(e), activityId: "other" });
  }

  /** 点击时间轴空白（左右留白条等缺口按钮未覆盖处）→ 同样定位整点区间 */
  function containerClick(e: React.MouseEvent<HTMLDivElement>) {
    if (draft || e.target !== e.currentTarget) return; // 只响应裸背景，缺口/日程块有自己的处理
    const rect = e.currentTarget.getBoundingClientRect();
    openSlotAt(Math.max(0, Math.min(1439, (e.clientY - rect.top) / PX_PER_MIN)));
  }

  async function submitCreate() {
    if (!draft || !draft.title.trim() || saving) return;
    const [sh, sm] = draft.start.split(":").map(Number);
    const [eh, em] = draft.end.split(":").map(Number);
    const ok = await onCreate({
      title: draft.title.trim(),
      startAt: isoFromMinutes(sh * 60 + sm),
      endAt: isoFromMinutes(eh * 60 + em),
      activityId: draft.activityId,
    });
    if (ok) setDraft(null);
  }

  return (
    <div>
      <div ref={formRef}>
        {draft && (
          <BlockDraftForm
            value={draft}
            activities={activities}
            busy={saving}
            onChange={setDraft}
            onCancel={() => setDraft(null)}
            onSubmit={submitCreate}
          />
        )}
      </div>

      <div ref={containerRef} className="relative max-h-[480px] overflow-y-auto rounded-lg border border-line-soft bg-bg/40">
        <div className="relative" style={{ height: `${1440 * PX_PER_MIN}px` }} onClick={containerClick}>
          {Array.from({ length: 25 }, (_, h) => (
            <div key={h} className="absolute inset-x-0 border-t border-line-soft/70" style={{ top: `${h * 60 * PX_PER_MIN}px` }}>
              <span
                className={`absolute -top-2 left-1.5 text-[10px] tabular-nums ${h % 3 === 0 ? "text-ink-mute" : "text-ink-faint"}`}
              >
                {h % 3 === 0 ? `${h}点` : ""}
              </span>
            </div>
          ))}

          {gaps.map((g, i) => (
            <button
              key={`gap-${i}`}
              onClick={(e) => {
                e.stopPropagation(); // 不冒泡到容器，避免二次计算覆盖
                const rect = e.currentTarget.getBoundingClientRect();
                openSlotAt(g.s + (e.clientY - rect.top) / PX_PER_MIN);
              }}
              title="点击空白处，按整点定位 1 小时补录"
              className="group absolute right-2 w-[calc(100%-3rem)] rounded border border-dashed border-line/60 text-left transition hover:border-amber-500/60 hover:bg-amber-500/5"
              style={{ top: `${g.s * PX_PER_MIN}px`, height: `${Math.max((g.e - g.s) * PX_PER_MIN - 2, 8)}px` }}
            >
              {(g.e - g.s) * PX_PER_MIN >= 22 && (
                <span className="pointer-events-none absolute inset-0 flex items-center justify-center gap-1 text-[10px] text-ink-faint group-hover:text-warn/80">
                  ✦ 未记录 {hmOf(g.s)}–{hmOf(g.e)}（{(g.e - g.s) >= 60 ? `${Math.floor((g.e - g.s) / 60)}小时${(g.e - g.s) % 60 || ""}` : `${g.e - g.s}分钟`}）
                </span>
              )}
            </button>
          ))}

          {blocks.map((b) => {
            const s = minOfDay(b.start_at);
            const e = Math.max(minOfDay(b.end_at), s + 2);
            const h = (e - s) * PX_PER_MIN;
            return (
              <button
                key={b.id}
                onClick={() => onEditBlock(b)}
                title="点击修改/删除"
                className="absolute left-10 right-2 overflow-hidden rounded border-l-4 px-2 text-left transition hover:brightness-125"
                style={{
                  top: `${s * PX_PER_MIN}px`,
                  height: `${h - 2}px`,
                  backgroundColor: `${b.color}40`,
                  borderColor: b.color,
                }}
              >
                {h >= 18 && (
                  <span className="pointer-events-none flex h-full items-center gap-1.5 truncate text-xs">
                    <span>{b.icon}</span>
                    <span className="truncate font-medium text-ink">{b.title}</span>
                    <span className="shrink-0 tabular-nums text-[10px] text-ink-mute">
                      {hmOf(s)}–{hmOf(e)}
                    </span>
                  </span>
                )}
                {h < 18 && h >= 9 && (
                  <span className="pointer-events-none flex h-full items-center text-[10px] text-ink-soft">{b.icon}</span>
                )}
              </button>
            );
          })}

          {isToday && (
            <div className="pointer-events-none absolute inset-x-0 z-10" style={{ top: `${nowMin * PX_PER_MIN}px` }}>
              <div className="relative border-t-2 border-rose-500/80">
                <span className="absolute -top-2.5 right-1 rounded bg-rose-500 px-1 text-[9px] font-bold tabular-nums text-white">
                  {hmOf(nowMin)}
                </span>
              </div>
            </div>
          )}
        </div>
      </div>
      <p className="mt-2 text-[10px] text-ink-faint">
        提示：点击彩色块可修改 · 点击空白处自动定位整点 1 小时补录（表单内可调时间）{isToday ? " · 红线为当前时刻" : ""}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useDismiss } from "./dismissable";

/**
 * N4 空间名称就地编辑（REQ-002 FR-N4）：展示态 ⇄ 编辑态。
 * Enter 保存（onSave 成功后回调刷新）、点空白/Esc 取消（N3 语义，内部 useDismiss）。
 */
export default function InlineRename({
  value,
  onSave,
  className = "",
  maxLength = 40,
}: {
  value: string;
  onSave: (name: string) => Promise<boolean>; // 返回 true=保存成功（退出编辑态）
  className?: string;
  maxLength?: number;
}) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(value);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => setName(value), [value]);

  const cancel = () => {
    setName(value);
    setErr(null);
    setEditing(false);
  };

  const ref = useDismiss<HTMLSpanElement>(cancel, editing);

  async function save() {
    const t = name.trim();
    if (!t) {
      setErr("名称不能为空");
      return;
    }
    if ([...t].length > maxLength) {
      setErr(`名称过长（≤${maxLength} 字）`);
      return;
    }
    setBusy(true);
    const ok = await onSave(t);
    setBusy(false);
    if (ok) setEditing(false);
  }

  if (!editing) {
    return (
      <span className={`group/rename inline-flex min-w-0 items-center gap-1 ${className}`}>
        <span className="min-w-0 truncate">{value}</span>
        <button
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            setEditing(true);
            setTimeout(() => inputRef.current?.focus(), 50);
          }}
          title="重命名"
          className="row-actions-hidden hidden shrink-0 rounded px-1 text-[11px] text-ink-mute transition hover:text-accent group-hover/rename:block"
        >
          ✏️
        </button>
      </span>
    );
  }

  return (
    <span
      ref={ref}
      onClick={(e) => e.stopPropagation()}
      className={`inline-flex min-w-0 items-center gap-1 ${className}`}
    >
      <input
        ref={inputRef}
        value={name}
        onChange={(e) => setName(e.target.value.slice(0, maxLength))}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.nativeEvent.isComposing) void save();
        }}
        maxLength={maxLength}
        className="input-glow min-w-0 rounded-lg border border-line-strong bg-surface px-2 py-1 text-sm outline-none focus:border-sky-500"
      />
      {err && <span className="text-[10px] text-danger">{err}</span>}
    </span>
  );
}

"use client";

import type { Activity, DayStat } from "@/lib/types";
import { todayStr, zhDuration, zhDate } from "@/lib/date";

interface Props {
  month: string; // YYYY-MM-01
  stats: Map<string, DayStat>;
  activities: Activity[];
  onPickDay: (date: string) => void;
}

/** 月视图：月历格 + 每日迷你结构环 + 月度统计 */
export default function MonthView({ month, stats, activities, onPickDay }: Props) {
  const [y, m] = month.split("-").map(Number);
  const first = new Date(y, m - 1, 1);
  const daysInMonth = new Date(y, m, 0).getDate();
  const lead = (first.getDay() + 6) % 7; // 周一为 0
  const actMap = new Map(activities.map((a) => [a.id, a]));

  const cells: (string | null)[] = [
    ...Array.from({ length: lead }, () => null),
    ...Array.from({ length: daysInMonth }, (_, i) => `${month.slice(0, 8)}${String(i + 1).padStart(2, "0")}`),
  ];

  // 月度各类合计
  const totals: Record<string, number> = {};
  let grand = 0;
  let recordedDays = 0;
  for (const s of stats.values()) {
    recordedDays++;
    grand += s.totalMin;
    for (const [id, min] of Object.entries(s.byActivity)) totals[id] = (totals[id] ?? 0) + min;
  }
  const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
  const today = todayStr();

  return (
    <div>
      <div className="grid grid-cols-7 gap-1">
        {["一", "二", "三", "四", "五", "六", "日"].map((w) => (
          <div key={w} className="pb-1 text-center text-[11px] text-ink-dim">
            {w}
          </div>
        ))}
        {cells.map((date, i) => {
          if (!date) return <div key={`e-${i}`} />;
          const s = stats.get(date);
          const isToday = date === today;
          const isFuture = date > today;
          const donut = s && s.totalMin > 0;
          return (
            <button
              key={date}
              onClick={() => onPickDay(date)}
              className={`flex h-[74px] flex-col items-center justify-center gap-1 rounded-lg border text-center transition ${
                isToday ? "border-sky-500 bg-sky-500/10" : "border-line-soft bg-bg/40 hover:border-line-strong"
              }`}
            >
              <span className={`text-xs tabular-nums ${isToday ? "font-bold text-accent" : "text-ink-mute"}`}>
                {Number(date.slice(8))}
              </span>
              {donut ? (
                <>
                  <MiniDonut byActivity={s!.byActivity} actMap={actMap} size={30} />
                  <span className="block truncate text-[9px] tabular-nums text-ink-dim">
                    {zhDuration(s!.totalMin)}
                  </span>
                </>
              ) : (
                /* 未来日期没有"未记录"义务，仅过去/今天温和提示 */
                !isFuture && <span className="text-[9px] text-ink-faint">未记录</span>
              )}
            </button>
          );
        })}
      </div>

      {/* 月度统计 */}
      {grand > 0 && (
        <div className="mt-4 rounded-lg border border-line-soft bg-bg/40 p-4">
          <p className="mb-2 text-xs text-ink-mute">
            {m} 月共记录 <span className="font-semibold text-ink">{zhDuration(grand)}</span>
            <span className="ml-2 text-ink-dim">· {recordedDays} 天有记录 · 日均 {zhDuration(Math.round(grand / recordedDays))}</span>
          </p>
          <div className="flex h-3 w-full overflow-hidden rounded-full">
            {sorted.map(([id, min]) => (
              <div key={id} style={{ width: `${(min / grand) * 100}%`, backgroundColor: actMap.get(id)?.color ?? "#64748b" }} />
            ))}
          </div>
          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
            {sorted.map(([id, min]) => {
              const a = actMap.get(id);
              return (
                <span key={id} className="flex items-center gap-1.5 text-[11px] text-ink-mute">
                  <span className="h-2 w-2 rounded-full" style={{ backgroundColor: a?.color }} />
                  {a?.icon} {a?.name}
                  <span className="tabular-nums text-ink-dim">{zhDuration(min)} · {Math.round((min / grand) * 100)}%</span>
                </span>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function MiniDonut({ byActivity, actMap, size }: { byActivity: Record<string, number>; actMap: Map<string, Activity>; size: number }) {
  const total = Object.values(byActivity).reduce((s, v) => s + v, 0);
  const r = size / 2 - 3;
  const c = 2 * Math.PI * r;
  let offset = 0;
  return (
    <svg width={size} height={size} className="-rotate-90">
      {Object.entries(byActivity)
        .sort((a, b) => b[1] - a[1])
        .map(([id, min]) => {
          const frac = min / total;
          const el = (
            <circle
              key={id}
              cx={size / 2}
              cy={size / 2}
              r={r}
              fill="none"
              stroke={actMap.get(id)?.color ?? "#64748b"}
              strokeWidth={5}
              strokeDasharray={`${frac * c} ${c - frac * c}`}
              strokeDashoffset={-offset}
            />
          );
          offset += frac * c;
          return el;
        })}
    </svg>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { uploadImages } from "@/lib/image";
import { useDismiss } from "./dismissable";

/**
 * 移动端发布输入面板（底部抽屉）：悬浮圆圈点按=空面板；长按语音松开=转写文字带入预览，
 * 用户确认/修改后点「发布」才真正提交。
 * 附带图片（REQ-001 R1）：相册多选 ≤9 张 + 触屏设备「拍照」入口；文字秒发后并行上传，失败可重试。
 */
interface SheetImage {
  file: File;
  url: string;
  status: "ready" | "uploading" | "error";
}

export default function PublishSheet({
  open,
  initialText,
  busy,
  onPublish,
  onClose,
  notify,
}: {
  open: boolean;
  /** 打开时带入的初始文字（语音转写结果或空串） */
  initialText: string;
  busy: boolean;
  /** 发布文字动态；返回 entry id（供图片上传），失败/无图返回 null */
  onPublish: (text: string) => Promise<string | null>;
  onClose: () => void;
  /** N3.5 取消且内容有改动时的轻提示（可选） */
  notify?: (m: { ok: boolean; text: string } | null) => void;
}) {
  const [value, setValue] = useState("");
  const [images, setImages] = useState<SheetImage[]>([]);
  const [sheetMsg, setSheetMsg] = useState<string | null>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const galleryRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  // 打开时的初始文字快照（取消时判断是否"有改动"）
  const initialRef = useRef("");
  // N3：点面板外空白 / Esc → 取消关闭（面板渲染期间生效）
  const panelRef = useDismiss<HTMLDivElement>(cancel, open);
  // 触屏设备提供「拍照」入口（桌面无摄像头场景隐藏）
  const [canCapture, setCanCapture] = useState(false);
  useEffect(() => setCanCapture(window.matchMedia("(pointer: coarse)").matches), []);
  // 最近发布的动态 id（重试用）
  const lastEntryId = useRef<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setValue(initialText);
    initialRef.current = initialText;
    setImages([]);
    setSheetMsg(null);
    // 等挂载/键盘弹起后再聚焦，保证光标落在面板输入框
    const t = setTimeout(() => inputRef.current?.focus(), 80);
    return () => clearTimeout(t);
  }, [open, initialText]);

  if (!open) return null;

  /** N3 取消：点空白/Esc/×——内容相对打开时有改动则轻提示"已取消，未保存" */
  function cancel() {
    if (value.trim() && value.trim() !== initialRef.current.trim()) {
      notify?.({ ok: true, text: "已取消，未保存" });
    }
    onClose();
  }

  function addImages(files: File[], source: "gallery" | "camera") {
    const imgs = files
      .filter((f) => /^image\/(jpeg|png|webp|gif)$/.test(f.type))
      .slice(0, 9 - images.length)
      .map((file) => ({ file, url: URL.createObjectURL(file), status: "ready" as const }));
    if (!imgs.length) setSheetMsg("仅支持 jpg/png/webp/gif 图片");
    else if (imgs.length < files.length) setSheetMsg("最多添加 9 张，多余图片已忽略");
    setImages((prev) => [...prev, ...imgs]);
    void source;
  }

  async function publish() {
    const t = value.trim();
    if (!t || busy) return;
    const files = images.filter((i) => i.status !== "error").map((i) => i.file);
    const entryId = await onPublish(t);
    if (!entryId) {
      onClose(); // 文字发布失败：关面板，错误提示在主页横幅
      return;
    }
    lastEntryId.current = entryId;
    if (!files.length) {
      onClose(); // 无图：直接收尾
      return;
    }
    setImages((prev) => prev.map((i) => ({ ...i, status: "uploading" as const })));
    const { failed } = await uploadImages(entryId, files);
    if (failed.length) {
      const failedSet = new Set(failed);
      setImages((prev) => prev.filter((i) => failedSet.has(i.file)).map((i) => ({ ...i, status: "error" as const })));
      setSheetMsg("动态已发布；部分图片上传失败，可「↻ 重试」或关闭面板");
      return;
    }
    images.forEach((i) => URL.revokeObjectURL(i.url));
    onClose();
  }

  async function retryUpload() {
    if (!lastEntryId.current) return;
    const retryFiles = images.filter((i) => i.status === "error").map((i) => i.file);
    if (!retryFiles.length) return;
    setImages((prev) => prev.map((i) => (i.status === "error" ? { ...i, status: "uploading" as const } : i)));
    const { failed } = await uploadImages(lastEntryId.current, retryFiles);
    if (failed.length) {
      const failedSet = new Set(failed);
      setImages((prev) => prev.filter((i) => failedSet.has(i.file)).map((i) => ({ ...i, status: "error" as const })));
      setSheetMsg(`仍有 ${failed.length} 张上传失败，请稍后再试`);
      return;
    }
    setSheetMsg(null);
    onClose();
  }

  return (
    <>
      {/* 遮罩仅视觉；点空白关闭由面板 useDismiss 统一处理（N3） */}
      <div className="fixed inset-0 z-[55] bg-black/50" />
      <div ref={panelRef} className="safe-bottom fixed inset-x-0 bottom-0 z-[56] rounded-t-2xl border-t border-line-soft bg-surface p-4 pb-5 shadow-2xl">
        <div className="mb-2 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-ink-soft">记录此刻</h3>
          <button
            type="button"
            onClick={cancel}
            aria-label="关闭"
            className="rounded-full p-1 text-ink-dim hover:bg-white/5 hover:text-ink"
          >
            ✕
          </button>
        </div>
        <textarea
          ref={inputRef}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
              e.preventDefault();
              void publish();
            }
            // Esc 取消由 Dismissable 统一处理（N3）
          }}
          rows={3}
          maxLength={2000}
          placeholder='说点什么…（试试"刚跑完步40分钟，心情不错"、"明天下午三点看牙"）'
          className="input-glow w-full resize-none rounded-xl border border-line-soft bg-surface/60 px-4 py-3 text-sm outline-none placeholder:text-ink-faint"
        />
        {/* 接近上限才显示字数，平时不干扰 */}
        {value.length >= 1800 && (
          <p className={`mt-1 text-right text-[11px] tabular-nums ${value.length >= 1950 ? "text-danger" : "text-ink-faint"}`}>
            {value.length}/2000
          </p>
        )}

        {/* 已选图片缩略条（上传失败显示重试） */}
        {images.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-2">
            {images.map((img, i) => (
              <span key={img.url} className={`relative overflow-hidden rounded-lg border ${img.status === "error" ? "border-rose-500/60" : "border-line-soft"}`}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={img.url} alt="" className="h-14 w-14 object-cover" />
                {img.status === "error" ? (
                  <button
                    type="button"
                    onClick={() => void retryUpload()}
                    className="absolute inset-0 flex items-center justify-center bg-black/50 text-xs text-white"
                  >
                    ↻ 重试
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={() =>
                      setImages((prev) => {
                        URL.revokeObjectURL(prev[i]?.url ?? "");
                        return prev.filter((_, idx) => idx !== i);
                      })
                    }
                    className="absolute right-0.5 top-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-black/60 text-[9px] text-white"
                    aria-label="移除"
                  >
                    ✕
                  </button>
                )}
                {img.status === "uploading" && (
                  <span className="absolute inset-x-0 bottom-0 bg-black/50 text-center text-[9px] text-white">上传中…</span>
                )}
              </span>
            ))}
          </div>
        )}
        {sheetMsg && <p className="mt-1.5 text-[11px] text-warn">{sheetMsg}</p>}

        <div className="mt-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <label
              title="从相册选择（最多 9 张）"
              className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-xl border border-line-soft bg-surface/60 text-base transition active:border-sky-500/60"
            >
              🖼
              <input
                ref={galleryRef}
                type="file"
                accept="image/jpeg,image/png,image/webp,image/gif"
                multiple
                className="hidden"
                onChange={(e) => {
                  addImages(Array.from(e.target.files ?? []), "gallery");
                  e.target.value = "";
                }}
              />
            </label>
            {canCapture && (
              <label
                title="拍照"
                className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-xl border border-line-soft bg-surface/60 text-base transition active:border-sky-500/60"
              >
                📷
                <input
                  ref={cameraRef}
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  capture="environment"
                  className="hidden"
                  onChange={(e) => {
                    addImages(Array.from(e.target.files ?? []), "camera");
                    e.target.value = "";
                  }}
                />
              </label>
            )}
            <span className="text-[11px] text-ink-faint">发布后 AI 自动识别</span>
          </div>
          <button
            type="button"
            onClick={() => void publish()}
            disabled={busy || !value.trim()}
            className="btn-primary rounded-xl px-7 py-2 text-sm font-medium"
          >
            {busy ? "识别中…" : "发布"}
          </button>
        </div>
      </div>
    </>
  );
}

/**
 * Jev PoC 对照评测（REQ-003 3-B / FR-B1 前置门）
 *   npm run poc:jev          Jev 问题组 vs GLM 基线（基线缓存 testset/poc-glm-baseline.json）
 *   npm run poc:jev:live     强制重跑 GLM 基线（消耗 GLM token，46 次调用）
 *
 * 评分口径（两引擎完全一致，仅闭集字段；开放词汇如人名/标题不参评——Jev 硬限制不能生成）：
 *   schedule/todo/finance/mood/diet/people 六域适用性（noul）
 *   activity（choice，仅日程适用句）/ record_type / period（期望为 now 的句跳过）
 *   fin_direction / fin_category（仅财务适用句）/ diet_meal（仅饮食适用句）
 * 达标线（01 §8 FR-B1）：闭集整体准确率 ≥ GLM × 95%，且 activity 单独 ≥ 80%。
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { parseInput } from "./parse";
import { hasApiKey } from "./glm";
import { jevAsk, qChoice, qNoul, type JevQuestions } from "./jev";

const here = dirname(fileURLToPath(import.meta.url));
const set = JSON.parse(readFileSync(join(here, "../testset/poc-20.json"), "utf8"));
const BASELINE_FILE = join(here, "../testset/poc-glm-baseline.json");
const glmLive = process.argv.includes("--glm-live");

// 固定"当前时间"保证可复现（与 run-poc.ts 一致）
const NOW = new Date("2026-09-17T15:00:00+08:00");
const NOW_LABEL = "2026-09-17 15:00（周四，北京时间）";

interface Case {
  id: number; text: string; activity: string; durationMin?: number; period?: string;
  finance?: { amountCents: number; direction: string; category?: string } | null;
  people?: string[]; future?: boolean; diet?: boolean; dietMeal?: string;
  noSchedule?: boolean; mood?: string; startDay?: string;
}

/** Jev 问题组（02 §7.2）：一次调用并行评估全部闭集问题 */
function questionsFor(text: string): JevQuestions {
  return {
    sched_applicable: qNoul("这句话记录了一个已经发生或正在进行的、有具体内容的事件或活动（不是纯感想，不是未来计划，也不只是吃喝）"),
    todo_applicable: qNoul("这句话表达了一个计划要做、还没发生的事情"),
    fin_applicable: qNoul("这句话包含有具体金额的花钱或收钱行为"),
    mood_applicable: qNoul("这句话表达了说话者的情绪或心情（情绪可能藏在动作里）"),
    diet_applicable: qNoul("这句话提到吃了或喝了具体的食物或饮品（喝白开水不算）"),
    people_applicable: qNoul("这句话提到了具体的人（称谓也算，比如爸妈、小李、张老师）"),
    activity: qChoice("如果这句话在记录一个活动，它最接近哪一类？", {
      sleep: "睡眠：睡觉、午睡、赖床补觉",
      work: "工作：开会、写周报、处理邮件、见客户、上班",
      study: "学习：看书、学英语、上课、刷题",
      fitness: "健身：跑步、撸铁、球类、瑜伽、散步锻炼",
      social: "社交：与亲友同事吃饭聊天通话、随礼帮忙",
      fun: "娱乐：刷抖音、看电影、玩游戏、逛街",
      chores: "家务：做饭、打扫、买菜、洗衣",
      commute: "通勤：上下班路上、打车地铁",
      other: "以上皆非",
    }),
    record_type: qChoice("这句话描述的是已经发生的事，还是计划要做的事？", {
      past: "已经发生或正在发生的事",
      future: "计划/将要发生的事",
    }),
    period: qChoice("这件事大致发生在什么时段？", {
      now: "当下、刚刚",
      morning: "早晨/上午",
      noon: "中午",
      afternoon: "下午",
      evening: "傍晚/晚上",
      night: "夜里",
      lateNight: "凌晨",
    }),
    fin_direction: qChoice("如果这句话涉及钱，是花钱还是收钱？", { out: "花钱/支出", income: "收钱/收入" }),
    fin_category: qChoice("如果这句话涉及钱，最接近哪个分类？", {
      餐饮: "吃饭、饮品、外卖",
      交通: "打车、地铁、公交、加油",
      人情往来: "随礼、份子钱、送礼",
      学习: "课程、书籍、培训",
      购物: "购买商品",
      娱乐: "娱乐消费",
      其他: "其他支出",
    }),
    diet_meal: qChoice("如果吃了或喝了东西，最接近哪一餐？", {
      早餐: "早餐", 午餐: "午餐", 晚餐: "晚餐", 加餐: "下午茶、零食", 夜宵: "深夜进食", 未知: "说不清",
    }),
  };
}

// ---------- 期望值推导（两引擎同一把尺） ----------
// 日程适用：纯感想/未来计划不算事件；吃喝事件带时间也算事件（实测 GLM 对饮食句同样判适用——
// 与产品落库行为一致，因此饮食句期望为 true，只有 noSchedule/future 才为 false）
const expectSched = (c: Case) => !(c.noSchedule || c.future);
// GLM 侧 period 从时间块开始钟点推导（time.start 为本地时刻串，getHours 即北京钟点，勿重复加 8h）
const hourBucket = (iso: string): string => {
  const h = new Date(iso).getHours();
  if (h <= 5) return "lateNight";
  if (h <= 9) return "morning";
  if (h <= 12) return "noon";
  if (h <= 16) return "afternoon";
  if (h <= 20) return "evening";
  return "night";
};

type Field = string;
const jevScore: Record<Field, { n: number; ok: number }> = {};
const glmScore: Record<Field, { n: number; ok: number }> = {};
const bump = (table: Record<Field, { n: number; ok: number }>, f: Field, okv: boolean) => {
  table[f] ??= { n: 0, ok: 0 };
  table[f].n++;
  if (okv) table[f].ok++;
};
const divergences: string[] = [];

function grade(
  c: Case,
  engine: "jev" | "glm",
  a: {
    sched: boolean; todo: boolean; fin: boolean; mood: boolean; diet: boolean; people: boolean;
    activity: string | null; recordType: "past" | "future"; period: string | null;
    finDirection: string | null; finCategory: string | null; dietMeal: string | null;
  },
) {
  const bumpT = (f: Field, okv: boolean) => bump(engine === "jev" ? jevScore : glmScore, f, okv);
  const note = (f: Field, got: unknown, want: unknown) => {
    if (engine === "jev") {
      divergences.push(`| ${c.id} | ${c.text.slice(0, 22)} | ${f} | ${JSON.stringify(got)} | ${JSON.stringify(want)} |`);
    }
  };
  const g = (f: Field, got: unknown, want: unknown) => {
    const okv = got === want;
    bumpT(f, okv);
    if (!okv) note(f, got, want);
    return okv;
  };

  g("schedule适用", a.sched, expectSched(c));
  g("todo适用", a.todo, !!c.future);
  g("财务适用", a.fin, c.finance != null);
  g("心情适用", a.mood, c.mood !== undefined);
  if (c.diet !== undefined) g("饮食适用", a.diet, c.diet);
  g("人物适用", a.people, (c.people ?? []).length > 0);
  if (expectSched(c)) {
    g("activity", a.activity, c.activity);
    if (c.period !== undefined && c.period !== "now") g("period", a.period, c.period);
  }
  if (c.finance) {
    g("fin_direction", a.finDirection, c.finance.direction);
    if (c.finance.category) g("fin_category", a.finCategory, c.finance.category);
  }
  if (c.dietMeal) g("diet_meal", a.dietMeal, c.dietMeal);
  g("record_type", a.recordType, c.future ? "future" : "past");
}

// ---------- 主流程 ----------
async function main() {
  const cases = set.cases as Case[];

  // ---- GLM 基线（缓存复用，--glm-live 强制重跑）----
  let glm: Record<number, any> = {};
  // 同场景耗时对照：Jev 单次并行答 13 题闭集 vs GLM 单次五域全量抽取
  const jevMs: Record<number, number> = {};
  let glmMs: Record<number, number> = {};
  if (!glmLive && existsSync(BASELINE_FILE)) {
    glm = JSON.parse(readFileSync(BASELINE_FILE, "utf8"));
    glmMs = Object.fromEntries(Object.entries(glm).map(([k, v]: [string, any]) => [k, v.ms ?? 0]));
    console.log(`GLM 基线：复用缓存（${Object.keys(glm).length} 句）\n`);
  } else {
    if (!hasApiKey()) {
      console.error("GLM 基线需要 ZHIPUAI_API_KEY（--glm-live）");
      process.exit(1);
    }
    console.log("GLM 基线：live 重跑（46 次调用）…");
    for (const c of cases) {
      try {
        const t0 = Date.now();
        const r = await parseInput(c.text, { now: NOW });
        glmMs[c.id] = Date.now() - t0;
        glm[c.id] = {
          sched: r.scheduleApplicable && r.intent === "schedule",
          todo: r.intent === "todo",
          fin: r.finance.hasAmount,
          mood: !!r.mood.label,
          diet: r.diet.applicable,
          people: r.people.length > 0,
          activity: r.activity,
          recordType: r.intent === "todo" ? "future" : "past",
          period: r.time?.start ? hourBucket(r.time.start) : null,
          finDirection: r.finance.direction ?? null,
          finCategory: r.finance.category ?? null,
          dietMeal: r.diet.meal ?? null,
          ms: glmMs[c.id],
        };
      } catch (e) {
        console.warn(`  GLM #${c.id} 失败：${String(e).slice(0, 80)}`);
      }
    }
    writeFileSync(BASELINE_FILE, JSON.stringify(glm, null, 1));
    console.log(`GLM 基线完成（${Object.keys(glm).length} 句），已缓存到 testset/poc-glm-baseline.json\n`);
  }

  // ---- Jev 问题组逐句调用 ----
  console.log("Jev：46 句 × 1 次并行调用 …");
  const jevRaw: Record<number, any> = {};
  for (const c of cases) {
    const state = `用户随口记录了一句话（当前时间：${NOW_LABEL}）：\n「${c.text}」`;
    try {
      const t0 = Date.now();
      const res = await jevAsk(state, questionsFor(c.text));
      jevMs[c.id] = Date.now() - t0;
      jevRaw[c.id] = { answers: res.answers, model: res.model };
      process.stdout.write(`  #${c.id} ✓\n`);
    } catch (e) {
      process.stdout.write(`  #${c.id} ✗ ${String(e).slice(0, 100)}\n`);
    }
  }
  const jevOkCount = Object.keys(jevRaw).length;
  console.log(`Jev 完成：${jevOkCount}/${cases.length}\n`);

  // ---- 统一评分 ----
  for (const c of cases) {
    const g = glm[c.id];
    if (g) grade(c, "glm", g);
    const j = jevRaw[c.id];
    if (!j) continue;
    const A = (k: string) => j.answers[k]?.value ?? null;
    grade(c, "jev", {
      sched: A("sched_applicable") === true,
      todo: A("todo_applicable") === true,
      fin: A("fin_applicable") === true,
      mood: A("mood_applicable") === true,
      diet: A("diet_applicable") === true,
      people: A("people_applicable") === true,
      activity: typeof A("activity") === "string" ? (A("activity") as string) : null,
      recordType: A("record_type") === "future" ? "future" : A("record_type") === "past" ? "past" : (null as never),
      period: typeof A("period") === "string" ? (A("period") as string) : null,
      finDirection: A("fin_direction") === "income" ? "in" : A("fin_direction"),
      finCategory: typeof A("fin_category") === "string" ? (A("fin_category") as string) : null,
      dietMeal: typeof A("diet_meal") === "string" ? (A("diet_meal") as string) : null,
    });
  }

  // ---- 汇总与判定 ----
  const total = (t: Record<Field, { n: number; ok: number }>) => {
    let n = 0, okc = 0;
    for (const v of Object.values(t)) { n += v.n; okc += v.ok; }
    return { n, ok: okc, pct: n ? okc / n : 0 };
  };
  const gT = total(glmScore);
  const jT = total(jevScore);
  const actJ = jevScore["activity"] ?? { n: 0, ok: 0 };
  const actG = glmScore["activity"] ?? { n: 0, ok: 0 };
  const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
  const passOverall = gT.n > 0 && jT.pct >= gT.pct * 0.95;
  const passActivity = actJ.n > 0 && actJ.ok / actJ.n >= 0.8;
  const verdict = passOverall && passActivity ? "✅ 达标（可进入 shadow）" : "❌ 未达标（止步归档）";

  // ---- 耗时统计（ms：avg / P50 / P95 / min / max）----
  const stats = (ms: Record<number, number>) => {
    const arr = Object.values(ms).filter((x) => x > 0).sort((a, b) => a - b);
    if (!arr.length) return null;
    const q = (p: number) => arr[Math.min(arr.length - 1, Math.floor(arr.length * p))];
    const sum = arr.reduce((a, b) => a + b, 0);
    return { n: arr.length, avg: Math.round(sum / arr.length), p50: q(0.5), p95: q(0.95), min: arr[0], max: arr[arr.length - 1], total: sum };
  };
  const gMs = stats(glmMs);
  const jMs = stats(jevMs);
  const msRow = (label: string, s: ReturnType<typeof stats>) =>
    s ? `| ${label} | ${s.avg} | ${s.p50} | ${s.p95} | ${s.min} | ${s.max} | ${s.total} |` : `| ${label} | —（缓存无耗时数据，--glm-live 重跑获取） | — | — | — | — | — |`;
  const speedup = gMs && jMs && jMs.avg > 0 ? (gMs.avg / jMs.avg).toFixed(0) : null;

  const fieldRows = [...new Set([...Object.keys(glmScore), ...Object.keys(jevScore)])]
    .map((f) => {
      const g = glmScore[f] ?? { n: 0, ok: 0 };
      const j = jevScore[f] ?? { n: 0, ok: 0 };
      return `| ${f} | ${j.ok}/${j.n}（${pct(j.n ? j.ok / j.n : 0)}） | ${g.ok}/${g.n}（${pct(g.n ? g.ok / g.n : 0)}） |`;
    })
    .join("\n");

  const report = `# Jev PoC 对照评测报告（REQ-003 3-B）

| 项 | 值 |
|---|---|
| 日期 | ${new Date().toISOString().slice(0, 10)} |
| 测试集 | packages/ai/testset/poc-20.json（${cases.length} 句真实记录） |
| 模型 | Jev：${process.env.JEV_MODEL ?? "jev-latest"}；GLM：${process.env.GLM_MODEL ?? "glm-5.3-flash"} |
| 固定当前时间 | ${NOW_LABEL}（与 poc:live 同基准） |
| Jev 响应 | ${jevOkCount}/${cases.length} 句成功 |
| 评分口径 | 闭集字段两引擎同尺；开放词汇（人名/标题）不参评 |

## 达标判定（FR-B1）

| 指标 | 阈值 | 实测 | 判定 |
|---|---|---|---|
| 闭集整体准确率（Jev） | ≥ GLM × 95% | ${pct(jT.pct)} vs GLM ${pct(gT.pct)}（门槛 ${pct(gT.pct * 0.95)}，${jT.ok}/${jT.n} 对 ${gT.ok}/${gT.n}） | ${passOverall ? "✅" : "❌"} |
| activity 单独准确率 | ≥ 80% | ${pct(actJ.n ? actJ.ok / actJ.n : 0)}（${actJ.ok}/${actJ.n}） | ${passActivity ? "✅" : "❌"} |
| **结论** | | | **${verdict}** |

## 分字段对照

| 字段 | Jev | GLM |
|---|---|---|
${fieldRows}

## 调用耗时对照（同 46 句，各自单次调用，毫秒）

Jev = 单次并行回答 13 个闭集问题；GLM = 单次五域全量抽取（含 JSON 生成）。生产同场景下两种调用是互替的。

| 引擎 | 平均 | P50 | P95 | 最小 | 最大 | 总耗时 |
|---|---|---|---|---|---|---|
${msRow("Jev（jev-latest）", jMs)}
${msRow("GLM（五域抽取）", gMs)}

${speedup ? `**同场景平均耗时比：GLM ≈ Jev 的 ${speedup} 倍。**` : ""}

## 分歧样本（Jev 答错的字段，前 ${Math.min(divergences.length, 40)} 条）

| # | 句子 | 字段 | Jev 答案 | 期望 |
|---|---|---|---|---|
${divergences.slice(0, 40).join("\n")}
`;

  const outPath = join(here, "../../../docs/requirements/003-综合迭代/04-Jev-PoC报告.md");
  writeFileSync(outPath, report, "utf8");
  console.log("\n" + report.split("\n").slice(0, 22).join("\n"));
  console.log(`\n报告已写入：${outPath}`);
  process.exit(0);
}

await main();

import { test } from "node:test";
